window.BADBEAR_REPETICION_DATA = {"examen":{"1":{"id":1,"tipo":"examen","titulo":"Pregunta 1","tema":"PARTE 1: CASOS CLÍNICOS DE ALTO NIVEL Y FISIOPATOLOGÍA","frente":"Paciente masculino de 24 años consulta por erupción en cara que empeora tras ingerir bebidas calientes y exposición solar. Al examen presenta eritema persistente en mejillas y nariz, pápulas y pústulas inflamatorias. No se observan comedones. ¿Cuál es el diagnóstico más probable?","opciones":[{"letra":"A","texto":"Acné vulgar papulopustuloso"},{"letra":"B","texto":"Rosácea papulopustulosa"},{"letra":"C","texto":"Dermatitis perioral"},{"letra":"D","texto":"Lupus eritematoso sistémico"}],"respuesta":"B) Rosácea papulopustulosa","explicacion":"El eritema centrofacial persistente, el empeoramiento con calor y sol y las lesiones inflamatorias sin comedones orientan a rosácea papulopustulosa. La ausencia de comedones es especialmente útil para separarla del acné vulgar.","fija":"Rosácea: eritema centrofacial + flushing + pápulo-pústulas sin comedones.","href":"examenes.html?pregunta=1"},"2":{"id":2,"tipo":"examen","titulo":"Pregunta 2","tema":"PARTE 1: CASOS CLÍNICOS DE ALTO NIVEL Y FISIOPATOLOGÍA","frente":"Lactante de 4 meses es llevado a consulta por erupción eritematosa y descamativa en cuero cabelludo, surco nasogeniano y área del pañal respetando pliegues. No presenta prurito significativo. ¿Cuál es el diagnóstico más probable?","opciones":[{"letra":"A","texto":"Dermatitis atópica"},{"letra":"B","texto":"Dermatitis seborreica"},{"letra":"C","texto":"Psoriasis infantil"},{"letra":"D","texto":"Impétigo ampolloso"}],"respuesta":"B) Dermatitis seborreica","explicacion":"En un lactante, la descamación en cuero cabelludo y zonas seborreicas con poco prurito es típica de dermatitis seborreica. La dermatitis atópica suele ser mucho más pruriginosa y en lactantes predomina en mejillas y superficies extensoras.","fija":"Dermatitis seborreica del lactante: escama grasa y poco prurito.","href":"examenes.html?pregunta=2"},"3":{"id":3,"tipo":"examen","titulo":"Pregunta 3","tema":"PARTE 1: CASOS CLÍNICOS DE ALTO NIVEL Y FISIOPATOLOGÍA","frente":"Paciente varón de 45 años con antecedente de consumo crónico de alcohol se presenta con ampollas tenues y fragilidad cutánea en el dorso de las manos, asociadas a hipertricosis facial y hiperpigmentación. Las ampollas rompen fácilmente dejando erosiones. ¿Cuál es la sospecha diagnóstica?","opciones":[{"letra":"A","texto":"Pénfigo vulgar"},{"letra":"B","texto":"Porfiria cutánea tarda"},{"letra":"C","texto":"Penfigoide ampolloso"},{"letra":"D","texto":"Dermatitis herpetiforme"}],"respuesta":"B) Porfiria cutánea tarda","explicacion":"La fragilidad cutánea y las ampollas en dorso de manos, asociadas a hipertricosis facial e hiperpigmentación en un adulto con consumo crónico de alcohol, son clásicas de porfiria cutánea tarda. La fotosensibilidad y el aumento de uroporfirinas explican el patrón en áreas expuestas.","fija":"Porfiria cutánea tarda: fragilidad y ampollas en dorso de manos + hipertricosis.","href":"examenes.html?pregunta=3"},"4":{"id":4,"tipo":"examen","titulo":"Pregunta 4","tema":"PARTE 1: CASOS CLÍNICOS DE ALTO NIVEL Y FISIOPATOLOGÍA","frente":"Una mujer de 32 años presenta pápulas poligonales, pruriginosas, de color violáceo en las superficies de flexión de las muñecas. Al examen minucioso de las lesiones se aprecian finas líneas blanquecinas en la superficie. ¿Cómo se denomina este hallazgo patognomónico?","opciones":[{"letra":"A","texto":"Signo de Nikolsky"},{"letra":"B","texto":"Estrías de Wickham"},{"letra":"C","texto":"Fenómeno de Koebner"},{"letra":"D","texto":"Signo de Auspitz"}],"respuesta":"B) Estrías de Wickham","explicacion":"Las finas líneas blanquecinas sobre pápulas violáceas y pruriginosas corresponden a estrías de Wickham, un hallazgo característico del liquen plano. Nikolsky se relaciona con fragilidad epidérmica y Auspitz con psoriasis.","fija":"Estrías de Wickham = liquen plano.","href":"examenes.html?pregunta=4"},"5":{"id":5,"tipo":"examen","titulo":"Pregunta 5","tema":"PARTE 1: CASOS CLÍNICOS DE ALTO NIVEL Y FISIOPATOLOGÍA","frente":"En la exploración física de un paciente con sospecha de psoriasis se realiza el raspado metódico de Brocq sobre una placa eritematosa. Tras la desprendimiento de una fina escama se observa un punteado hemorrágico microscópico. ¿Qué estructura histológica explica este fenómeno (Signo de Auspitz)?","opciones":[{"letra":"A","texto":"Acantosis con elongación de crestas interpapilares"},{"letra":"B","texto":"Papilomatosis con adelgazamiento del epitelio suprapapilar y capilares dilatados"},{"letra":"C","texto":"Microabscesos de Munro-Sabouraud"},{"letra":"D","texto":"Hiperqueratosis ortoqueratósica"}],"respuesta":"B) Papilomatosis con adelgazamiento del epitelio suprapapilar y capilares dilatados","explicacion":"El signo de Auspitz se explica por el adelgazamiento del epitelio suprapapilar sobre papilas dérmicas con capilares dilatados y superficiales. Al retirar la escama se traumatizan esos capilares y aparece el punteado hemorrágico.","fija":"Auspitz: capilares dilatados bajo epitelio suprapapilar adelgazado.","href":"examenes.html?pregunta=5"},"6":{"id":6,"tipo":"examen","titulo":"Pregunta 6","tema":"PARTE 1: CASOS CLÍNICOS DE ALTO NIVEL Y FISIOPATOLOGÍA","frente":"Escolar de 7 años presenta en cara costras amarillentas gruesas similares a la miel (melicéricas) situadas sobre una base eritematosa alrededor de los orificios nasales. No presenta síntomas sistémicos. ¿Cuál es el tratamiento tópico de elección de primera línea?","opciones":[{"letra":"A","texto":"Gentamicina en crema"},{"letra":"B","texto":"Mupirocina al 2% en crema o ungüento"},{"letra":"C","texto":"Neomicina tópica"},{"letra":"D","texto":"Ketoconazol al 2% en crema"}],"respuesta":"B) Mupirocina al 2% en crema o ungüento","explicacion":"El impétigo no ampolloso localizado se trata de primera línea con mupirocina tópica cuando la extensión es limitada. Las costras melicéricas perinasales son un dato clínico clásico.","fija":"Impétigo limitado: mupirocina tópica.","href":"examenes.html?pregunta=6"},"7":{"id":7,"tipo":"examen","titulo":"Pregunta 7","tema":"PARTE 1: CASOS CLÍNICOS DE ALTO NIVEL Y FISIOPATOLOGÍA","frente":"Varón de 68 años con antecedente de fallo cardíaco presenta una placa eritematosa, caliente, dolorosa y con bordes mal definidos en la pierna derecha, acompañada de fiebre y escalofríos. Se objetiva puerta de entrada por tiña pedis interdigital. ¿Cuál es la capa histológica cutánea primordialmente comprometida?","opciones":[{"letra":"A","texto":"Epidermis superficial"},{"letra":"B","texto":"Estrato córneo"},{"letra":"C","texto":"Dermis profunda y tejido celular subcutáneo"},{"letra":"D","texto":"Submucosa muscular"}],"respuesta":"C) Dermis profunda y tejido celular subcutáneo","explicacion":"La descripción corresponde a celulitis, una infección que compromete dermis profunda y tejido celular subcutáneo. Los bordes mal definidos, calor, dolor y fiebre la diferencian de procesos más superficiales.","fija":"Celulitis: dermis profunda + tejido celular subcutáneo.","href":"examenes.html?pregunta=7"},"8":{"id":8,"tipo":"examen","titulo":"Pregunta 8","tema":"PARTE 1: CASOS CLÍNICOS DE ALTO NIVEL Y FISIOPATOLOGÍA","frente":"Paciente inmunosuprimido de 52 años desarrolla ampollas flácidas sobre piel aparentemente sana que se rompen fácilmente dejando áreas desnudadas dolorosas. La tracción ligera sobre la piel perilesional provoca el desprendimiento epidérmico (Nikolsky positivo). La biopsia revela acantólisis suprabasal. ¿Contra qué estructura van dirigidos los autoanticuerpos?","opciones":[{"letra":"A","texto":"Colágeno tipo VII"},{"letra":"B","texto":"Desmogleína 3"},{"letra":"C","texto":"Proteína BP180"},{"letra":"D","texto":"Desmogleína 1 exclusivamente"}],"respuesta":"B) Desmogleína 3","explicacion":"La acantólisis suprabasal con ampollas flácidas y Nikolsky positivo orienta a pénfigo vulgar. Los autoanticuerpos se dirigen principalmente contra desmogleína 3, y en formas mucocutáneas también puede participar desmogleína 1.","fija":"Pénfigo vulgar: anti-desmogleína 3; acantólisis suprabasal.","href":"examenes.html?pregunta=8"},"9":{"id":9,"tipo":"examen","titulo":"Pregunta 9","tema":"PARTE 1: CASOS CLÍNICOS DE ALTO NIVEL Y FISIOPATOLOGÍA","frente":"Paciente de 75 años consulta por ampollas tensas, resistentes a la rotura, sobre una base eritematosa urticariforme en abdomen y muslos. El signo de Nikolsky es negativo y la histología muestra ampolla subepidérmica con infiltrado rico en eosinófilos. ¿Cuál es el diagnóstico?","opciones":[{"letra":"A","texto":"Pénfigo vulgar"},{"letra":"B","texto":"Penfigoide ampolloso"},{"letra":"C","texto":"Dermatitis herpetiforme"},{"letra":"D","texto":"Epidermolisis ampollosa adquirida"}],"respuesta":"B) Penfigoide ampolloso","explicacion":"Las ampollas tensas, Nikolsky negativo y la separación subepidérmica con eosinófilos son características del penfigoide ampolloso. En el pénfigo vulgar las ampollas son flácidas e intraepidérmicas.","fija":"Penfigoide ampolloso: ampolla tensa, subepidérmica y eosinófilos.","href":"examenes.html?pregunta=9"},"10":{"id":10,"tipo":"examen","titulo":"Pregunta 10","tema":"PARTE 1: CASOS CLÍNICOS DE ALTO NIVEL Y FISIOPATOLOGÍA","frente":"Niño de 5 años es traído a urgencias por presentar descamación epidérmica generalizada que semeja una quemadura, con signo de Nikolsky positivo en todo el cuerpo, pero sin afectación de mucosas. El cuadro inició tras una infección ótica. ¿Cuál es la toxina causante y su diana específica?","opciones":[{"letra":"A","texto":"Toxina del TSST-1 de S. aureus – Desmogleína 3"},{"letra":"B","texto":"Toxina exfoliativa (ET-A/ET-B) de S. aureus – Desmogleína 1"},{"letra":"C","texto":"Exotoxina A de S. pyogenes – Filagrina"},{"letra":"D","texto":"Toxina alfa de Clostridium – Cadherina E"}],"respuesta":"B) Toxina exfoliativa (ET-A/ET-B) de S. aureus – Desmogleína 1","explicacion":"El síndrome de piel escaldada estafilocócica se debe a toxinas exfoliativas ET-A/ET-B de Staphylococcus aureus que clivan desmogleína 1. Por eso hay desprendimiento superficial y típicamente se respetan las mucosas.","fija":"SSSS: toxina exfoliativa contra desmogleína 1.","href":"examenes.html?pregunta=10"},"11":{"id":11,"tipo":"examen","titulo":"Pregunta 11","tema":"PARTE 1: CASOS CLÍNICOS DE ALTO NIVEL Y FISIOPATOLOGÍA","frente":"Paciente varón de 28 años presenta en tronco múltiples máculas hipopigmentadas finamente descamativas que se hacen más evidentes tras el verano. El examen con luz de Wood muestra fluorescencia amarillo-dorada. ¿Cuál es el agente causal de esta patología?","opciones":[{"letra":"A","texto":"Trichophyton rubrum"},{"letra":"B","texto":"Malassezia furfur"},{"letra":"C","texto":"Microsporum canis"},{"letra":"D","texto":"Epidermophyton floccosum"}],"respuesta":"B) Malassezia furfur","explicacion":"La pitiriasis versicolor es producida por Malassezia, una levadura lipofílica de la flora cutánea. Las máculas finamente descamativas del tronco y la fluorescencia amarillenta apoyan el diagnóstico.","fija":"Pitiriasis versicolor: Malassezia.","href":"examenes.html?pregunta=11"},"12":{"id":12,"tipo":"examen","titulo":"Pregunta 12","tema":"PARTE 1: CASOS CLÍNICOS DE ALTO NIVEL Y FISIOPATOLOGÍA","frente":"En la pitiriasis versicolor, ¿qué hallazgo microscópico característico se observa al realizar un examen directo con KOH al 10% del raspado de la lesión?","opciones":[{"letra":"A","texto":"Hifas hialinas tabicadas en ángulo recto"},{"letra":"B","texto":"Esporas en racimo con hifas cortas y curvadas (\"imagen en espagueti con albóndigas\")"},{"letra":"C","texto":"Pseudohifas con blastoconidias"},{"letra":"D","texto":"Artroconidias dispuestas en cadena"}],"respuesta":"B) Esporas en racimo con hifas cortas y curvadas (\"imagen en espagueti con albóndigas\")","explicacion":"En KOH, Malassezia muestra levaduras agrupadas junto con hifas cortas y curvadas, el patrón clásico descrito como “espagueti con albóndigas”. Este hallazgo es característico de pitiriasis versicolor.","fija":"KOH en pitiriasis versicolor: hifas cortas + levaduras en racimos.","href":"examenes.html?pregunta=12"},"13":{"id":13,"tipo":"examen","titulo":"Pregunta 13","tema":"PARTE 1: CASOS CLÍNICOS DE ALTO NIVEL Y FISIOPATOLOGÍA","frente":"Paciente femenina de 22 años acude por placas eritematosas ovaladas con escama fina periférica en tórax y espalda, distribuidas en \"árbol de Navidad\". Refiere que hace 10 días presentó una placa similar pero más grande en el abdomen. ¿Cómo se denomina esa lesión inicial?","opciones":[{"letra":"A","texto":"Lesión diana"},{"letra":"B","texto":"Placa heráldica"},{"letra":"C","texto":"Mancha en aceite"},{"letra":"D","texto":"Medallón de Auspitz"}],"respuesta":"B) Placa heráldica","explicacion":"La lesión inicial grande que precede a la erupción secundaria de pitiriasis rosada se denomina placa heráldica. Días después aparecen lesiones menores siguiendo líneas de tensión del tronco.","fija":"Pitiriasis rosada: placa heráldica antes del patrón en árbol de Navidad.","href":"examenes.html?pregunta=13"},"14":{"id":14,"tipo":"examen","titulo":"Pregunta 14","tema":"PARTE 1: CASOS CLÍNICOS DE ALTO NIVEL Y FISIOPATOLOGÍA","frente":"Varón de 40 años acude por prurito intenso de predominio nocturno que afecta a él y a su cónyuge. Al examen se aprecian pápulas eritematosas, excoriaciones y surcos finos interdigitales en manos y muñecas. ¿Cuál es la conducta terapéutica de primera línea adecuada?","opciones":[{"letra":"A","texto":"Permetrina al 5% en crema aplicada en todo el cuerpo desde el cuello hacia abajo, repitiendo a los 7 días"},{"letra":"B","texto":"Ivermectina oral dosis única solo al paciente"},{"letra":"C","texto":"Corticoides tópicos de alta potencia durante 14 días"},{"letra":"D","texto":"Lindano al 1% en champú diario por 3 días"}],"respuesta":"A) Permetrina al 5% en crema aplicada en todo el cuerpo desde el cuello hacia abajo, repitiendo a los 7 días","explicacion":"La escabiosis clásica se trata con permetrina al 5% aplicada de cuello hacia abajo y repetida a los 7 días; además deben tratarse simultáneamente los convivientes. Una sola dosis de ivermectina al paciente no constituye el esquema estándar completo.","fija":"Escabiosis: permetrina 5% y tratar contactos.","href":"examenes.html?pregunta=14"},"15":{"id":15,"tipo":"examen","titulo":"Pregunta 15","tema":"PARTE 1: CASOS CLÍNICOS DE ALTO NIVEL Y FISIOPATOLOGÍA","frente":"¿Cuál es el hallazgo patognomónico que confirma la escabiosis al examen dermoscópico o microscópico?","opciones":[{"letra":"A","texto":"Signo de la bujía"},{"letra":"B","texto":"Signo del \"ala de delta\" o estructura en estela que corresponde a la hembra de Sarcoptes scabiei"},{"letra":"C","texto":"Células acantolíticas"},{"letra":"D","texto":"Fenómeno de Koebner"}],"respuesta":"B) Signo del \"ala de delta\" o estructura en estela que corresponde a la hembra de Sarcoptes scabiei","explicacion":"La dermoscopia puede mostrar el signo del ala delta o jet con estela, que representa la porción anterior del ácaro al final del surco. Es un hallazgo muy característico de Sarcoptes scabiei.","fija":"Ala delta al final del surco = Sarcoptes scabiei.","href":"examenes.html?pregunta=15"},"16":{"id":16,"tipo":"examen","titulo":"Pregunta 16","tema":"PARTE 1: CASOS CLÍNICOS DE ALTO NIVEL Y FISIOPATOLOGÍA","frente":"Paciente mujer de 35 años con antecedentes de asma presenta placas eritematosas, secas y muy pruriginosas en los pliegues flexores de los codos y huecos poplíteos. Histológicamente se asocia a mutaciones en el gen de una proteína de barrera cutánea. ¿De qué proteína se trata?","opciones":[{"letra":"A","texto":"Involucrina"},{"letra":"B","texto":"Filagrina"},{"letra":"C","texto":"Loricrina"},{"letra":"D","texto":"Queratina 5"}],"respuesta":"B) Filagrina","explicacion":"La filagrina es una proteína esencial de la barrera epidérmica y sus variantes de pérdida de función se asocian fuertemente con dermatitis atópica. Esto favorece xerosis, mayor pérdida transepidérmica de agua y penetración de alérgenos.","fija":"Dermatitis atópica: defecto de barrera por filagrina.","href":"examenes.html?pregunta=16"},"17":{"id":17,"tipo":"examen","titulo":"Pregunta 17","tema":"PARTE 1: CASOS CLÍNICOS DE ALTO NIVEL Y FISIOPATOLOGÍA","frente":"Un paciente de 60 años consulta por pápula perlada en la mejilla derecha con telangiectasias en la superficie y un centro levemente ulcerado. La biopsia confirma el carcinoma cutáneo más frecuente. ¿Cuál es?","opciones":[{"letra":"A","texto":"Carcinoma espinocelular"},{"letra":"B","texto":"Melanoma nodular"},{"letra":"C","texto":"Carcinoma basocelular"},{"letra":"D","texto":"Keratoacantoma"}],"respuesta":"C) Carcinoma basocelular","explicacion":"Una pápula perlada con telangiectasias y ulceración central en la cara es la presentación clásica del carcinoma basocelular, el cáncer cutáneo más frecuente. Su crecimiento suele ser lento y la metástasis es excepcional.","fija":"CBC: pápula perlada + telangiectasias + ulceración.","href":"examenes.html?pregunta=17"},"18":{"id":18,"tipo":"examen","titulo":"Pregunta 18","tema":"PARTE 1: CASOS CLÍNICOS DE ALTO NIVEL Y FISIOPATOLOGÍA","frente":"En el carcinoma espinocelular (epidermoide) de piel, ¿cuál es la lesión previa o premaligna más común?","opciones":[{"letra":"A","texto":"Leucoplasia oral"},{"letra":"B","texto":"Queratosis actínica"},{"letra":"C","texto":"Nevo displásico"},{"letra":"D","texto":"Léntigo solar"}],"respuesta":"B) Queratosis actínica","explicacion":"La queratosis actínica es la lesión precursora más frecuente del carcinoma epidermoide cutáneo en piel fotoexpuesta. Representa displasia de queratinocitos inducida por radiación ultravioleta acumulativa.","fija":"Queratosis actínica = lesión premaligna clásica del CEC.","href":"examenes.html?pregunta=18"},"19":{"id":19,"tipo":"examen","titulo":"Pregunta 19","tema":"PARTE 1: CASOS CLÍNICOS DE ALTO NIVEL Y FISIOPATOLOGÍA","frente":"Paciente con sospecha de melanoma en brazo. Al evaluarlo se aplica la regla del ABCDE. ¿Qué representa la letra \"E\" en este algoritmo clínico de tamizaje?","opciones":[{"letra":"A","texto":"Eritema periférico"},{"letra":"B","texto":"Evolución (cambio en tamaño, forma o color)"},{"letra":"C","texto":"Espesor de Breslow"},{"letra":"D","texto":"Extensión microscópica"}],"respuesta":"B) Evolución (cambio en tamaño, forma o color)","explicacion":"En la regla ABCDE del melanoma, la E corresponde a evolución: cambios recientes en tamaño, forma, color, síntomas o relieve. La evolución suele ser una de las pistas más sensibles para sospechar transformación maligna.","fija":"ABCDE: E = evolución.","href":"examenes.html?pregunta=19"},"20":{"id":20,"tipo":"examen","titulo":"Pregunta 20","tema":"PARTE 1: CASOS CLÍNICOS DE ALTO NIVEL Y FISIOPATOLOGÍA","frente":"¿Cuál es el parámetro pronóstico histológico más importante en el melanoma cutáneo primario sin metástasis a distancia?","opciones":[{"letra":"A","texto":"Nivel de Clark"},{"letra":"B","texto":"Índice de Breslow (profundidad en milímetros)"},{"letra":"C","texto":"Presencia de ulceración exclusivamente"},{"letra":"D","texto":"Tasa mitótica celular"}],"respuesta":"B) Índice de Breslow (profundidad en milímetros)","explicacion":"El espesor de Breslow, medido en milímetros desde la capa granulosa hasta la célula tumoral más profunda, es el principal factor pronóstico histológico del melanoma localizado. Se correlaciona estrechamente con riesgo de metástasis y supervivencia.","fija":"Melanoma: Breslow es el factor pronóstico histológico clave.","href":"examenes.html?pregunta=20"},"21":{"id":21,"tipo":"examen","titulo":"Pregunta 21","tema":"PARTE 2: ANATOMÍA, FISIOLOGÍA Y LESIONES ELEMENTALES","frente":"¿En qué estrato de la epidermis se lleva a cabo la mitosis activa de las células madre de los queratinocitos?","opciones":[{"letra":"A","texto":"Estrato córneo"},{"letra":"B","texto":"Estrato espinoso"},{"letra":"C","texto":"Estrato basal o germinativo"},{"letra":"D","texto":"Estrato granuloso"}],"respuesta":"C) Estrato basal o germinativo","explicacion":"La proliferación de queratinocitos basales y células madre epidérmicas ocurre principalmente en el estrato basal o germinativo. Desde allí las células migran y se diferencian hacia capas más superficiales.","fija":"Mitosis epidérmica activa: estrato basal.","href":"examenes.html?pregunta=21"},"22":{"id":22,"tipo":"examen","titulo":"Pregunta 22","tema":"PARTE 2: ANATOMÍA, FISIOLOGÍA Y LESIONES ELEMENTALES","frente":"¿Qué estrato epidérmico está presente únicamente en zonas de piel gruesa como las palmas de las manos y las plantas de los pies?","opciones":[{"letra":"A","texto":"Estrato granuloso"},{"letra":"B","texto":"Estrato lúcido"},{"letra":"C","texto":"Estrato basal"},{"letra":"D","texto":"Estrato espinoso"}],"respuesta":"B) Estrato lúcido","explicacion":"El estrato lúcido se observa en piel gruesa de palmas y plantas, entre el granuloso y el córneo. No está presente de forma definida en la piel fina habitual.","fija":"Estrato lúcido: exclusivo de piel gruesa.","href":"examenes.html?pregunta=22"},"23":{"id":23,"tipo":"examen","titulo":"Pregunta 23","tema":"PARTE 2: ANATOMÍA, FISIOLOGÍA Y LESIONES ELEMENTALES","frente":"Células epidérmicas dendríticas derivadas de la médula ósea que participan activamente en la presentación de antígenos e inmunidad cutánea:","opciones":[{"letra":"A","texto":"Células de Merkel"},{"letra":"B","texto":"Melanocitos"},{"letra":"C","texto":"Células de Langerhans"},{"letra":"D","texto":"Corneocitos"}],"respuesta":"C) Células de Langerhans","explicacion":"Las células de Langerhans son células dendríticas presentadoras de antígeno de origen hematopoyético que participan en inmunovigilancia cutánea. Se localizan principalmente en el estrato espinoso.","fija":"Langerhans = presentación de antígeno en epidermis.","href":"examenes.html?pregunta=23"},"24":{"id":24,"tipo":"examen","titulo":"Pregunta 24","tema":"PARTE 2: ANATOMÍA, FISIOLOGÍA Y LESIONES ELEMENTALES","frente":"Células de la capa basal de la epidermis que actúan como mecanorreceptores para el tacto fino:","opciones":[{"letra":"A","texto":"Células de Langerhans"},{"letra":"B","texto":"Células de Merkel"},{"letra":"C","texto":"Queratinocitos"},{"letra":"D","texto":"Adipocitos"}],"respuesta":"B) Células de Merkel","explicacion":"Las células de Merkel se encuentran en la capa basal y funcionan como mecanorreceptores asociados a terminaciones nerviosas para tacto fino y presión ligera. No son células presentadoras de antígeno.","fija":"Merkel: mecanorrecepción táctil en estrato basal.","href":"examenes.html?pregunta=24"},"25":{"id":25,"tipo":"examen","titulo":"Pregunta 25","tema":"PARTE 2: ANATOMÍA, FISIOLOGÍA Y LESIONES ELEMENTALES","frente":"El componente estructural principal que une a los queratinocitos adyacentes entre sí en el estrato espinoso y cuya alteración genera acantólisis es:","opciones":[{"letra":"A","texto":"Hemidesmosoma"},{"letra":"B","texto":"Desmosoma"},{"letra":"C","texto":"Unión estrecha (tight junction)"},{"letra":"D","texto":"Unión GAP"}],"respuesta":"B) Desmosoma","explicacion":"Los desmosomas unen queratinocitos entre sí y son particularmente evidentes en el estrato espinoso. La pérdida de adhesión desmosómica produce acantólisis, como ocurre en el pénfigo.","fija":"Desmosoma: adhesión queratinocito-queratinocito.","href":"examenes.html?pregunta=25"},"26":{"id":26,"tipo":"examen","titulo":"Pregunta 26","tema":"PARTE 2: ANATOMÍA, FISIOLOGÍA Y LESIONES ELEMENTALES","frente":"Los hemidesmosomas son estructuras de unión celular que fijan a los queratinocitos basales con:","opciones":[{"letra":"A","texto":"El estrato espinoso"},{"letra":"B","texto":"La membrana basal / dermis"},{"letra":"C","texto":"Los vasos sanguíneos"},{"letra":"D","texto":"El tallo piloso"}],"respuesta":"B) La membrana basal / dermis","explicacion":"Los hemidesmosomas anclan los queratinocitos basales a la membrana basal y, a través de ella, a la dermis. Son distintos de los desmosomas, que unen células epidérmicas entre sí.","fija":"Hemidesmosoma: anclaje del queratinocito basal a membrana basal.","href":"examenes.html?pregunta=26"},"27":{"id":27,"tipo":"examen","titulo":"Pregunta 27","tema":"PARTE 2: ANATOMÍA, FISIOLOGÍA Y LESIONES ELEMENTALES","frente":"¿Cuál es el principal tipo de colágeno presente en la dermis reticular adulta que le otorga fuerza de tensión a la piel?","opciones":[{"letra":"A","texto":"Colágeno Tipo I"},{"letra":"B","texto":"Colágeno Tipo II"},{"letra":"C","texto":"Colágeno Tipo IV"},{"letra":"D","texto":"Colágeno Tipo VII"}],"respuesta":"A) Colágeno Tipo I","explicacion":"El colágeno tipo I es el componente colágeno predominante de la dermis reticular y aporta resistencia tensil. El tipo IV forma redes en membranas basales y el tipo VII participa en fibrillas de anclaje.","fija":"Dermis reticular: predomina colágeno tipo I.","href":"examenes.html?pregunta=27"},"28":{"id":28,"tipo":"examen","titulo":"Pregunta 28","tema":"PARTE 2: ANATOMÍA, FISIOLOGÍA Y LESIONES ELEMENTALES","frente":"Corpúsculo sensitivo localizado en la dermis papilar encargado de percibir el tacto fino y la discriminación entre dos puntos:","opciones":[{"letra":"A","texto":"Corpúsculo de Pacini"},{"letra":"B","texto":"Corpúsculo de Meissner"},{"letra":"C","texto":"Corpúsculo de Ruffini"},{"letra":"D","texto":"Corpúsculo de Krause"}],"respuesta":"B) Corpúsculo de Meissner","explicacion":"Los corpúsculos de Meissner se ubican en papilas dérmicas de piel glabra y detectan tacto fino y discriminación de dos puntos. Los de Pacini responden a presión profunda y vibración de alta frecuencia.","fija":"Meissner: tacto fino; Pacini: vibración profunda.","href":"examenes.html?pregunta=28"},"29":{"id":29,"tipo":"examen","titulo":"Pregunta 29","tema":"PARTE 2: ANATOMÍA, FISIOLOGÍA Y LESIONES ELEMENTALES","frente":"Corpúsculo mecano-receptor especializado en la detección de presión profunda y vibraciones de alta frecuencia, ubicado en la dermis profunda e hipodermis:","opciones":[{"letra":"A","texto":"Corpúsculo de Meissner"},{"letra":"B","texto":"Corpúsculo de Pacini"},{"letra":"C","texto":"Disco de Merkel"},{"letra":"D","texto":"Bulbo de Krause"}],"respuesta":"B) Corpúsculo de Pacini","explicacion":"Los corpúsculos de Pacini se localizan en dermis profunda e hipodermis y están especializados en presión profunda y vibraciones rápidas. Su estructura laminar les permite responder a cambios mecánicos rápidos.","fija":"Pacini: presión profunda y vibración de alta frecuencia.","href":"examenes.html?pregunta=29"},"30":{"id":30,"tipo":"examen","titulo":"Pregunta 30","tema":"PARTE 2: ANATOMÍA, FISIOLOGÍA Y LESIONES ELEMENTALES","frente":"Las glándulas sudoríparas apocrinas se diferencian de las ecrinas en que las apocrinas:","opciones":[{"letra":"A","texto":"Desembocan directamente en la superficie folicular y funcionan desde el nacimiento"},{"letra":"B","texto":"Tienen secreción merocrina pura y regulan la temperatura"},{"letra":"C","texto":"Desembocan habitualmente en el folículo piloso y se activan en la pubertad"},{"letra":"D","texto":"Están presentes en toda la superficie corporal sin excepción"}],"respuesta":"C) Desembocan habitualmente en el folículo piloso y se activan en la pubertad","explicacion":"Las glándulas apocrinas desembocan habitualmente en folículos pilosos y se activan funcionalmente en la pubertad, sobre todo en axilas y región anogenital. Las ecrinas desembocan en la superficie y son centrales para termorregulación.","fija":"Apocrinas: folículo piloso y actividad desde la pubertad.","href":"examenes.html?pregunta=30"},"31":{"id":31,"tipo":"examen","titulo":"Pregunta 31","tema":"PARTE 2: ANATOMÍA, FISIOLOGÍA Y LESIONES ELEMENTALES","frente":"¿Cuál es el tipo de secreción de la glándula sebácea donde la célula entera se desintegra para liberar el sebo?","opciones":[{"letra":"A","texto":"Merocrina"},{"letra":"B","texto":"Apocrina"},{"letra":"C","texto":"Holocrina"},{"letra":"D","texto":"Paracrina"}],"respuesta":"C) Holocrina","explicacion":"La glándula sebácea utiliza secreción holocrina: la célula se llena de lípidos y se desintegra para liberar su contenido. Es el ejemplo clásico de secreción holocrina.","fija":"Glándula sebácea = secreción holocrina.","href":"examenes.html?pregunta=31"},"32":{"id":32,"tipo":"examen","titulo":"Pregunta 32","tema":"PARTE 2: ANATOMÍA, FISIOLOGÍA Y LESIONES ELEMENTALES","frente":"Una lesión elemental primaria, plana, no palpable, caracterizada por un cambio de color de la piel menor de 1 cm se denomina:","opciones":[{"letra":"A","texto":"Pápula"},{"letra":"B","texto":"Mácula"},{"letra":"C","texto":"Placa"},{"letra":"D","texto":"Nódulo"}],"respuesta":"B) Mácula","explicacion":"Una mácula es un cambio circunscrito de color, plano y no palpable, clásicamente menor de 1 cm. Cuando el cambio plano es mayor suele denominarse parche.","fija":"Mácula: lesión plana no palpable con cambio de color.","href":"examenes.html?pregunta=32"},"33":{"id":33,"tipo":"examen","titulo":"Pregunta 33","tema":"PARTE 2: ANATOMÍA, FISIOLOGÍA Y LESIONES ELEMENTALES","frente":"Lesión elevada, sólida, circumscrita, de menos de 1 cm de diámetro que cura sin dejar cicatriz:","opciones":[{"letra":"A","texto":"Nódulo"},{"letra":"B","texto":"Pápula"},{"letra":"C","texto":"Ampolla"},{"letra":"D","texto":"Roncha"}],"respuesta":"B) Pápula","explicacion":"La pápula es una elevación sólida, circunscrita y pequeña, generalmente menor de 1 cm. Un nódulo es más profundo y suele comprometer dermis o hipodermis.","fija":"Pápula: sólida, superficial y <1 cm.","href":"examenes.html?pregunta=33"},"34":{"id":34,"tipo":"examen","titulo":"Pregunta 34","tema":"PARTE 2: ANATOMÍA, FISIOLOGÍA Y LESIONES ELEMENTALES","frente":"Elevación sólida, circunscrita de la piel, de más de 1 cm de diámetro, que frecuentemente se forma por la confluencia de pápulas:","opciones":[{"letra":"A","texto":"Mácula"},{"letra":"B","texto":"Nódulo"},{"letra":"C","texto":"Placa"},{"letra":"D","texto":"Vesícula"}],"respuesta":"C) Placa","explicacion":"Una placa es una lesión elevada de superficie amplia, generalmente mayor de 1 cm, que puede originarse por confluencia de pápulas. Su extensión lateral supera su profundidad.","fija":"Placa: elevación amplia >1 cm, a menudo por confluencia de pápulas.","href":"examenes.html?pregunta=34"},"35":{"id":35,"tipo":"examen","titulo":"Pregunta 35","tema":"PARTE 2: ANATOMÍA, FISIOLOGÍA Y LESIONES ELEMENTALES","frente":"Lesión sólida, profunda, palpable en dermis o hipodermis, que al evolucionar puede curar dejando cicatriz:","opciones":[{"letra":"A","texto":"Pápula"},{"letra":"B","texto":"Nódulo"},{"letra":"C","texto":"Vesícula"},{"letra":"D","texto":"Habón"}],"respuesta":"B) Nódulo","explicacion":"El nódulo es una lesión sólida y profunda localizada en dermis o tejido subcutáneo; por su profundidad puede dejar cicatriz. Esto lo diferencia de la pápula, que es más superficial.","fija":"Nódulo: lesión sólida profunda en dermis/hipodermis.","href":"examenes.html?pregunta=35"},"36":{"id":36,"tipo":"examen","titulo":"Pregunta 36","tema":"PARTE 2: ANATOMÍA, FISIOLOGÍA Y LESIONES ELEMENTALES","frente":"Lesión de contenido líquido seroso o hemorrágico, elevación menor de 0.5 - 1 cm de diámetro:","opciones":[{"letra":"A","texto":"Pústula"},{"letra":"B","texto":"Ampolla (flictena)"},{"letra":"C","texto":"Vesícula"},{"letra":"D","texto":"Quiste"}],"respuesta":"C) Vesícula","explicacion":"La vesícula es una elevación pequeña con contenido líquido, habitualmente menor de 1 cm. Cuando la colección líquida es mayor se denomina ampolla o flictena.","fija":"Vesícula = contenido líquido pequeño; ampolla = mayor tamaño.","href":"examenes.html?pregunta=36"},"37":{"id":37,"tipo":"examen","titulo":"Pregunta 37","tema":"PARTE 2: ANATOMÍA, FISIOLOGÍA Y LESIONES ELEMENTALES","frente":"Lesión de contenido líquido purulento desde su origen:","opciones":[{"letra":"A","texto":"Vesícula"},{"letra":"B","texto":"Pústula"},{"letra":"C","texto":"Ampolla"},{"letra":"D","texto":"Habón"}],"respuesta":"B) Pústula","explicacion":"La pústula contiene material purulento desde su origen. Puede ser folicular o no folicular y no debe confundirse con una vesícula que secundariamente se infecta.","fija":"Pústula: contenido purulento.","href":"examenes.html?pregunta=37"},"38":{"id":38,"tipo":"examen","titulo":"Pregunta 38","tema":"PARTE 2: ANATOMÍA, FISIOLOGÍA Y LESIONES ELEMENTALES","frente":"Placa eritematodematosa, evanescente (dura menos de 24 horas en la misma ubicación), muy pruriginosa, secundaria a edema de la dermis superficial:","opciones":[{"letra":"A","texto":"Comedón"},{"letra":"B","texto":"Habón o roncha"},{"letra":"C","texto":"Tubérculo"},{"letra":"D","texto":"Escama"}],"respuesta":"B) Habón o roncha","explicacion":"El habón es una elevación edematosa, pruriginosa y evanescente debida a edema de dermis superficial; cada lesión suele durar menos de 24 horas. Es la lesión elemental de la urticaria.","fija":"Habón: edema dérmico superficial y duración <24 h.","href":"examenes.html?pregunta=38"},"39":{"id":39,"tipo":"examen","titulo":"Pregunta 39","tema":"PARTE 2: ANATOMÍA, FISIOLOGÍA Y LESIONES ELEMENTALES","frente":"Lesión elemental secundaria producida por desecación de exudados, sangre o pus sobre la piel:","opciones":[{"letra":"A","texto":"Escama"},{"letra":"B","texto":"Costra"},{"letra":"C","texto":"Escara"},{"letra":"D","texto":"Licuenificación"}],"respuesta":"B) Costra","explicacion":"La costra se forma por desecación de suero, sangre, pus o una mezcla de estos sobre la superficie cutánea. La escama, en cambio, corresponde a láminas de estrato córneo desprendidas.","fija":"Costra = exudado desecado.","href":"examenes.html?pregunta=39"},"40":{"id":40,"tipo":"examen","titulo":"Pregunta 40","tema":"PARTE 2: ANATOMÍA, FISIOLOGÍA Y LESIONES ELEMENTALES","frente":"Pérdida de sustancia epidérmica superficial que cura sin dejar cicatriz:","opciones":[{"letra":"A","texto":"Ulcera"},{"letra":"B","texto":"Erosión o excoriación"},{"letra":"C","texto":"Fisura"},{"letra":"D","texto":"Cicatriz queloide"}],"respuesta":"B) Erosión o excoriación","explicacion":"La erosión es una pérdida superficial de epidermis que no rebasa la membrana basal y por ello cura sin cicatriz. La úlcera es más profunda y puede dejar cicatriz.","fija":"Erosión: pérdida epidérmica superficial sin cicatriz.","href":"examenes.html?pregunta=40"},"41":{"id":41,"tipo":"examen","titulo":"Pregunta 41","tema":"PARTE 3: DERMATOSIS INFLAMATORIAS E INFECCIOSAS","frente":"Pérdida de sustancia cutánea profunda que afecta epidermis, dermis e incluso hipodermis, dejando cicatriz al curar:","opciones":[{"letra":"A","texto":"Erosión"},{"letra":"B","texto":"Excoriación"},{"letra":"C","texto":"Úlcera"},{"letra":"D","texto":"Fisura"}],"respuesta":"C) Úlcera","explicacion":"La úlcera implica pérdida de sustancia que atraviesa epidermis y compromete dermis, incluso tejido subcutáneo. Al destruir dermis suele reparar con cicatriz.","fija":"Úlcera: pérdida profunda de sustancia y cicatriz.","href":"examenes.html?pregunta=41"},"42":{"id":42,"tipo":"examen","titulo":"Pregunta 42","tema":"PARTE 3: DERMATOSIS INFLAMATORIAS E INFECCIOSAS","frente":"Engrosamiento de la piel con exageración del cuadriculado normal y acentuación de sus pliegues, secundario al rascado crónico:","opciones":[{"letra":"A","texto":"Atrofia"},{"letra":"B","texto":"Esclerosis"},{"letra":"C","texto":"Licuenificación"},{"letra":"D","texto":"Cicatriz"}],"respuesta":"C) Licuenificación","explicacion":"La liquenificación es el engrosamiento cutáneo con acentuación de pliegues y cuadriculado secundario a rascado o fricción crónicos. Es frecuente en dermatosis intensamente pruriginosas.","fija":"Rascado crónico → liquenificación.","href":"examenes.html?pregunta=42"},"43":{"id":43,"tipo":"examen","titulo":"Pregunta 43","tema":"PARTE 3: DERMATOSIS INFLAMATORIAS E INFECCIOSAS","frente":"Lesión elemental secundaria caracterizada por tejido necrótico delimitado que el cuerpo tiende a separar de los tejidos sanos:","opciones":[{"letra":"A","texto":"Costra"},{"letra":"B","texto":"Escara"},{"letra":"C","texto":"Escama"},{"letra":"D","texto":"Nódulo"}],"respuesta":"B) Escara","explicacion":"La escara es tejido necrótico seco y delimitado que se separa del tejido viable. No debe confundirse con una costra, que es material exudativo seco sobre la superficie.","fija":"Escara = tejido necrótico delimitado.","href":"examenes.html?pregunta=43"},"44":{"id":44,"tipo":"examen","titulo":"Pregunta 44","tema":"PARTE 3: DERMATOSIS INFLAMATORIAS E INFECCIOSAS","frente":"El fenómeno de Koebner se define como:","opciones":[{"letra":"A","texto":"La aparición de ampollas tras la presión tangencial de la piel"},{"letra":"B","texto":"La formación de lesiones características de una dermatosis sobre piel sana previamente traumatizada"},{"letra":"C","texto":"El sangrado puntual tras el desprendimiento de una escama"},{"letra":"D","texto":"El eritema persistente a la vitropresión"}],"respuesta":"B) La formación de lesiones características de una dermatosis sobre piel sana previamente traumatizada","explicacion":"El fenómeno de Koebner consiste en la aparición de lesiones propias de una dermatosis en zonas de traumatismo cutáneo previo. Se observa clásicamente en psoriasis, liquen plano y vitíligo.","fija":"Koebner: lesiones de la enfermedad sobre piel traumatizada.","href":"examenes.html?pregunta=44"},"45":{"id":45,"tipo":"examen","titulo":"Pregunta 45","tema":"PARTE 3: DERMATOSIS INFLAMATORIAS E INFECCIOSAS","frente":"¿En cuál de las siguientes patologías NO es característico observar el Fenómeno de Koebner?","opciones":[{"letra":"A","texto":"Psoriasis"},{"letra":"B","texto":"Liquen plano"},{"letra":"C","texto":"Vitíligo"},{"letra":"D","texto":"Pénfigo vulgar"}],"respuesta":"D) Pénfigo vulgar","explicacion":"Psoriasis, liquen plano y vitíligo son dermatosis clásicamente asociadas al fenómeno de Koebner. El pénfigo vulgar no es una de las asociaciones prototípicas del fenómeno isomórfico.","fija":"Koebner clásico: psoriasis, liquen plano y vitíligo.","href":"examenes.html?pregunta=45"},"46":{"id":46,"tipo":"examen","titulo":"Pregunta 46","tema":"PARTE 3: DERMATOSIS INFLAMATORIAS E INFECCIOSAS","frente":"La presencia del Signo de Nikolsky positivo es característico de:","opciones":[{"letra":"A","texto":"Penfigoide ampolloso"},{"letra":"B","texto":"Pénfigo vulgar y Síndrome de Necrólisis Epidérmica Tóxica (NET)"},{"letra":"C","texto":"Dermatitis herpetiforme"},{"letra":"D","texto":"Eritema nodoso"}],"respuesta":"B) Pénfigo vulgar y Síndrome de Necrólisis Epidérmica Tóxica (NET)","explicacion":"Nikolsky positivo refleja pérdida de cohesión epidérmica y puede observarse en pénfigo vulgar y en necrolisis epidérmica tóxica. En el penfigoide ampolloso, por su ampolla subepidérmica tensa, suele ser negativo.","fija":"Nikolsky positivo: pénfigo vulgar y NET, entre otros.","href":"examenes.html?pregunta=46"},"47":{"id":47,"tipo":"examen","titulo":"Pregunta 47","tema":"PARTE 3: DERMATOSIS INFLAMATORIAS E INFECCIOSAS","frente":"¿Cuál es la bacteria causal más frecuente del Impétigo contagioso no ampolloso?","opciones":[{"letra":"A","texto":"Pseudomonas aeruginosa"},{"letra":"B","texto":"Staphylococcus aureus y Streptococcus pyogenes"},{"letra":"C","texto":"Propionibacterium acnes"},{"letra":"D","texto":"Corynebacterium minutissimum"}],"respuesta":"B) Staphylococcus aureus y Streptococcus pyogenes","explicacion":"El impétigo no ampolloso se relaciona principalmente con Staphylococcus aureus y Streptococcus pyogenes. La epidemiología actual favorece con frecuencia a S. aureus, pero ambos son agentes clásicos.","fija":"Impétigo no ampolloso: S. aureus y S. pyogenes.","href":"examenes.html?pregunta=47"},"48":{"id":48,"tipo":"examen","titulo":"Pregunta 48","tema":"PARTE 3: DERMATOSIS INFLAMATORIAS E INFECCIOSAS","frente":"En la Erisipela, la infección afecta característicamente a:","opciones":[{"letra":"A","texto":"Dermis superficial y vasos linfáticos cutáneos, con bordes muy bien delimitados"},{"letra":"B","texto":"Hipodermis exclusivamente sin compromiso de la dermis"},{"letra":"C","texto":"Musculatura y fascia profunda"},{"letra":"D","texto":"Estrato córneo únicamente"}],"respuesta":"A) Dermis superficial y vasos linfáticos cutáneos, con bordes muy bien delimitados","explicacion":"La erisipela compromete dermis superficial y vasos linfáticos cutáneos, por eso suele verse como una placa brillante, elevada y con límites muy nítidos. La celulitis se extiende más profundamente y presenta bordes menos definidos.","fija":"Erisipela: dermis superficial + linfáticos, borde nítido.","href":"examenes.html?pregunta=48"},"49":{"id":49,"tipo":"examen","titulo":"Pregunta 49","tema":"PARTE 3: DERMATOSIS INFLAMATORIAS E INFECCIOSAS","frente":"Agente etiológico principal de la Erisipela:","opciones":[{"letra":"A","texto":"Staphylococcus aureus"},{"letra":"B","texto":"Streptococcus pyogenes (Estreptococo betahemolítico del grupo A)"},{"letra":"C","texto":"Escherichia coli"},{"letra":"D","texto":"Bacteroides fragilis"}],"respuesta":"B) Streptococcus pyogenes (Estreptococo betahemolítico del grupo A)","explicacion":"Streptococcus pyogenes, estreptococo betahemolítico del grupo A, es el agente clásico de la erisipela. El cuadro suele ser agudo, febril y con una placa bien delimitada.","fija":"Erisipela: S. pyogenes.","href":"examenes.html?pregunta=49"},"50":{"id":50,"tipo":"examen","titulo":"Pregunta 50","tema":"PARTE 3: DERMATOSIS INFLAMATORIAS E INFECCIOSAS","frente":"El Ectima se diferencia del Impétigo en que el Ectima:","opciones":[{"letra":"A","texto":"Es producido únicamente por virus"},{"letra":"B","texto":"Es una forma ulcerada que penetra hasta la dermis dejando cicatriz"},{"letra":"C","texto":"No produce costras"},{"letra":"D","texto":"Es una afección exclusiva de recién nacidos"}],"respuesta":"B) Es una forma ulcerada que penetra hasta la dermis dejando cicatriz","explicacion":"El ectima es una infección bacteriana más profunda que el impétigo y produce una lesión ulcerada que penetra en dermis. Esa mayor profundidad explica que pueda dejar cicatriz.","fija":"Ectima = forma ulcerada profunda que deja cicatriz.","href":"examenes.html?pregunta=50"},"51":{"id":51,"tipo":"examen","titulo":"Pregunta 51","tema":"PARTE 3: DERMATOSIS INFLAMATORIAS E INFECCIOSAS","frente":"La foliculitis se define como la infección e inflamación de:","opciones":[{"letra":"A","texto":"La glándula sudorípara ecrina"},{"letra":"B","texto":"El ostium del folículo piloso"},{"letra":"C","texto":"El tejido celular subcutáneo llano"},{"letra":"D","texto":"La uña y el lecho ungueal"}],"respuesta":"B) El ostium del folículo piloso","explicacion":"La foliculitis es inflamación e infección del ostium o porción superficial del folículo piloso. Clínicamente se observan pústulas centradas por un pelo.","fija":"Foliculitis: infección del folículo piloso.","href":"examenes.html?pregunta=51"},"52":{"id":52,"tipo":"examen","titulo":"Pregunta 52","tema":"PARTE 3: DERMATOSIS INFLAMATORIAS E INFECCIOSAS","frente":"El Ántrax cutáneo (estafilocócico) consiste en:","opciones":[{"letra":"A","texto":"La infección por Bacillus anthracis"},{"letra":"B","texto":"La confluencia de varios forúnculos vecinos con afectación de múltiples folículos y necrosis profunda"},{"letra":"C","texto":"Una micosis profunda del pie"},{"letra":"D","texto":"Una manifestación de sífilis terciaria"}],"respuesta":"B) La confluencia de varios forúnculos vecinos con afectación de múltiples folículos y necrosis profunda","explicacion":"El ántrax estafilocócico o carbunco es la confluencia de varios forúnculos contiguos con compromiso de múltiples folículos y necrosis profunda. No debe confundirse con el carbunco por Bacillus anthracis.","fija":"Ántrax estafilocócico = varios forúnculos confluyentes.","href":"examenes.html?pregunta=52"},"53":{"id":53,"tipo":"examen","titulo":"Pregunta 53","tema":"PARTE 3: DERMATOSIS INFLAMATORIAS E INFECCIOSAS","frente":"Paciente varón de 30 años presenta lesión eritematosa en axila, con presencia de placas hiperpigmentadas y maceración, que muestra fluorescencia rojo coral a la Luz de Wood. ¿Cuál es el diagnóstico?","opciones":[{"letra":"A","texto":"Tiña cruris"},{"letra":"B","texto":"Eritrasma"},{"letra":"C","texto":"Candidiasis cutánea"},{"letra":"D","texto":"Intertrigo estreptocócico"}],"respuesta":"B) Eritrasma","explicacion":"La fluorescencia rojo coral con luz de Wood en un pliegue es muy característica de eritrasma, producido por Corynebacterium minutissimum. La porfirina bacteriana es responsable de esa fluorescencia.","fija":"Eritrasma: fluorescencia rojo coral.","href":"examenes.html?pregunta=53"},"54":{"id":54,"tipo":"examen","titulo":"Pregunta 54","tema":"PARTE 3: DERMATOSIS INFLAMATORIAS E INFECCIOSAS","frente":"¿Cuál es el microorganismo causal del Eritrasma?","opciones":[{"letra":"A","texto":"Malassezia globosa"},{"letra":"B","texto":"Corynebacterium minutissimum"},{"letra":"C","texto":"Microsporum audouinii"},{"letra":"D","texto":"Pseudomonas aeruginosa"}],"respuesta":"B) Corynebacterium minutissimum","explicacion":"Corynebacterium minutissimum es el agente del eritrasma. Es una infección superficial de pliegues que puede simular tiña o candidiasis.","fija":"Eritrasma = Corynebacterium minutissimum.","href":"examenes.html?pregunta=54"},"55":{"id":55,"tipo":"examen","titulo":"Pregunta 55","tema":"PARTE 3: DERMATOSIS INFLAMATORIAS E INFECCIOSAS","frente":"El \"Síndrome de la piel escaldada estafilocócica\" ocurre con mayor frecuencia en:","opciones":[{"letra":"A","texto":"Ancianos diabéticos"},{"letra":"B","texto":"Neonatos y niños menores de 5 años"},{"letra":"C","texto":"Adultos jóvenes deportistas"},{"letra":"D","texto":"Mujeres embarazadas"}],"respuesta":"B) Neonatos y niños menores de 5 años","explicacion":"El síndrome de piel escaldada estafilocócica afecta principalmente a neonatos y niños pequeños por menor capacidad de depuración renal de las toxinas exfoliativas y falta de anticuerpos neutralizantes.","fija":"SSSS predomina en neonatos y menores de 5 años.","href":"examenes.html?pregunta=55"},"56":{"id":56,"tipo":"examen","titulo":"Pregunta 56","tema":"PARTE 3: DERMATOSIS INFLAMATORIAS E INFECCIOSAS","frente":"En la lepra lepromatosa, la respuesta inmune del huésped se caracteriza por ser:","opciones":[{"letra":"A","texto":"Predominantemente Celular (Th1) eficiente"},{"letra":"B","texto":"Predominantemente Humoral (Th2) ineficaz con alta carga bacilar"},{"letra":"C","texto":"Autolimitada y no contagiosa"},{"letra":"D","texto":"Negativa para bacilos en el examen microscópico"}],"respuesta":"B) Predominantemente Humoral (Th2) ineficaz con alta carga bacilar","explicacion":"La lepra lepromatosa aparece cuando predomina una respuesta humoral Th2 con pobre inmunidad celular frente a Mycobacterium leprae. Esto permite una alta carga bacilar y enfermedad difusa.","fija":"Lepra lepromatosa: Th2, alta carga bacilar.","href":"examenes.html?pregunta=56"},"57":{"id":57,"tipo":"examen","titulo":"Pregunta 57","tema":"PARTE 3: DERMATOSIS INFLAMATORIAS E INFECCIOSAS","frente":"La forma de Lepra Tuberculoide se caracteriza por:","opciones":[{"letra":"A","texto":"Placas hipocromicas anésticas bien delimitadas con escasos bacilos (paucibacilar)"},{"letra":"B","texto":"Facies leonina y nódulos difusos"},{"letra":"C","texto":"Baciloscopía altamente positiva"},{"letra":"D","texto":"Ausencia de compromiso nervioso periférico"}],"respuesta":"A) Placas hipocromicas anésticas bien delimitadas con escasos bacilos (paucibacilar)","explicacion":"La lepra tuberculoide expresa buena inmunidad celular, baja carga bacilar y pocas lesiones bien delimitadas, hipocrómicas o eritematosas, con pérdida de sensibilidad por compromiso neural.","fija":"Tuberculoide: paucibacilar, pocas placas anestésicas bien delimitadas.","href":"examenes.html?pregunta=57"},"58":{"id":58,"tipo":"examen","titulo":"Pregunta 58","tema":"PARTE 3: DERMATOSIS INFLAMATORIAS E INFECCIOSAS","frente":"¿Cuál es el tratamiento de elección recomendado por la OMS para la Lepra Multibacilar?","opciones":[{"letra":"A","texto":"Penicilina G benzatínica por 1 año"},{"letra":"B","texto":"Rifampicina, Dapsona y Clofazimina"},{"letra":"C","texto":"Doxiciclina más Metronidazol"},{"letra":"D","texto":"Ciprofloxacino en monoterapia"}],"respuesta":"B) Rifampicina, Dapsona y Clofazimina","explicacion":"La poliquimioterapia para lepra multibacilar combina rifampicina, dapsona y clofazimina. El uso combinado reduce resistencia y trata eficazmente la alta carga bacilar.","fija":"Lepra multibacilar: rifampicina + dapsona + clofazimina.","href":"examenes.html?pregunta=58"},"59":{"id":59,"tipo":"examen","titulo":"Pregunta 59","tema":"PARTE 3: DERMATOSIS INFLAMATORIAS E INFECCIOSAS","frente":"La Tiña Capitis producida por Microsporum canis se caracteriza clínicamente por:","opciones":[{"letra":"A","texto":"Múltiples placas pequeñas con pelos rotos a diferente nivel"},{"letra":"B","texto":"Placa única o grande de alopecia con cabellos rotos al mismo nivel que fluoresce color verde al examen con Luz de Wood"},{"letra":"C","texto":"Alopecia cicatrizal irreversible inmediata"},{"letra":"D","texto":"Ausencia total de escamas"}],"respuesta":"B) Placa única o grande de alopecia con cabellos rotos al mismo nivel que fluoresce color verde al examen con Luz de Wood","explicacion":"La tiña capitis microspórica por Microsporum canis suele producir una placa grande con pelos quebrados a nivel similar y puede fluorescer verdosa con luz de Wood. El patrón tricofítico suele dar múltiples placas pequeñas.","fija":"Microsporum canis: placa grande y fluorescencia verdosa.","href":"examenes.html?pregunta=59"},"60":{"id":60,"tipo":"examen","titulo":"Pregunta 60","tema":"PARTE 3: DERMATOSIS INFLAMATORIAS E INFECCIOSAS","frente":"El Querión de Celso es una forma inflamatoria grave de:","opciones":[{"letra":"A","texto":"Psoriasis en cuero cabelludo"},{"letra":"B","texto":"Tiña del cuero cabelludo (Tiña capitis) con supuración y riesgo de alopecia cicatrizal"},{"letra":"C","texto":"Foliculitis por Pseudomonas"},{"letra":"D","texto":"Impétigo ampollar"}],"respuesta":"B) Tiña del cuero cabelludo (Tiña capitis) con supuración y riesgo de alopecia cicatrizal","explicacion":"El querión de Celso es una reacción inflamatoria intensa de tiña capitis con tumefacción, supuración y riesgo de alopecia cicatrizal. Requiere tratamiento antifúngico sistémico.","fija":"Querión = tiña capitis inflamatoria y supurativa.","href":"examenes.html?pregunta=60"},"61":{"id":61,"tipo":"examen","titulo":"Pregunta 61","tema":"PARTE 4: MICOLOGÍA, VIROLOGÍA Y PARASITOLOGÍA CUTÁNEA","frente":"El hongo causante más frecuente de la Tiña pedis y Tiña unguium (onicomicosis) a nivel mundial es:","opciones":[{"letra":"A","texto":"Candida albicans"},{"letra":"B","texto":"Trichophyton rubrum"},{"letra":"C","texto":"Epidermophyton floccosum"},{"letra":"D","texto":"Microsporum gypseum"}],"respuesta":"B) Trichophyton rubrum","explicacion":"Trichophyton rubrum es el dermatofito más frecuente en tiña pedis y onicomicosis a nivel mundial. Tiene gran afinidad por queratina y puede producir infección crónica.","fija":"T. rubrum: principal dermatofito de pie y uña.","href":"examenes.html?pregunta=61"},"62":{"id":62,"tipo":"examen","titulo":"Pregunta 62","tema":"PARTE 4: MICOLOGÍA, VIROLOGÍA Y PARASITOLOGÍA CUTÁNEA","frente":"La manifestación clínica de la Candidiasis intertriginosa muestra característicamente:","opciones":[{"letra":"A","texto":"Placas secas con escamas plateadas"},{"letra":"B","texto":"Eritema brillante, maceración, fisura central y presencia de \"lesiones satélites\" pustulosas"},{"letra":"C","texto":"Lesiones en diana y ampollas tensas"},{"letra":"D","texto":"Manchas acrómicas con pérdida de sensibilidad"}],"respuesta":"B) Eritema brillante, maceración, fisura central y presencia de \"lesiones satélites\" pustulosas","explicacion":"La candidiasis intertriginosa produce eritema brillante, maceración y fisuras en pliegues, con pápulas o pústulas satélite periféricas. Las lesiones satélite son una pista especialmente útil.","fija":"Candidiasis de pliegues: eritema húmedo + lesiones satélite.","href":"examenes.html?pregunta=62"},"63":{"id":63,"tipo":"examen","titulo":"Pregunta 63","tema":"PARTE 4: MICOLOGÍA, VIROLOGÍA Y PARASITOLOGÍA CUTÁNEA","frente":"El virus del Herpes Simple Tipo 1 (VHS-1) permanece en estado latente principalmente en:","opciones":[{"letra":"A","texto":"Los queratinocitos del estrato basal"},{"letra":"B","texto":"El ganglio sensitivo del trigémino (V par craneal)"},{"letra":"C","texto":"Los ganglios linfáticos axilares"},{"letra":"D","texto":"Los mastocitos dérmicos"}],"respuesta":"B) El ganglio sensitivo del trigémino (V par craneal)","explicacion":"VHS-1 establece latencia en ganglios sensitivos, clásicamente el ganglio trigémino en infecciones orolabiales. La reactivación viaja por el nervio sensitivo hacia la piel o mucosa.","fija":"VHS-1 orolabial: latencia en ganglio trigémino.","href":"examenes.html?pregunta=63"},"64":{"id":64,"tipo":"examen","titulo":"Pregunta 64","tema":"PARTE 4: MICOLOGÍA, VIROLOGÍA Y PARASITOLOGÍA CUTÁNEA","frente":"El citodiagnóstico de Tzanck obtenido del raspado de la base de una ampolla herpética muestra característicamente:","opciones":[{"letra":"A","texto":"Acantocitos aislados sin cambios nucleares"},{"letra":"B","texto":"Células gigantes multinucleadas con inclusiones intranucleares"},{"letra":"C","texto":"Microabscesos de Munro"},{"letra":"D","texto":"Infiltrado masivo de eosinófilos"}],"respuesta":"B) Células gigantes multinucleadas con inclusiones intranucleares","explicacion":"El frotis de Tzanck en infección herpética puede mostrar células gigantes multinucleadas con moldeamiento nuclear e inclusiones intranucleares. No diferencia con precisión entre VHS y VVZ.","fija":"Tzanck herpético: células gigantes multinucleadas.","href":"examenes.html?pregunta=64"},"65":{"id":65,"tipo":"examen","titulo":"Pregunta 65","tema":"PARTE 4: MICOLOGÍA, VIROLOGÍA Y PARASITOLOGÍA CUTÁNEA","frente":"El Herpes Zóster es causado por la reactivación del virus:","opciones":[{"letra":"A","texto":"Herpes Virus Humano 8"},{"letra":"B","texto":"Virus de la Varicela-Zóster (VVZ) latente en los ganglios de la raíz dorsal"},{"letra":"C","texto":"Epstein-Barr Virus"},{"letra":"D","texto":"Citomegalovirus"}],"respuesta":"B) Virus de la Varicela-Zóster (VVZ) latente en los ganglios de la raíz dorsal","explicacion":"El herpes zóster representa reactivación del virus varicela-zóster latente en ganglios sensitivos, especialmente ganglios de raíz dorsal o de pares craneales. La erupción sigue el territorio del nervio afectado.","fija":"Zóster = reactivación de VVZ latente en ganglio sensitivo.","href":"examenes.html?pregunta=65"},"66":{"id":66,"tipo":"examen","titulo":"Pregunta 66","tema":"PARTE 4: MICOLOGÍA, VIROLOGÍA Y PARASITOLOGÍA CUTÁNEA","frente":"La distribución clínica característica del eritema vesicular doloroso en el Herpes Zóster es:","opciones":[{"letra":"A","texto":"Difusa y simétrica en ambas extremidades"},{"letra":"B","texto":"Dermatómica, unilateral, sin cruzar la línea media"},{"letra":"C","texto":"Exclusivamente palmoplantar"},{"letra":"D","texto":"Flexora generalizada"}],"respuesta":"B) Dermatómica, unilateral, sin cruzar la línea media","explicacion":"El herpes zóster típicamente produce dolor y vesículas agrupadas en un dermatoma unilateral que no cruza la línea media. Ese patrón anatómico es una de sus claves diagnósticas.","fija":"Zóster: distribución dermatomal unilateral.","href":"examenes.html?pregunta=66"},"67":{"id":67,"tipo":"examen","titulo":"Pregunta 67","tema":"PARTE 4: MICOLOGÍA, VIROLOGÍA Y PARASITOLOGÍA CUTÁNEA","frente":"Las pápulas umbilicales, firmes, de aspecto perlado, causadas por un Poxvirus se diagnostican como:","opciones":[{"letra":"A","texto":"Verrugas vulgares"},{"letra":"B","texto":"Molusco contagioso"},{"letra":"C","texto":"Cóndilomas acuminados"},{"letra":"D","texto":"Poliposis cutánea"}],"respuesta":"B) Molusco contagioso","explicacion":"El molusco contagioso por poxvirus produce pápulas perladas, firmes y umbilicadas. La depresión central es una pista clínica muy característica.","fija":"Pápula perlada umbilicada = molusco contagioso.","href":"examenes.html?pregunta=67"},"68":{"id":68,"tipo":"examen","titulo":"Pregunta 68","tema":"PARTE 4: MICOLOGÍA, VIROLOGÍA Y PARASITOLOGÍA CUTÁNEA","frente":"Las verrugas vulgares son causadas por la infección epitelial por:","opciones":[{"letra":"A","texto":"Virus del Papiloma Humano (VPH)"},{"letra":"B","texto":"Virus Coxsackie A16"},{"letra":"C","texto":"Parvovirus B19"},{"letra":"D","texto":"Moluscipoxvirus"}],"respuesta":"A) Virus del Papiloma Humano (VPH)","explicacion":"Las verrugas vulgares son proliferaciones epidérmicas causadas por virus del papiloma humano. Distintos tipos de VPH muestran tropismo por piel o mucosas.","fija":"Verruga vulgar = infección por VPH.","href":"examenes.html?pregunta=68"},"69":{"id":69,"tipo":"examen","titulo":"Pregunta 69","tema":"PARTE 4: MICOLOGÍA, VIROLOGÍA Y PARASITOLOGÍA CUTÁNEA","frente":"¿Qué serotipos del Virus del Papiloma Humano (VPH) están asociados con mayor frecuencia al desarrollo de condilomas acuminados genitales benignos?","opciones":[{"letra":"A","texto":"VPH 16 y 18"},{"letra":"B","texto":"VPH 6 y 11"},{"letra":"C","texto":"VPH 1 y 2"},{"letra":"D","texto":"VPH 31 y 33"}],"respuesta":"B) VPH 6 y 11","explicacion":"Los condilomas acuminados benignos se asocian sobre todo con VPH de bajo riesgo 6 y 11. Los tipos 16 y 18 se relacionan con lesiones intraepiteliales y cáncer.","fija":"Condiloma benigno: VPH 6 y 11.","href":"examenes.html?pregunta=69"},"70":{"id":70,"tipo":"examen","titulo":"Pregunta 70","tema":"PARTE 4: MICOLOGÍA, VIROLOGÍA Y PARASITOLOGÍA CUTÁNEA","frente":"¿Qué serotipos de VPH son de alto riesgo oncogénico para carcinoma epidermoide de cérvix y ano?","opciones":[{"letra":"A","texto":"VPH 6 y 11"},{"letra":"B","texto":"VPH 16 y 18"},{"letra":"C","texto":"VPH 5 y 8"},{"letra":"D","texto":"VPH 2 y 4"}],"respuesta":"B) VPH 16 y 18","explicacion":"Los VPH 16 y 18 son los tipos de alto riesgo oncogénico más relevantes para carcinoma de cérvix y ano. Integran oncogenes virales que alteran p53 y Rb.","fija":"Alto riesgo oncogénico: VPH 16 y 18.","href":"examenes.html?pregunta=70"},"71":{"id":71,"tipo":"examen","titulo":"Pregunta 71","tema":"PARTE 4: MICOLOGÍA, VIROLOGÍA Y PARASITOLOGÍA CUTÁNEA","frente":"El eritema infeccioso (o Quinta enfermedad) se manifiesta con el signo del \"bofetón\" en cara y es causado por:","opciones":[{"letra":"A","texto":"Virus del Sarampión"},{"letra":"B","texto":"Parvovirus B19"},{"letra":"C","texto":"Virus HHV-6"},{"letra":"D","texto":"Enterovirus 71"}],"respuesta":"B) Parvovirus B19","explicacion":"El eritema infeccioso o quinta enfermedad es causado por parvovirus B19. El exantema facial en “mejillas abofeteadas” es su presentación clásica en niños.","fija":"Quinta enfermedad = Parvovirus B19.","href":"examenes.html?pregunta=71"},"72":{"id":72,"tipo":"examen","titulo":"Pregunta 72","tema":"PARTE 4: MICOLOGÍA, VIROLOGÍA Y PARASITOLOGÍA CUTÁNEA","frente":"El Exantema Súbito (Roseola infantil o Sexta enfermedad) se caracteriza por fiebre alta de 3 días que cede al aparecer el exantema, siendo producido por:","opciones":[{"letra":"A","texto":"Virus Herpes Humano 6 (VHH-6)"},{"letra":"B","texto":"Virus de la Rubéola"},{"letra":"C","texto":"Coxsackie A6"},{"letra":"D","texto":"Adenovirus tipo 7"}],"respuesta":"A) Virus Herpes Humano 6 (VHH-6)","explicacion":"La roseola o exantema súbito se asocia principalmente con VHH-6. La característica clásica es fiebre alta por varios días que cede justo cuando aparece el exantema.","fija":"Roseola: VHH-6; exantema al ceder la fiebre.","href":"examenes.html?pregunta=72"},"73":{"id":73,"tipo":"examen","titulo":"Pregunta 73","tema":"PARTE 4: MICOLOGÍA, VIROLOGÍA Y PARASITOLOGÍA CUTÁNEA","frente":"Paciente con pediculosis capitis. ¿Cuál es el tratamiento de primera línea de elección?","opciones":[{"letra":"A","texto":"Permetrina al 1% en loción"},{"letra":"B","texto":"Griseofulvina oral"},{"letra":"C","texto":"Corticoide tópico en crema"},{"letra":"D","texto":"Terbinafina tópica"}],"respuesta":"A) Permetrina al 1% en loción","explicacion":"La permetrina al 1% es un tratamiento habitual de primera línea para pediculosis capitis, junto con peinado fino y manejo de contactos y fómites según el contexto.","fija":"Pediculosis capitis: permetrina 1%.","href":"examenes.html?pregunta=73"},"74":{"id":74,"tipo":"examen","titulo":"Pregunta 74","tema":"PARTE 4: MICOLOGÍA, VIROLOGÍA Y PARASITOLOGÍA CUTÁNEA","frente":"La Pediculosis pubis (\"ladillas\") es causada por el ectoparásito:","opciones":[{"letra":"A","texto":"Pediculus humanus capitis"},{"letra":"B","texto":"Pthirus pubis"},{"letra":"C","texto":"Sarcoptes scabiei var. hominis"},{"letra":"D","texto":"Demodex folliculorum"}],"respuesta":"B) Pthirus pubis","explicacion":"La pediculosis pubis es causada por Pthirus pubis, ectoparásito adaptado al vello grueso de la región genital y otras áreas pilosas.","fija":"Ladillas = Pthirus pubis.","href":"examenes.html?pregunta=74"},"75":{"id":75,"tipo":"examen","titulo":"Pregunta 75","tema":"PARTE 4: MICOLOGÍA, VIROLOGÍA Y PARASITOLOGÍA CUTÁNEA","frente":"La Leishmaniasis cutánea (Uta) en los Andes peruanos es transmitida por la picadura de la hembra del díptero:","opciones":[{"letra":"A","texto":"Aedes aegypti"},{"letra":"B","texto":"Lutzomyia (Lutzomyia verrucarum / peruensis)"},{"letra":"C","texto":"Anopheles Darlingi"},{"letra":"D","texto":"Triatoma infestans"}],"respuesta":"B) Lutzomyia (Lutzomyia verrucarum / peruensis)","explicacion":"La leishmaniasis cutánea andina peruana se transmite por flebótomos del género Lutzomyia. La hembra infectada inocula promastigotes durante la picadura.","fija":"Leishmaniasis peruana: vector Lutzomyia.","href":"examenes.html?pregunta=75"},"76":{"id":76,"tipo":"examen","titulo":"Pregunta 76","tema":"PARTE 4: MICOLOGÍA, VIROLOGÍA Y PARASITOLOGÍA CUTÁNEA","frente":"La forma clínica de la Leishmaniasis mucocutánea (Espundia) se caracteriza por causar lesiones destructivas en:","opciones":[{"letra":"A","texto":"Cuero cabelludo y cabello"},{"letra":"B","texto":"Mucosa nasofaríngea y tabique nasal"},{"letra":"C","texto":"Uñas de manos y pies"},{"letra":"D","texto":"Plantas de los pies"}],"respuesta":"B) Mucosa nasofaríngea y tabique nasal","explicacion":"La forma mucocutánea o espundia compromete de manera destructiva la mucosa nasofaríngea y puede afectar el tabique nasal. Suele aparecer después de una lesión cutánea previa.","fija":"Espundia: destrucción de mucosa nasofaríngea.","href":"examenes.html?pregunta=76"},"77":{"id":77,"tipo":"examen","titulo":"Pregunta 77","tema":"PARTE 4: MICOLOGÍA, VIROLOGÍA Y PARASITOLOGÍA CUTÁNEA","frente":"¿Cuál es el tratamiento de primera línea para la Leishmaniasis cutánea según las guías del MINSA?","opciones":[{"letra":"A","texto":"Ivermectina oral"},{"letra":"B","texto":"Antimoniato de meglumina (Antimoniales pentavalentes) parenteral"},{"letra":"C","texto":"Ketoconazol oral"},{"letra":"D","texto":"Penicilina G procainica"}],"respuesta":"B) Antimoniato de meglumina (Antimoniales pentavalentes) parenteral","explicacion":"En el banco fuente, el esquema señalado como primera línea para leishmaniasis cutánea es un antimonial pentavalente como antimoniato de meglumina por vía parenteral. La elección real puede variar según especie, localización, gravedad y guía nacional vigente.","fija":"Leishmaniasis cutánea: antimoniales pentavalentes según el esquema del banco.","href":"examenes.html?pregunta=77"},"78":{"id":78,"tipo":"examen","titulo":"Pregunta 78","tema":"PARTE 4: MICOLOGÍA, VIROLOGÍA Y PARASITOLOGÍA CUTÁNEA","frente":"Lesión cutánea producida por la picadura de Loxosceles laeta que presenta una placa eritemato-edematosa con áreas violáceas e isquémicas (\"placa livedoide\") con tendencia a la necrosis central:","opciones":[{"letra":"A","texto":"Loxoscelismo cutáneo"},{"letra":"B","texto":"Latrodectismo"},{"letra":"C","texto":"Picadura de abeja"},{"letra":"D","texto":"Carbunco cutáneo"}],"respuesta":"A) Loxoscelismo cutáneo","explicacion":"La placa livedoide con zonas violáceas e isquémicas que progresa a necrosis central tras picadura de Loxosceles laeta es típica de loxoscelismo cutáneo.","fija":"Loxoscelismo: placa livedoide y necrosis central.","href":"examenes.html?pregunta=78"},"79":{"id":79,"tipo":"examen","titulo":"Pregunta 79","tema":"PARTE 4: MICOLOGÍA, VIROLOGÍA Y PARASITOLOGÍA CUTÁNEA","frente":"El compromiso sistémico grave en el loxoscelismo cutáneo-visceral incluye fundamentalmente:","opciones":[{"letra":"A","texto":"Parálisis flácida descendente"},{"letra":"B","texto":"Hemólisis intravascular masiva, hemoglobinuria e insuficiencia renal aguda"},{"letra":"C","texto":"Hipertensión maligna e infarto de miocardio"},{"letra":"D","texto":"Fibrosis pulmonar acelerada"}],"respuesta":"B) Hemólisis intravascular masiva, hemoglobinuria e insuficiencia renal aguda","explicacion":"El loxoscelismo sistémico puede producir hemólisis intravascular intensa, hemoglobinuria e insuficiencia renal aguda. Es una complicación potencialmente grave que requiere vigilancia hospitalaria.","fija":"Loxoscelismo visceral: hemólisis + hemoglobinuria + IRA.","href":"examenes.html?pregunta=79"},"80":{"id":80,"tipo":"examen","titulo":"Pregunta 80","tema":"PARTE 4: MICOLOGÍA, VIROLOGÍA Y PARASITOLOGÍA CUTÁNEA","frente":"El tratamiento de elección en la larva migrans cutánea causada por Ancylostoma braziliense es:","opciones":[{"letra":"A","texto":"Permetrina tópica"},{"letra":"B","texto":"Ivermectina oral o Albendazol oral"},{"letra":"C","texto":"Metronidazol oral"},{"letra":"D","texto":"Amphotericin B"}],"respuesta":"B) Ivermectina oral o Albendazol oral","explicacion":"Ivermectina o albendazol son tratamientos eficaces para larva migrans cutánea. La mejoría del prurito y detención del trayecto suelen ser rápidas tras el tratamiento.","fija":"Larva migrans cutánea: ivermectina o albendazol.","href":"examenes.html?pregunta=80"},"81":{"id":81,"tipo":"examen","titulo":"Pregunta 81","tema":"PARTE 5: PATOLOGÍA ERITEMATODESCAMATIVA Y ENFERMEDADES AMPOLLOSAS","frente":"En la Psoriasis vulgar, las placas eritematosas están cubiertas por escamas nácaradas o plateadas ubicadas característicamente en:","opciones":[{"letra":"A","texto":"Superficies de extensión (codos, rodillas, zona lumbosacra)"},{"letra":"B","texto":"Superficies de flexión (hueco poplíteo, pliegues del codo)"},{"letra":"C","texto":"Axilas e ingle únicamente"},{"letra":"D","texto":"Palmas y plantas exclusivamente"}],"respuesta":"A) Superficies de extensión (codos, rodillas, zona lumbosacra)","explicacion":"La psoriasis vulgar clásica predomina en superficies extensoras como codos y rodillas, además de cuero cabelludo y región lumbosacra. Las escamas plateadas y los bordes definidos apoyan el diagnóstico.","fija":"Psoriasis clásica: superficies extensoras.","href":"examenes.html?pregunta=81"},"82":{"id":82,"tipo":"examen","titulo":"Pregunta 82","tema":"PARTE 5: PATOLOGÍA ERITEMATODESCAMATIVA Y ENFERMEDADES AMPOLLOSAS","frente":"La alteración histopatológica caracterizada por el engrosamiento del estrato espinoso epidérmico se conoce como:","opciones":[{"letra":"A","texto":"Hyperqueratosis"},{"letra":"B","texto":"Acantosis"},{"letra":"C","texto":"Espongiosis"},{"letra":"D","texto":"Paraqueratosis"}],"respuesta":"B) Acantosis","explicacion":"El engrosamiento del estrato espinoso se denomina acantosis. Es un hallazgo histopatológico frecuente en psoriasis y otras dermatosis hiperplásicas.","fija":"Acantosis = engrosamiento del estrato espinoso.","href":"examenes.html?pregunta=82"},"83":{"id":83,"tipo":"examen","titulo":"Pregunta 83","tema":"PARTE 5: PATOLOGÍA ERITEMATODESCAMATIVA Y ENFERMEDADES AMPOLLOSAS","frente":"La presencia de núcleos celulares retenidos dentro del estrato córneo epidérmico en la psoriasis se denomina:","opciones":[{"letra":"A","texto":"Ortoqueratosis"},{"letra":"B","texto":"Paraqueratosis"},{"letra":"C","texto":"Dysqueratosis"},{"letra":"D","texto":"Acantólisis"}],"respuesta":"B) Paraqueratosis","explicacion":"La paraqueratosis es la retención de núcleos en el estrato córneo, reflejo de una queratinización acelerada. Es un hallazgo típico de psoriasis.","fija":"Paraqueratosis: núcleos retenidos en estrato córneo.","href":"examenes.html?pregunta=83"},"84":{"id":84,"tipo":"examen","titulo":"Pregunta 84","tema":"PARTE 5: PATOLOGÍA ERITEMATODESCAMATIVA Y ENFERMEDADES AMPOLLOSAS","frente":"Los cúmulos de neutrófilos en el estrato córneo o subcórneo observados en la psoriasis reciben el nombre histológico de:","opciones":[{"letra":"A","texto":"Cuerpos de Civatte"},{"letra":"B","texto":"Microabscesos de Munro-Sabouraud"},{"letra":"C","texto":"Células de Tzanck"},{"letra":"D","texto":"Cuerpos de Russell"}],"respuesta":"B) Microabscesos de Munro-Sabouraud","explicacion":"Los microabscesos de Munro son cúmulos de neutrófilos en el estrato córneo de la psoriasis. Las pústulas espongiformes de Kogoj se localizan más profundamente en epidermis.","fija":"Psoriasis: microabscesos de Munro.","href":"examenes.html?pregunta=84"},"85":{"id":85,"tipo":"examen","titulo":"Pregunta 85","tema":"PARTE 5: PATOLOGÍA ERITEMATODESCAMATIVA Y ENFERMEDADES AMPOLLOSAS","frente":"La Psoriasis en gotas (guttata) se presenta típicamente como pápulas eruptivas pequeñas tras una infección por:","opciones":[{"letra":"A","texto":"Staphylococcus aureus"},{"letra":"B","texto":"Streptococcus pyogenes (faringitis estreptocócica)"},{"letra":"C","texto":"Pseudomonas aeruginosa"},{"letra":"D","texto":"Virus de Epstein-Barr"}],"respuesta":"B) Streptococcus pyogenes (faringitis estreptocócica)","explicacion":"La psoriasis guttata suele aparecer tras una faringitis por Streptococcus pyogenes, especialmente en niños y adultos jóvenes. El brote consiste en múltiples lesiones pequeñas en tronco y extremidades.","fija":"Psoriasis guttata: antecedente de faringitis estreptocócica.","href":"examenes.html?pregunta=85"},"86":{"id":86,"tipo":"examen","titulo":"Pregunta 86","tema":"PARTE 5: PATOLOGÍA ERITEMATODESCAMATIVA Y ENFERMEDADES AMPOLLOSAS","frente":"¿Cuál de los siguientes medicamentos puede desencadenar o empeorar un brote de Psoriasis?","opciones":[{"letra":"A","texto":"Paracetamol"},{"letra":"B","texto":"Betabloqueantes, Litio y Antipalúdicos"},{"letra":"C","texto":"Amoxicilina"},{"letra":"D","texto":"Loratadina"}],"respuesta":"B) Betabloqueantes, Litio y Antipalúdicos","explicacion":"Litio, betabloqueadores y antipalúdicos son fármacos clásicos capaces de desencadenar o exacerbar psoriasis. También se reconocen otros precipitantes como retirada brusca de corticoides sistémicos.","fija":"Fármacos que empeoran psoriasis: litio, betabloqueadores y antipalúdicos.","href":"examenes.html?pregunta=86"},"87":{"id":87,"tipo":"examen","titulo":"Pregunta 87","tema":"PARTE 5: PATOLOGÍA ERITEMATODESCAMATIVA Y ENFERMEDADES AMPOLLOSAS","frente":"La artritis psoriásica afecta a un porcentaje de pacientes con psoriasis. ¿Cuál es la presentación articular periférica más común?","opciones":[{"letra":"A","texto":"Osteoartritis degenerativa"},{"letra":"B","texto":"Oligoartritis asimétrica o compromiso de articulaciones interfalángicas distales"},{"letra":"C","texto":"Artritis simétrica de grandes articulaciones exclusivamente"},{"letra":"D","texto":"Gota tofácea"}],"respuesta":"B) Oligoartritis asimétrica o compromiso de articulaciones interfalángicas distales","explicacion":"La artritis psoriásica periférica suele presentarse como oligoartritis asimétrica o con compromiso de interfalángicas distales; también puede haber dactilitis y entesitis.","fija":"Psoriásica: oligoartritis asimétrica e IF distales.","href":"examenes.html?pregunta=87"},"88":{"id":88,"tipo":"examen","titulo":"Pregunta 88","tema":"PARTE 5: PATOLOGÍA ERITEMATODESCAMATIVA Y ENFERMEDADES AMPOLLOSAS","frente":"El Liquen Plano se caracteriza clínicamente por la regla de las 4 \"P\":","opciones":[{"letra":"A","texto":"Pápula, Placa, Purpúrica, Pigmentada"},{"letra":"B","texto":"Pápula, Poligonal, Purpúrica/Violácea, Pruriginosa"},{"letra":"C","texto":"Pústula, Pain (dolorosa), Plana, Profiláctica"},{"letra":"D","texto":"Pigmentada, Palmar, Profunda, Perioral"}],"respuesta":"B) Pápula, Poligonal, Purpúrica/Violácea, Pruriginosa","explicacion":"Las clásicas “P” del liquen plano describen lesiones papulares, poligonales, purpúricas/violáceas y pruriginosas; con frecuencia también se añade que son planas.","fija":"Liquen plano: pápulas poligonales, violáceas y pruriginosas.","href":"examenes.html?pregunta=88"},"89":{"id":89,"tipo":"examen","titulo":"Pregunta 89","tema":"PARTE 5: PATOLOGÍA ERITEMATODESCAMATIVA Y ENFERMEDADES AMPOLLOSAS","frente":"Histológicamente, el Liquen Plano presenta un infiltrado inflamatorio en la unión dermoepidérmica en forma de:","opciones":[{"letra":"A","texto":"Absceso difuso"},{"letra":"B","texto":"Infiltrado \"en banda\" o en hilera con vacuolización de la capa basal"},{"letra":"C","texto":"Granulomas caseificantes"},{"letra":"D","texto":"Vasculitis leucocitoclástica con trombosis"}],"respuesta":"B) Infiltrado \"en banda\" o en hilera con vacuolización de la capa basal","explicacion":"El liquen plano muestra un infiltrado linfocítico en banda en la unión dermoepidérmica con daño vacuolar basal. Esta dermatitis de interfase explica varios de sus hallazgos histológicos.","fija":"Liquen plano: infiltrado en banda en unión dermoepidérmica.","href":"examenes.html?pregunta=89"},"90":{"id":90,"tipo":"examen","titulo":"Pregunta 90","tema":"PARTE 5: PATOLOGÍA ERITEMATODESCAMATIVA Y ENFERMEDADES AMPOLLOSAS","frente":"Los cuerpos coloides o de Civatte vistos en la histología del liquen plano corresponden a:","opciones":[{"letra":"A","texto":"Queratinocitos basales apoptóticos / degenerados"},{"letra":"B","texto":"Depósitos de amiloide"},{"letra":"C","texto":"Colonias bacterianas"},{"letra":"D","texto":"Granulocitos lisados"}],"respuesta":"A) Queratinocitos basales apoptóticos / degenerados","explicacion":"Los cuerpos de Civatte son queratinocitos basales apoptóticos y eosinofílicos, típicos de dermatitis de interfase como el liquen plano. No corresponden a depósitos de amiloide.","fija":"Cuerpos de Civatte = queratinocitos apoptóticos.","href":"examenes.html?pregunta=90"},"91":{"id":91,"tipo":"examen","titulo":"Pregunta 91","tema":"PARTE 5: PATOLOGÍA ERITEMATODESCAMATIVA Y ENFERMEDADES AMPOLLOSAS","frente":"¿Con qué infección viral crónica sistémica se asocia fuertemente la presencia de Liquen Plano?","opciones":[{"letra":"A","texto":"Virus de la Hepatitis B"},{"letra":"B","texto":"Virus de la Hepatitis C (VHC)"},{"letra":"C","texto":"Citomegalovirus"},{"letra":"D","texto":"Virus HTLV-1"}],"respuesta":"B) Virus de la Hepatitis C (VHC)","explicacion":"El liquen plano tiene una asociación epidemiológica descrita con infección crónica por virus de hepatitis C, aunque la fuerza de la asociación varía por región.","fija":"Liquen plano: asociación clásica con VHC.","href":"examenes.html?pregunta=91"},"92":{"id":92,"tipo":"examen","titulo":"Pregunta 92","tema":"PARTE 5: PATOLOGÍA ERITEMATODESCAMATIVA Y ENFERMEDADES AMPOLLOSAS","frente":"La Pitiriasis Rosada de Gibert es una dermatosis aguda, autolimitada, presumiblemente desencadenada por la reactivación de:","opciones":[{"letra":"A","texto":"Virus del Papiloma Humano"},{"letra":"B","texto":"Herpes Virus Humano 6 y 7 (VHH-6 / VHH-7)"},{"letra":"C","texto":"Coxsackie B4"},{"letra":"D","texto":"Parvovirus B19"}],"respuesta":"B) Herpes Virus Humano 6 y 7 (VHH-6 / VHH-7)","explicacion":"La pitiriasis rosada se ha relacionado con reactivación de VHH-6 y VHH-7. Es una dermatosis autolimitada que suele iniciar con una placa heráldica.","fija":"Pitiriasis rosada: asociación con VHH-6/VHH-7.","href":"examenes.html?pregunta=92"},"93":{"id":93,"tipo":"examen","titulo":"Pregunta 93","tema":"PARTE 5: PATOLOGÍA ERITEMATODESCAMATIVA Y ENFERMEDADES AMPOLLOSAS","frente":"En la Dermatitis Seborreica, el área corporal afectada se relaciona con zonas de elevada densidad de:","opciones":[{"letra":"A","texto":"Folículos pilosos atrofiados"},{"letra":"B","texto":"Glándulas sebáceas (cara, cuero cabelludo, tórax superior)"},{"letra":"C","texto":"Glándulas ecrinas exclusivamente"},{"letra":"D","texto":"Adipocitos subcutáneos"}],"respuesta":"B) Glándulas sebáceas (cara, cuero cabelludo, tórax superior)","explicacion":"La dermatitis seborreica afecta zonas con alta densidad de glándulas sebáceas como cuero cabelludo, cejas, surcos nasolabiales y tórax superior.","fija":"Dermatitis seborreica: zonas ricas en glándulas sebáceas.","href":"examenes.html?pregunta=93"},"94":{"id":94,"tipo":"examen","titulo":"Pregunta 94","tema":"PARTE 5: PATOLOGÍA ERITEMATODESCAMATIVA Y ENFERMEDADES AMPOLLOSAS","frente":"¿Qué microorganismo fúngico comensal de la piel juega un rol patogénico clave en el desarrollo de la Dermatitis Seborreica?","opciones":[{"letra":"A","texto":"Candida albicans"},{"letra":"B","texto":"Malassezia spp. (Malassezia restricta / globosa)"},{"letra":"C","texto":"Trichophyton tonsurans"},{"letra":"D","texto":"Aspergillus fumigatus"}],"respuesta":"B) Malassezia spp. (Malassezia restricta / globosa)","explicacion":"Malassezia spp., especialmente M. restricta y M. globosa, participa en la patogenia de dermatitis seborreica en individuos predispuestos. Esto explica la utilidad de antifúngicos tópicos.","fija":"Dermatitis seborreica: Malassezia spp.","href":"examenes.html?pregunta=94"},"95":{"id":95,"tipo":"examen","titulo":"Pregunta 95","tema":"PARTE 5: PATOLOGÍA ERITEMATODESCAMATIVA Y ENFERMEDADES AMPOLLOSAS","frente":"El Pénfigo Vulgar es una enfermedad autoinmune ampollar grave caracterizada por anticuerpos IgG dirigidos contra:","opciones":[{"letra":"A","texto":"Colágeno IV"},{"letra":"B","texto":"Desmogleína 3 (y Desmogleína 1 en fases avanzadas)"},{"letra":"C","texto":"Integrina Alfa-6"},{"letra":"D","texto":"Laminina 332"}],"respuesta":"B) Desmogleína 3 (y Desmogleína 1 en fases avanzadas)","explicacion":"El pénfigo vulgar se asocia a IgG contra desmogleína 3 y, cuando hay compromiso cutáneo más amplio, también contra desmogleína 1. La pérdida de adhesión genera acantólisis suprabasal.","fija":"Pénfigo vulgar: anti-Dsg3 ± Dsg1.","href":"examenes.html?pregunta=95"},"96":{"id":96,"tipo":"examen","titulo":"Pregunta 96","tema":"PARTE 5: PATOLOGÍA ERITEMATODESCAMATIVA Y ENFERMEDADES AMPOLLOSAS","frente":"El Pénfigo Foliáceo se diferencia clínicamente del Pénfigo Vulgar porque el Pénfigo Foliáceo:","opciones":[{"letra":"A","texto":"No afecta las mucosas y presenta ampollas extremadamente superficiales (subcórneas)"},{"letra":"B","texto":"Produce ampollas muy profundas en la dermis"},{"letra":"C","texto":"Tiene signo de Nikolsky negativo"},{"letra":"D","texto":"Es causado por infecciones bacterianas"}],"respuesta":"A) No afecta las mucosas y presenta ampollas extremadamente superficiales (subcórneas)","explicacion":"El pénfigo foliáceo afecta capas epidérmicas superficiales por autoanticuerpos contra desmogleína 1 y típicamente respeta las mucosas. Por eso las ampollas son muy superficiales y a menudo se ven como erosiones o costras.","fija":"Pénfigo foliáceo: superficial y sin mucosa.","href":"examenes.html?pregunta=96"},"97":{"id":97,"tipo":"examen","titulo":"Pregunta 97","tema":"PARTE 5: PATOLOGÍA ERITEMATODESCAMATIVA Y ENFERMEDADES AMPOLLOSAS","frente":"En el Pénfigo Foliáceo, los autoanticuerpos están dirigidos selectivamente contra:","opciones":[{"letra":"A","texto":"Desmogleína 3"},{"letra":"B","texto":"Desmogleína 1"},{"letra":"C","texto":"BPAG1"},{"letra":"D","texto":"Pectina"}],"respuesta":"B) Desmogleína 1","explicacion":"En pénfigo foliáceo el autoantígeno principal es desmogleína 1, abundante en capas superficiales de la epidermis. La desmogleína 3 se relaciona principalmente con pénfigo vulgar.","fija":"Pénfigo foliáceo = anti-desmogleína 1.","href":"examenes.html?pregunta=97"},"98":{"id":98,"tipo":"examen","titulo":"Pregunta 98","tema":"PARTE 5: PATOLOGÍA ERITEMATODESCAMATIVA Y ENFERMEDADES AMPOLLOSAS","frente":"El examen de Inmunofluorescencia Directa (IFD) en el Pénfigo Vulgar muestra un patrón característico de deposición de IgG C3 en:","opciones":[{"letra":"A","texto":"La membrana basal en banda continua lineal"},{"letra":"B","texto":"La sustancia intercelular de la epidermis en patrón de \"malla de pescar\" o \"panal de abeja\""},{"letra":"C","texto":"Los vasos sanguíneos superficiales"},{"letra":"D","texto":"Las fibras de colágeno dérmicas"}],"respuesta":"B) La sustancia intercelular de la epidermis en patrón de \"malla de pescar\" o \"panal de abeja\"","explicacion":"La inmunofluorescencia directa del pénfigo vulgar muestra depósito intercelular de IgG y C3 con patrón reticular de malla de pescar o panal de abeja.","fija":"Pénfigo vulgar en IFD: patrón intercelular en malla de pescar.","href":"examenes.html?pregunta=98"},"99":{"id":99,"tipo":"examen","titulo":"Pregunta 99","tema":"PARTE 5: PATOLOGÍA ERITEMATODESCAMATIVA Y ENFERMEDADES AMPOLLOSAS","frente":"El Penfigoide Ampolloso afecta primordialmente a pacientes de qué grupo etario:","opciones":[{"letra":"A","texto":"Niños menores de 2 años"},{"letra":"B","texto":"Adultos mayores (ancianos de más de 60-70 años)"},{"letra":"C","texto":"Adolescentes en la pubertad"},{"letra":"D","texto":"Mujeres embarazadas en el primer trimestre"}],"respuesta":"B) Adultos mayores (ancianos de más de 60-70 años)","explicacion":"El penfigoide ampolloso predomina en adultos mayores, generalmente por encima de 60-70 años. Se caracteriza por prurito y ampollas tensas subepidérmicas.","fija":"Penfigoide ampolloso: enfermedad del adulto mayor.","href":"examenes.html?pregunta=99"},"100":{"id":100,"tipo":"examen","titulo":"Pregunta 100","tema":"PARTE 5: PATOLOGÍA ERITEMATODESCAMATIVA Y ENFERMEDADES AMPOLLOSAS","frente":"En el Penfigoide Ampolloso, la Inmunofluorescencia Directa (IFD) revela:","opciones":[{"letra":"A","texto":"Depósito lineal de IgG y/o C3 a lo largo de la zona de la membrana basal dermoepidérmica"},{"letra":"B","texto":"Depósito intercelular epidérmico en malla de pescar"},{"letra":"C","texto":"Depósitos IgA granulares en las papilas dérmicas"},{"letra":"D","texto":"Ausencia total de depósitos inmunes"}],"respuesta":"A) Depósito lineal de IgG y/o C3 a lo largo de la zona de la membrana basal dermoepidérmica","explicacion":"La IFD del penfigoide ampolloso muestra depósito lineal de IgG y C3 a lo largo de la membrana basal. Esto contrasta con el patrón intercelular del pénfigo.","fija":"Penfigoide: IgG/C3 lineal en membrana basal.","href":"examenes.html?pregunta=100"},"101":{"id":101,"tipo":"examen","titulo":"Pregunta 101","tema":"PARTE 6: DERMATITIS, ALERGIA Y REACCIONES POR FÁRMACOS","frente":"La Dermatitis Herpetiforme es una manifestación cutánea ampollosa de la:","opciones":[{"letra":"A","texto":"Enfermedad de Crohn"},{"letra":"B","texto":"Enfermedad Celíaca (Enteropatía sensible al gluten)"},{"letra":"C","texto":"Colitis Ulcerosa"},{"letra":"D","texto":"Diabetes Mellitus Tipo 1"}],"respuesta":"B) Enfermedad Celíaca (Enteropatía sensible al gluten)","explicacion":"La dermatitis herpetiforme es la manifestación cutánea clásica de la enfermedad celíaca. Se asocia a prurito intenso y lesiones agrupadas en superficies extensoras.","fija":"Dermatitis herpetiforme = manifestación cutánea de celiaquía.","href":"examenes.html?pregunta=101"},"102":{"id":102,"tipo":"examen","titulo":"Pregunta 102","tema":"PARTE 6: DERMATITIS, ALERGIA Y REACCIONES POR FÁRMACOS","frente":"Los anticuerpos característicos implicados en la patogenia de la Dermatitis Herpetiforme son de clase:","opciones":[{"letra":"A","texto":"IgG contra la desmogleína"},{"letra":"B","texto":"IgA depositada en forma granular en las papilas dérmicas"},{"letra":"C","texto":"IgM fijadora de complemento en la dermis"},{"letra":"D","texto":"IgE libre en suero"}],"respuesta":"B) IgA depositada en forma granular en las papilas dérmicas","explicacion":"La dermatitis herpetiforme se caracteriza por depósitos granulares de IgA en papilas dérmicas en inmunofluorescencia directa. Es un hallazgo diagnóstico clave.","fija":"Dermatitis herpetiforme: IgA granular en papilas dérmicas.","href":"examenes.html?pregunta=102"},"103":{"id":103,"tipo":"examen","titulo":"Pregunta 103","tema":"PARTE 6: DERMATITIS, ALERGIA Y REACCIONES POR FÁRMACOS","frente":"Tratamiento sistémico farmacológico de elección de acción rápida para el control del prurito y lesiones en Dermatitis Herpetiforme junto con la dieta libre de gluten:","opciones":[{"letra":"A","texto":"Prednisona oral a dosis altas"},{"letra":"B","texto":"Dapsona (Diaminodifenilsulfona)"},{"letra":"C","texto":"Metotrexato"},{"letra":"D","texto":"Ciclosporina"}],"respuesta":"B) Dapsona (Diaminodifenilsulfona)","explicacion":"La dapsona produce alivio rápido del prurito en dermatitis herpetiforme, mientras que la dieta estricta sin gluten trata el mecanismo de fondo y reduce recurrencias.","fija":"Dermatitis herpetiforme: dapsona + dieta sin gluten.","href":"examenes.html?pregunta=103"},"104":{"id":104,"tipo":"examen","titulo":"Pregunta 104","tema":"PARTE 6: DERMATITIS, ALERGIA Y REACCIONES POR FÁRMACOS","frente":"Paciente lactante con eccema en mejillas que respeta el triángulo nasogeniano, piel muy seca (xerosis) y prurito severo. ¿Cuál es la sospecha diagnóstica principal?","opciones":[{"letra":"A","texto":"Dermatitis Seborreica"},{"letra":"B","texto":"Dermatitis Atópica"},{"letra":"C","texto":"Psoriasis infantil"},{"letra":"D","texto":"Escabiosis"}],"respuesta":"B) Dermatitis Atópica","explicacion":"El eccema pruriginoso del lactante con xerosis y afectación facial es característico de dermatitis atópica. El prurito intenso y el antecedente atópico ayudan a diferenciarla de dermatitis seborreica.","fija":"Dermatitis atópica: prurito + xerosis + patrón por edad.","href":"examenes.html?pregunta=104"},"105":{"id":105,"tipo":"examen","titulo":"Pregunta 105","tema":"PARTE 6: DERMATITIS, ALERGIA Y REACCIONES POR FÁRMACOS","frente":"En la fase infantil y del adulto de la Dermatitis Atópica, las lesiones eccematosas se localizan preferentemente en:","opciones":[{"letra":"A","texto":"Flexuras antecubitales y poplíteas"},{"letra":"B","texto":"Caras de extensión de codos y rodillas"},{"letra":"C","texto":"Palmas y plantas exclusivamente"},{"letra":"D","texto":"Zona lumbosacra"}],"respuesta":"A) Flexuras antecubitales y poplíteas","explicacion":"En niños mayores y adultos, la dermatitis atópica predomina en flexuras antecubitales y poplíteas. La distribución cambia con la edad.","fija":"Dermatitis atópica del niño mayor/adulto: flexuras.","href":"examenes.html?pregunta=105"},"106":{"id":106,"tipo":"examen","titulo":"Pregunta 106","tema":"PARTE 6: DERMATITIS, ALERGIA Y REACCIONES POR FÁRMACOS","frente":"¿Cuál es el pilar fundamental del tratamiento de mantenimiento y prevención de brotes en la Dermatitis Atópica?","opciones":[{"letra":"A","texto":"Corticoides orales continuos"},{"letra":"B","texto":"Hidratación frecuente con emolientes y restauración de la barrera cutánea"},{"letra":"C","texto":"Antibióticos profilácticos"},{"letra":"D","texto":"Antihistamínicos tópicos"}],"respuesta":"B) Hidratación frecuente con emolientes y restauración de la barrera cutánea","explicacion":"El mantenimiento de la barrera cutánea con emolientes frecuentes es la base del tratamiento crónico de dermatitis atópica. Reduce xerosis, prurito y frecuencia de brotes.","fija":"Atopia: emolientes y restauración de barrera son el pilar.","href":"examenes.html?pregunta=106"},"107":{"id":107,"tipo":"examen","titulo":"Pregunta 107","tema":"PARTE 6: DERMATITIS, ALERGIA Y REACCIONES POR FÁRMACOS","frente":"La Dermatitis de Contacto Alérgica es una reacción de hipersensibilidad de tipo:","opciones":[{"letra":"A","texto":"Tipo I (Inmediata mediada por IgE)"},{"letra":"B","texto":"Tipo IV (Retardada mediada por células T)"},{"letra":"C","texto":"Tipo II (Citotóxica)"},{"letra":"D","texto":"Tipo III (Por inmunocomplejos)"}],"respuesta":"B) Tipo IV (Retardada mediada por células T)","explicacion":"La dermatitis de contacto alérgica es una hipersensibilidad tipo IV mediada por linfocitos T y requiere sensibilización previa. La reacción aparece de forma retardada tras reexposición.","fija":"Contacto alérgico = hipersensibilidad tipo IV.","href":"examenes.html?pregunta=107"},"108":{"id":108,"tipo":"examen","titulo":"Pregunta 108","tema":"PARTE 6: DERMATITIS, ALERGIA Y REACCIONES POR FÁRMACOS","frente":"El alérgeno más frecuente causante de Dermatitis de Contacto Alérgica por bisutería y objetos metálicos es el:","opciones":[{"letra":"A","texto":"Cobre"},{"letra":"B","texto":"Níquel"},{"letra":"C","texto":"Cromo"},{"letra":"D","texto":"Oro"}],"respuesta":"B) Níquel","explicacion":"El níquel es uno de los alérgenos de contacto más frecuentes y se encuentra en bisutería, broches y objetos metálicos. Puede confirmarse mediante pruebas epicutáneas.","fija":"Bisutería + eczema = pensar en níquel.","href":"examenes.html?pregunta=108"},"109":{"id":109,"tipo":"examen","titulo":"Pregunta 109","tema":"PARTE 6: DERMATITIS, ALERGIA Y REACCIONES POR FÁRMACOS","frente":"La Dermatitis de Contacto Irritativa se diferencia de la Alérgica en que la Irritativa:","opciones":[{"letra":"A","texto":"Requiere una fase previa de sensibilización inmunológica"},{"letra":"B","texto":"Es causada por un daño citotóxico directo sobre la piel sin mecanismo inmunológico previo"},{"letra":"C","texto":"Solo ocurre en pacientes atópicos"},{"letra":"D","texto":"Se diagnostica mediante parches cutáneos (Patch test)"}],"respuesta":"B) Es causada por un daño citotóxico directo sobre la piel sin mecanismo inmunológico previo","explicacion":"La dermatitis irritativa resulta de daño directo sobre la barrera cutánea sin requerir sensibilización inmunológica previa. Su intensidad depende de concentración, tiempo de exposición y estado de la piel.","fija":"Dermatitis irritativa: daño directo, no requiere sensibilización.","href":"examenes.html?pregunta=109"},"110":{"id":110,"tipo":"examen","titulo":"Pregunta 110","tema":"PARTE 6: DERMATITIS, ALERGIA Y REACCIONES POR FÁRMACOS","frente":"La Urticaria Aguda se define como la presencia de habones/ronchas y/o angioedema con una duración menor a:","opciones":[{"letra":"A","texto":"24 horas"},{"letra":"B","texto":"6 semanas"},{"letra":"C","texto":"3 meses"},{"letra":"D","texto":"1 año"}],"respuesta":"B) 6 semanas","explicacion":"La urticaria aguda se define por una duración global menor de seis semanas. Cada habón individual, en cambio, suele durar menos de 24 horas.","fija":"Urticaria aguda: curso total <6 semanas; cada habón <24 h.","href":"examenes.html?pregunta=110"},"111":{"id":111,"tipo":"examen","titulo":"Pregunta 111","tema":"PARTE 6: DERMATITIS, ALERGIA Y REACCIONES POR FÁRMACOS","frente":"El mediador químico principal liberado por los mastocitos responsable del prurito, eritema y edema en la urticaria es:","opciones":[{"letra":"A","texto":"Histamina"},{"letra":"B","texto":"Serotonina"},{"letra":"C","texto":"Bradicinina"},{"letra":"D","texto":"Prostaglandina E2"}],"respuesta":"A) Histamina","explicacion":"La histamina liberada por mastocitos es el mediador central de prurito, vasodilatación y aumento de permeabilidad en urticaria. Por eso los antihistamínicos H1 son primera línea.","fija":"Urticaria: histamina es el mediador principal.","href":"examenes.html?pregunta=111"},"112":{"id":112,"tipo":"examen","titulo":"Pregunta 112","tema":"PARTE 6: DERMATITIS, ALERGIA Y REACCIONES POR FÁRMACOS","frente":"El tratamiento de primera línea de la Urticaria es:","opciones":[{"letra":"A","texto":"Corticoides sistémicos a dosis altas por 1 mes"},{"letra":"B","texto":"Antihistamínicos H1 de segunda generación (no sedantes) a dosis estándar"},{"letra":"C","texto":"Adrenalina intramuscular en todos los casos"},{"letra":"D","texto":"Omalizumab de entrada"}],"respuesta":"B) Antihistamínicos H1 de segunda generación (no sedantes) a dosis estándar","explicacion":"Los antihistamínicos H1 de segunda generación son primera línea por su eficacia y menor sedación. Los corticoides no se usan de forma prolongada como tratamiento basal.","fija":"Urticaria: H1 de segunda generación primero.","href":"examenes.html?pregunta=112"},"113":{"id":113,"tipo":"examen","titulo":"Pregunta 113","tema":"PARTE 6: DERMATITIS, ALERGIA Y REACCIONES POR FÁRMACOS","frente":"Si un paciente con Urticaria Crónica no responde a la dosis estándar de antihistamínicos H1 de 2ª generación, el siguiente paso según las guías internacionales es:","opciones":[{"letra":"A","texto":"Cambiar a antihistamínicos H1 de 1ª generación"},{"letra":"B","texto":"Aumentar la dosis del antihistamínico H1 de 2ª generación hasta 4 veces la dosis convencional"},{"letra":"C","texto":"Iniciar Inmunoglobulina Humana Intravenosa"},{"letra":"D","texto":"Inducir plasmaféresis"}],"respuesta":"B) Aumentar la dosis del antihistamínico H1 de 2ª generación hasta 4 veces la dosis convencional","explicacion":"Si la urticaria crónica persiste con dosis estándar de H1 de segunda generación, las guías permiten aumentar la dosis hasta cuatro veces antes de escalar a terapias como omalizumab.","fija":"Urticaria crónica: aumentar H1 de 2ª generación hasta 4×.","href":"examenes.html?pregunta=113"},"114":{"id":114,"tipo":"examen","titulo":"Pregunta 114","tema":"PARTE 6: DERMATITIS, ALERGIA Y REACCIONES POR FÁRMACOS","frente":"El Angioedema se diferencia de la Urticaria en que el Angioedema afecta a:","opciones":[{"letra":"A","texto":"La epidermis exclusivamente"},{"letra":"B","texto":"La dermis profunda y el tejido subcutáneo/submucoso, produciendo dolor más que prurito"},{"letra":"C","texto":"La superficie de las uñas"},{"letra":"D","texto":"El folículo piloso profundo"}],"respuesta":"B) La dermis profunda y el tejido subcutáneo/submucoso, produciendo dolor más que prurito","explicacion":"El angioedema compromete dermis profunda y tejido subcutáneo o submucoso, con edema más profundo y a menudo dolor o sensación de tensión. La urticaria afecta principalmente dermis superficial.","fija":"Angioedema = edema profundo subcutáneo/submucoso.","href":"examenes.html?pregunta=114"},"115":{"id":115,"tipo":"examen","titulo":"Pregunta 115","tema":"PARTE 6: DERMATITIS, ALERGIA Y REACCIONES POR FÁRMACOS","frente":"El Eritema Multiforme se caracteriza por lesiones cutáneas patognomónicas denominadas:","opciones":[{"letra":"A","texto":"Placas en escama"},{"letra":"B","texto":"Lesiones en \"diana\" o \"blanco de tiro\" (con tres zonas concéntricas)"},{"letra":"C","texto":"Habones evanescentes"},{"letra":"D","texto":"Úlceras fagedénicas"}],"respuesta":"B) Lesiones en \"diana\" o \"blanco de tiro\" (con tres zonas concéntricas)","explicacion":"Las lesiones en diana con tres zonas concéntricas son características del eritema multiforme. Su reconocimiento ayuda a diferenciarlo de urticaria y farmacodermias extensas.","fija":"Eritema multiforme: lesión en diana típica.","href":"examenes.html?pregunta=115"},"116":{"id":116,"tipo":"examen","titulo":"Pregunta 116","tema":"PARTE 6: DERMATITIS, ALERGIA Y REACCIONES POR FÁRMACOS","frente":"El desencadenante infeccioso más común del Eritema Multiforme Menor es:","opciones":[{"letra":"A","texto":"Infección por el Virus del Herpes Simple (VHS)"},{"letra":"B","texto":"Infección por Streptococcus pneumoniae"},{"letra":"C","texto":"Escherichia coli"},{"letra":"D","texto":"Varicela Zóster"}],"respuesta":"A) Infección por el Virus del Herpes Simple (VHS)","explicacion":"El herpes simple es el desencadenante infeccioso más frecuente del eritema multiforme menor, a menudo con episodios recurrentes tras herpes labial.","fija":"Eritema multiforme menor: frecuente tras VHS.","href":"examenes.html?pregunta=116"},"117":{"id":117,"tipo":"examen","titulo":"Pregunta 117","tema":"PARTE 6: DERMATITIS, ALERGIA Y REACCIONES POR FÁRMACOS","frente":"El Síndrome de Stevens-Johnson (SSJ) y la Necrólisis Epidérmica Tóxica (NET) se definen según el porcentaje de desprendimiento de la superficie corporal total (SCT). Se considera NET cuando el desprendimiento es:","opciones":[{"letra":"A","texto":"Menor del 10% de la SCT"},{"letra":"B","texto":"Entre 10% y 30% de la SCT"},{"letra":"C","texto":"Mayor del 30% de la SCT"},{"letra":"D","texto":"Exactamente del 5% de la SCT"}],"respuesta":"C) Mayor del 30% de la SCT","explicacion":"La NET se define por desprendimiento epidérmico de más del 30% de la superficie corporal; SSJ afecta menos del 10% y 10-30% corresponde a superposición SSJ/NET.","fija":"NET: >30% de superficie corporal desprendida.","href":"examenes.html?pregunta=117"},"118":{"id":118,"tipo":"examen","titulo":"Pregunta 118","tema":"PARTE 6: DERMATITIS, ALERGIA Y REACCIONES POR FÁRMACOS","frente":"La causa principal del Síndrome de Stevens-Johnson y la Necrólisis Epidérmica Tóxica es:","opciones":[{"letra":"A","texto":"Reacción adversa severa a medicamentos (ej. anticonvulsivantes, alopurinol, sulfonamidas, AINES)"},{"letra":"B","texto":"Infección micótica diseminada"},{"letra":"C","texto":"Déficit vitamínico grave"},{"letra":"D","texto":"Exposición a radiación UV"}],"respuesta":"A) Reacción adversa severa a medicamentos (ej. anticonvulsivantes, alopurinol, sulfonamidas, AINES)","explicacion":"SSJ/NET se asocia principalmente con reacciones graves a fármacos como anticonvulsivantes, alopurinol, sulfonamidas y algunos AINE. El retiro inmediato del fármaco es esencial.","fija":"SSJ/NET: sospechar fármacos de alto riesgo.","href":"examenes.html?pregunta=118"},"119":{"id":119,"tipo":"examen","titulo":"Pregunta 119","tema":"PARTE 6: DERMATITIS, ALERGIA Y REACCIONES POR FÁRMACOS","frente":"El Síndrome DRESS (Drug Reaction with Eosinophilia and Systemic Symptoms) se caracteriza clínicamente por exantema cutáneo acompañado de:","opciones":[{"letra":"A","texto":"Fiebre, adenopatías, eosinofilia y afectación visceral (hígado, riñón)"},{"letra":"B","texto":"Ampollas hemorrágicas generalizadas sin fiebre"},{"letra":"C","texto":"Desprendimiento epidérmico del 80% sin compromiso de órganos"},{"letra":"D","texto":"Trombocitopenia y convulsiones únicamente"}],"respuesta":"A) Fiebre, adenopatías, eosinofilia y afectación visceral (hígado, riñón)","explicacion":"DRESS combina erupción medicamentosa con fiebre, adenopatías, eosinofilia y afectación visceral, especialmente hepática. Suele aparecer varias semanas después de iniciar el fármaco.","fija":"DRESS: rash + eosinofilia + compromiso sistémico.","href":"examenes.html?pregunta=119"},"120":{"id":120,"tipo":"examen","titulo":"Pregunta 120","tema":"PARTE 6: DERMATITIS, ALERGIA Y REACCIONES POR FÁRMACOS","frente":"El Exantema Fijo Medicamentoso se caracteriza por presentar:","opciones":[{"letra":"A","texto":"Lesiones eritematovioláceas que recurren exactamente en la misma localización anatómicamente cada vez que se ingiere el fármaco causante"},{"letra":"B","texto":"Habones migratorios que cambian de sitio cada 2 horas"},{"letra":"C","texto":"Descamación profusa de cuero cabelludo"},{"letra":"D","texto":"Pústulas foliculares purulentas"}],"respuesta":"A) Lesiones eritematovioláceas que recurren exactamente en la misma localización anatómicamente cada vez que se ingiere el fármaco causante","explicacion":"El exantema fijo medicamentoso reaparece en el mismo sitio cada vez que se administra el fármaco causal y suele dejar hiperpigmentación residual.","fija":"Exantema fijo: recurre exactamente en la misma localización.","href":"examenes.html?pregunta=120"},"121":{"id":121,"tipo":"examen","titulo":"Pregunta 121","tema":"PARTE 7: ACNÉ, ROSÁCEA Y PATOLOGÍA DE LOS ANEXOS","frente":"La patogenia del Acné Vulgar involucra cuatro factores clave. ¿Cuál de los siguientes NO es uno de ellos?","opciones":[{"letra":"A","texto":"Hiperqueratinización folicular"},{"letra":"B","texto":"Producción excesiva de sebo mediada por andrógenos"},{"letra":"C","texto":"Proliferación de Cutibacterium acnes (antes Propionibacterium acnes)"},{"letra":"D","texto":"Infección fúngica por dermatofitos"}],"respuesta":"D) Infección fúngica por dermatofitos","explicacion":"Los cuatro pilares del acné son hiperqueratinización folicular, aumento de sebo, Cutibacterium acnes e inflamación. Los dermatofitos no forman parte de su patogenia.","fija":"Acné: no es una dermatofitosis.","href":"examenes.html?pregunta=121"},"122":{"id":122,"tipo":"examen","titulo":"Pregunta 122","tema":"PARTE 7: ACNÉ, ROSÁCEA Y PATOLOGÍA DE LOS ANEXOS","frente":"La lesión elemental patognomónica e inicial del acné vulgar es el:","opciones":[{"letra":"A","texto":"Comedón (abierto o cerrado)"},{"letra":"B","texto":"Habón"},{"letra":"C","texto":"Quiste epidérmico"},{"letra":"D","texto":"Nódulo frío"}],"respuesta":"A) Comedón (abierto o cerrado)","explicacion":"El comedón abierto o cerrado es la lesión elemental patognomónica del acné y refleja obstrucción folicular. Su presencia ayuda a diferenciar acné de rosácea.","fija":"Comedón = lesión clave del acné.","href":"examenes.html?pregunta=122"},"123":{"id":123,"tipo":"examen","titulo":"Pregunta 123","tema":"PARTE 7: ACNÉ, ROSÁCEA Y PATOLOGÍA DE LOS ANEXOS","frente":"Tratamiento tópico de primera línea fundamental en el acné comedoniano por su efecto queratolítico y comedolítico:","opciones":[{"letra":"A","texto":"Corticoides tópicos"},{"letra":"B","texto":"Retinoides tópicos (Adapaleno, Tretinoína)"},{"letra":"C","texto":"Ketoconazol"},{"letra":"D","texto":"Clorhexidina"}],"respuesta":"B) Retinoides tópicos (Adapaleno, Tretinoína)","explicacion":"Los retinoides tópicos normalizan queratinización folicular y son comedolíticos, por eso constituyen la base del acné comedoniano.","fija":"Acné comedoniano: retinoide tópico.","href":"examenes.html?pregunta=123"},"124":{"id":124,"tipo":"examen","titulo":"Pregunta 124","tema":"PARTE 7: ACNÉ, ROSÁCEA Y PATOLOGÍA DE LOS ANEXOS","frente":"En el acné papulopustuloso moderado, el tratamiento combinado oral de elección incluye:","opciones":[{"letra":"A","texto":"Doxiciclina u Oxitetraciclina oral más tratamiento tópico"},{"letra":"B","texto":"Penicilina V oral"},{"letra":"C","texto":"Ciprofloxacino oral"},{"letra":"D","texto":"Antihistamínicos orales"}],"respuesta":"A) Doxiciclina u Oxitetraciclina oral más tratamiento tópico","explicacion":"En acné inflamatorio moderado puede utilizarse una tetraciclina oral como doxiciclina combinada con tratamiento tópico. La combinación reduce inflamación y limita resistencia antimicrobiana.","fija":"Acné moderado: doxiciclina + tratamiento tópico.","href":"examenes.html?pregunta=124"},"125":{"id":125,"tipo":"examen","titulo":"Pregunta 125","tema":"PARTE 7: ACNÉ, ROSÁCEA Y PATOLOGÍA DE LOS ANEXOS","frente":"La Isotretinoína oral está indicada principalmente en el tratamiento del:","opciones":[{"letra":"A","texto":"Acné comedoniano leve"},{"letra":"B","texto":"Acné noduloquístico severo o resistente a tratamientos convencionales"},{"letra":"C","texto":"Acné neonatal autolimitado"},{"letra":"D","texto":"Rosácea eritematotelangiectásica"}],"respuesta":"B) Acné noduloquístico severo o resistente a tratamientos convencionales","explicacion":"La isotretinoína está indicada en acné noduloquístico grave, cicatricial o resistente a tratamientos convencionales. Actúa sobre todos los mecanismos patogénicos principales del acné.","fija":"Isotretinoína: acné noduloquístico severo o refractario.","href":"examenes.html?pregunta=125"},"126":{"id":126,"tipo":"examen","titulo":"Pregunta 126","tema":"PARTE 7: ACNÉ, ROSÁCEA Y PATOLOGÍA DE LOS ANEXOS","frente":"El efecto secundario teratogénico de la Isotretinoína exige obligatoriamente en mujeres en edad fértil:","opciones":[{"letra":"A","texto":"Uso de anticoncepción eficaz desde 1 mes antes, durante y hasta 1 mes después del tratamiento"},{"letra":"B","texto":"Administración conjunta de ácido fólico a dosis altas sin anticoncepción"},{"letra":"C","texto":"Tomar el medicamento solo durante la menstruación"},{"letra":"D","texto":"No requiere ninguna medida si la dosis es baja"}],"respuesta":"A) Uso de anticoncepción eficaz desde 1 mes antes, durante y hasta 1 mes después del tratamiento","explicacion":"La isotretinoína es altamente teratógena, por lo que requiere prevención estricta del embarazo antes, durante y después del tratamiento según protocolos locales.","fija":"Isotretinoína: teratogenicidad obliga a anticoncepción estricta.","href":"examenes.html?pregunta=126"},"127":{"id":127,"tipo":"examen","titulo":"Pregunta 127","tema":"PARTE 7: ACNÉ, ROSÁCEA Y PATOLOGÍA DE LOS ANEXOS","frente":"Además de la teratogenicidad, ¿qué parámetros de laboratorio deben monitorizarse periódicamente durante el tratamiento con Isotretinoína oral?","opciones":[{"letra":"A","texto":"Perfil lipídico (triglicéridos/colesterol) y función hepática (transaminasas)"},{"letra":"B","texto":"Tiempos de coagulación"},{"letra":"C","texto":"Electrólitos séricos (potasio/sodio)"},{"letra":"D","texto":"Hormonas tiroideas"}],"respuesta":"A) Perfil lipídico (triglicéridos/colesterol) y función hepática (transaminasas)","explicacion":"Durante isotretinoína se vigilan especialmente triglicéridos y enzimas hepáticas por riesgo de hipertrigliceridemia y hepatotoxicidad. El seguimiento debe adaptarse al riesgo individual.","fija":"Isotretinoína: monitorizar perfil lipídico y transaminasas.","href":"examenes.html?pregunta=127"},"128":{"id":128,"tipo":"examen","titulo":"Pregunta 128","tema":"PARTE 7: ACNÉ, ROSÁCEA Y PATOLOGÍA DE LOS ANEXOS","frente":"La Rosácea se diferencia fundamentalmente del Acné Vulgar por la ausencia de:","opciones":[{"letra":"A","texto":"Eritema"},{"letra":"B","texto":"Pústulas"},{"letra":"C","texto":"Comedones"},{"letra":"D","texto":"Telangiectasias"}],"respuesta":"C) Comedones","explicacion":"La rosácea puede presentar eritema, telangiectasias y pústulas, pero típicamente carece de comedones. Esa ausencia es una diferencia clínica importante frente al acné vulgar.","fija":"Rosácea: no hay comedones.","href":"examenes.html?pregunta=128"},"129":{"id":129,"tipo":"examen","titulo":"Pregunta 129","tema":"PARTE 7: ACNÉ, ROSÁCEA Y PATOLOGÍA DE LOS ANEXOS","frente":"El subtipo de Rosácea caracterizado por eritema centrofacial persistente y telangiectasias se denomina:","opciones":[{"letra":"A","texto":"Rosácea papulopustulosa"},{"letra":"B","texto":"Rosácea eritematotelangiectásica (o cuperosis)"},{"letra":"C","texto":"Rosácea fimatosa"},{"letra":"D","texto":"Rosácea ocular"}],"respuesta":"B) Rosácea eritematotelangiectásica (o cuperosis)","explicacion":"El subtipo eritematotelangiectásico se caracteriza por eritema centrofacial persistente, flushing y telangiectasias. Los subtipos actuales pueden solaparse clínicamente.","fija":"Rosácea eritematotelangiectásica: eritema persistente + telangiectasias.","href":"examenes.html?pregunta=129"},"130":{"id":130,"tipo":"examen","titulo":"Pregunta 130","tema":"PARTE 7: ACNÉ, ROSÁCEA Y PATOLOGÍA DE LOS ANEXOS","frente":"El engrosamiento e hipertrofia de la piel de la nariz con deformidad estética en hombres mayores con rosácea avanzada se conoce como:","opciones":[{"letra":"A","texto":"Rhinophyma (Rinofima)"},{"letra":"B","texto":"Otofima"},{"letra":"C","texto":"Blefarofima"},{"letra":"D","texto":"Gnatofima"}],"respuesta":"A) Rhinophyma (Rinofima)","explicacion":"El rinofima es engrosamiento fimatoso de la nariz por hiperplasia sebácea y fibrosis, asociado a rosácea crónica, especialmente en hombres.","fija":"Rosácea fimatosa nasal = rinofima.","href":"examenes.html?pregunta=130"},"131":{"id":131,"tipo":"examen","titulo":"Pregunta 131","tema":"PARTE 7: ACNÉ, ROSÁCEA Y PATOLOGÍA DE LOS ANEXOS","frente":"Medicamento tópico de primera elección para reducir el eritema centrofacial transitorio (rubor) en la rosácea por su efecto vasoconstrictor alpha-2 agonista:","opciones":[{"letra":"A","texto":"Tartrato de Brimonidina"},{"letra":"B","texto":"Betametasona"},{"letra":"C","texto":"Mupirocina"},{"letra":"D","texto":"Ácido salicílico al 10%"}],"respuesta":"A) Tartrato de Brimonidina","explicacion":"La brimonidina es un agonista alfa-2 tópico que produce vasoconstricción y reduce transitoriamente el eritema facial persistente de rosácea.","fija":"Brimonidina: vasoconstrictor tópico para eritema de rosácea.","href":"examenes.html?pregunta=131"},"132":{"id":132,"tipo":"examen","titulo":"Pregunta 132","tema":"PARTE 7: ACNÉ, ROSÁCEA Y PATOLOGÍA DE LOS ANEXOS","frente":"Tratamiento sistémico antibiótico a dosis subantimicrobianas (antiinflamatorias) indicado en la Rosácea papulopustulosa moderada a severa:","opciones":[{"letra":"A","texto":"Doxiciclina 40 mg/día"},{"letra":"B","texto":"Amoxicilina 1 g/día"},{"letra":"C","texto":"Ceftriaxona 1 g/día"},{"letra":"D","texto":"Azitromicina 500 mg/día por 6 meses"}],"respuesta":"A) Doxiciclina 40 mg/día","explicacion":"La doxiciclina 40 mg/día se utiliza a dosis subantimicrobiana por su efecto antiinflamatorio en rosácea papulopustulosa moderada o grave.","fija":"Rosácea papulopustulosa: doxiciclina antiinflamatoria.","href":"examenes.html?pregunta=132"},"133":{"id":133,"tipo":"examen","titulo":"Pregunta 133","tema":"PARTE 7: ACNÉ, ROSÁCEA Y PATOLOGÍA DE LOS ANEXOS","frente":"La Hidradenitis Supurativa (Acné Inverso) es una patología crónica e inflamatoria que afecta primariamente a:","opciones":[{"letra":"A","texto":"La unidad pilosebácea de áreas intertriginosas con glándulas apocrinas (axilas, ingle, zona anogenital)"},{"letra":"B","texto":"Las glándulas ecrinas de la frente"},{"letra":"C","texto":"El lecho ungueal de las manos"},{"letra":"D","texto":"La piel del cuero cabelludo únicamente"}],"respuesta":"A) La unidad pilosebácea de áreas intertriginosas con glándulas apocrinas (axilas, ingle, zona anogenital)","explicacion":"La hidradenitis supurativa es una enfermedad inflamatoria de la unidad pilosebácea en áreas intertriginosas como axilas, ingles y región anogenital, con nódulos, abscesos y túneles.","fija":"Hidradenitis: unidad pilosebácea en pliegues.","href":"examenes.html?pregunta=133"},"134":{"id":134,"tipo":"examen","titulo":"Pregunta 134","tema":"PARTE 7: ACNÉ, ROSÁCEA Y PATOLOGÍA DE LOS ANEXOS","frente":"La Alopecia Areata se considera una enfermedad:","opciones":[{"letra":"A","texto":"Infecciosa fúngica"},{"letra":"B","texto":"Autoinmune mediada por linfocitos T con pérdida del privilegio inmune del folículo piloso"},{"letra":"C","texto":"Hereditaria dominante sin inflamación"},{"letra":"D","texto":"Neoplásica maligna"}],"respuesta":"B) Autoinmune mediada por linfocitos T con pérdida del privilegio inmune del folículo piloso","explicacion":"La alopecia areata es una enfermedad autoinmune mediada por linfocitos T contra el folículo piloso, con pérdida de su privilegio inmunológico. Produce áreas no cicatriciales bien delimitadas.","fija":"Alopecia areata: autoinmune y no cicatricial.","href":"examenes.html?pregunta=134"},"135":{"id":135,"tipo":"examen","titulo":"Pregunta 135","tema":"PARTE 7: ACNÉ, ROSÁCEA Y PATOLOGÍA DE LOS ANEXOS","frente":"Al examen dermatoscópico en la Alopecia Areata en fase activa se observan característicamente:","opciones":[{"letra":"A","texto":"Cabellos en \"signo de admiración\" o signo de signo de exclamación"},{"letra":"B","texto":"Vellos espiralados en tirabuzón"},{"letra":"C","texto":"Vainas tubulares blancas rígidas"},{"letra":"D","texto":"Puntos negros gigantes comedonianos"}],"respuesta":"A) Cabellos en \"signo de admiración\" o signo de signo de exclamación","explicacion":"Los cabellos en signo de exclamación son estrechos proximalmente y más gruesos distalmente, y se observan en el margen de placas activas de alopecia areata.","fija":"Alopecia areata activa: cabellos en signo de exclamación.","href":"examenes.html?pregunta=135"},"136":{"id":136,"tipo":"examen","titulo":"Pregunta 136","tema":"PARTE 7: ACNÉ, ROSÁCEA Y PATOLOGÍA DE LOS ANEXOS","frente":"La Alopecia Androgenética en varones está mediada principalmente por la acción del andrógeno:","opciones":[{"letra":"A","texto":"Testosterona libre"},{"letra":"B","texto":"Dihidrotestosterona (DHT), convertida por la enzima 5-alfa reductasa"},{"letra":"C","texto":"Androstenediona"},{"letra":"D","texto":"Dehidroepiandrosterona"}],"respuesta":"B) Dihidrotestosterona (DHT), convertida por la enzima 5-alfa reductasa","explicacion":"La dihidrotestosterona, formada por 5-alfa reductasa, induce miniaturización folicular en áreas genéticamente susceptibles de alopecia androgenética.","fija":"Alopecia androgenética: DHT.","href":"examenes.html?pregunta=136"},"137":{"id":137,"tipo":"examen","titulo":"Pregunta 137","tema":"PARTE 7: ACNÉ, ROSÁCEA Y PATOLOGÍA DE LOS ANEXOS","frente":"¿Cuál es el mecanismo de acción del Finasteride en el tratamiento de la Alopecia Androgenética masculina?","opciones":[{"letra":"A","texto":"Inhibidor selectivo de la enzima 5-alfa reductasa tipo 2"},{"letra":"B","texto":"Agonista de receptores de estrógenos"},{"letra":"C","texto":"Vasodilatador directo de la papila dérmica"},{"letra":"D","texto":"Antihistamínico H2"}],"respuesta":"A) Inhibidor selectivo de la enzima 5-alfa reductasa tipo 2","explicacion":"Finasteride inhibe selectivamente la 5-alfa reductasa tipo 2 y reduce la conversión de testosterona a DHT, disminuyendo la miniaturización folicular.","fija":"Finasteride: inhibe 5-alfa reductasa tipo 2.","href":"examenes.html?pregunta=137"},"138":{"id":138,"tipo":"examen","titulo":"Pregunta 138","tema":"PARTE 7: ACNÉ, ROSÁCEA Y PATOLOGÍA DE LOS ANEXOS","frente":"Fármaco tópico vasodilatador aprobado para estimular el crecimiento capilar en la Alopecia Androgenética tanto masculina como femenina:","opciones":[{"letra":"A","texto":"Minoxidil (al 2% o 5%)"},{"letra":"B","texto":"Clobetasol en loción"},{"letra":"C","texto":"Ketoconazol champú al 1%"},{"letra":"D","texto":"Ácido azelaico"}],"respuesta":"A) Minoxidil (al 2% o 5%)","explicacion":"Minoxidil tópico es un estimulante del crecimiento capilar aprobado para alopecia androgenética en hombres y mujeres. Prolonga la fase anágena y aumenta calibre folicular.","fija":"Alopecia androgenética: minoxidil tópico.","href":"examenes.html?pregunta=138"},"139":{"id":139,"tipo":"examen","titulo":"Pregunta 139","tema":"PARTE 7: ACNÉ, ROSÁCEA Y PATOLOGÍA DE LOS ANEXOS","frente":"El Efluvio Telógeno se caracteriza por una caída difusa y acentuada de cabello que ocurre típicamente:","opciones":[{"letra":"A","texto":"2 a 3 meses después de un evento estresante agudo (parto, fiebre alta, cirugía mayor, dieta estricta)"},{"letra":"B","texto":"Inmediatamente a los 2 días del evento"},{"letra":"C","texto":"5 años después de la menopausia"},{"letra":"D","texto":"De forma irreversible con cicatrización del cuero cabelludo"}],"respuesta":"A) 2 a 3 meses después de un evento estresante agudo (parto, fiebre alta, cirugía mayor, dieta estricta)","explicacion":"El efluvio telógeno suele aparecer 2-3 meses después de un estrés sistémico porque numerosos folículos entran de forma sincronizada en telógeno antes de desprenderse.","fija":"Efluvio telógeno: caída difusa 2-3 meses tras el desencadenante.","href":"examenes.html?pregunta=139"},"140":{"id":140,"tipo":"examen","titulo":"Pregunta 140","tema":"PARTE 7: ACNÉ, ROSÁCEA Y PATOLOGÍA DE LOS ANEXOS","frente":"La Paroniquia Aguda es la infección del pliegue periungueal, producida con mayor frecuencia por:","opciones":[{"letra":"A","texto":"Staphylococcus aureus"},{"letra":"B","texto":"Trichophyton rubrum"},{"letra":"C","texto":"Pseudomonas aeruginosa"},{"letra":"D","texto":"Virus Herpes Humano 8"}],"respuesta":"A) Staphylococcus aureus","explicacion":"La paroniquia aguda es con mayor frecuencia bacteriana y Staphylococcus aureus es un agente típico. Se presenta con dolor, eritema y tumefacción del pliegue ungueal.","fija":"Paroniquia aguda: S. aureus.","href":"examenes.html?pregunta=140"},"141":{"id":141,"tipo":"examen","titulo":"Pregunta 141","tema":"PARTE 8: CANCER DE PIEL, NEOPLASIAS Y DERMATOSIS ASOCIADAS A ENFERMEDADES SISTÉMICAS","frente":"El Carcinoma Basocelular presenta como características histopatológicas típicas:","opciones":[{"letra":"A","texto":"Nidos de células basaloides con disposición de núcleos en \"empalizada periférica\" y artefactos de retracción"},{"letra":"B","texto":"Perlas córneas de queratina difusas"},{"letra":"C","texto":"Melanosomas atípicos pagetoides"},{"letra":"D","texto":"Granulomas con necrosis de caseificación"}],"respuesta":"A) Nidos de células basaloides con disposición de núcleos en \"empalizada periférica\" y artefactos de retracción","explicacion":"El carcinoma basocelular muestra nidos de células basaloides con empalizada periférica y hendiduras de retracción estromal, hallazgos histológicos muy característicos.","fija":"CBC histológico: empalizada periférica + retracción.","href":"examenes.html?pregunta=141"},"142":{"id":142,"tipo":"examen","titulo":"Pregunta 142","tema":"PARTE 8: CANCER DE PIEL, NEOPLASIAS Y DERMATOSIS ASOCIADAS A ENFERMEDADES SISTÉMICAS","frente":"¿Cuál es el factor de riesgo ambiental más importante para el desarrollo del Carcinoma Basocelular y Carcinoma Espinocelular?","opciones":[{"letra":"A","texto":"Radiación Ultravioleta (UV), especialmente la exposición solar crónica y quemaduras solares"},{"letra":"B","texto":"Exposición a jabones perfumados"},{"letra":"C","texto":"Infecciones virales respiratorias"},{"letra":"D","texto":"Traumatismos repetidos de baja intensidad"}],"respuesta":"A) Radiación Ultravioleta (UV), especialmente la exposición solar crónica y quemaduras solares","explicacion":"La exposición a radiación ultravioleta es el principal factor ambiental para carcinomas basocelular y epidermoide, especialmente por daño acumulativo y quemaduras solares.","fija":"Cáncer cutáneo queratinocítico: radiación UV es el factor ambiental principal.","href":"examenes.html?pregunta=142"},"143":{"id":143,"tipo":"examen","titulo":"Pregunta 143","tema":"PARTE 8: CANCER DE PIEL, NEOPLASIAS Y DERMATOSIS ASOCIADAS A ENFERMEDADES SISTÉMICAS","frente":"El Carcinoma Espinocelular (Epidermoide) cutáneo se caracteriza histopatológicamente por:","opciones":[{"letra":"A","texto":"Proliferación de queratinocitos atípicos con puentes intercelulares y formación de \"perlas de queratina\" o perlas córneas"},{"letra":"B","texto":"Nidos de células nevicas en la unión dermoepidérmica"},{"letra":"C","texto":"Infiltrado mastocitario masivo"},{"letra":"D","texto":"Cavidades rellenas de mucina sin atipia"}],"respuesta":"A) Proliferación de queratinocitos atípicos con puentes intercelulares y formación de \"perlas de queratina\" o perlas córneas","explicacion":"El carcinoma epidermoide cutáneo muestra queratinocitos atípicos, puentes intercelulares y perlas córneas en tumores diferenciados. Estos hallazgos reflejan diferenciación escamosa.","fija":"CEC: puentes intercelulares + perlas de queratina.","href":"examenes.html?pregunta=143"},"144":{"id":144,"tipo":"examen","titulo":"Pregunta 144","tema":"PARTE 8: CANCER DE PIEL, NEOPLASIAS Y DERMATOSIS ASOCIADAS A ENFERMEDADES SISTÉMICAS","frente":"¿Cuál de los siguientes tipos de melanoma es el más frecuente en la población de piel clara?","opciones":[{"letra":"A","texto":"Melanoma de extensión superficial"},{"letra":"B","texto":"Melanoma lentiginoso acral"},{"letra":"C","texto":"Melanoma nodular"},{"letra":"D","texto":"Melanoma léntigo maligno"}],"respuesta":"A) Melanoma de extensión superficial","explicacion":"El melanoma de extensión superficial es el subtipo más frecuente en poblaciones de piel clara. Suele presentar una fase de crecimiento radial relativamente prolongada.","fija":"Piel clara: melanoma de extensión superficial es el más frecuente.","href":"examenes.html?pregunta=144"},"145":{"id":145,"tipo":"examen","titulo":"Pregunta 145","tema":"PARTE 8: CANCER DE PIEL, NEOPLASIAS Y DERMATOSIS ASOCIADAS A ENFERMEDADES SISTÉMICAS","frente":"¿Cuál es el tipo histológico de melanoma cutáneo más común en poblaciones de fototipos oscuros (latinoamericanos, afrodescendientes, asiáticos) y que se localiza en palmas, plantas y lecho ungueal?","opciones":[{"letra":"A","texto":"Melanoma de extensión superficial"},{"letra":"B","texto":"Melanoma lentiginoso acral"},{"letra":"C","texto":"Melanoma nodular"},{"letra":"D","texto":"Léntigo maligno melanoma"}],"respuesta":"B) Melanoma lentiginoso acral","explicacion":"El melanoma lentiginoso acral es proporcionalmente más frecuente en fototipos oscuros y aparece en palmas, plantas y aparato ungueal. No depende tanto de exposición solar acumulativa.","fija":"Fototipos oscuros: pensar en melanoma lentiginoso acral.","href":"examenes.html?pregunta=145"},"146":{"id":146,"tipo":"examen","titulo":"Pregunta 146","tema":"PARTE 8: CANCER DE PIEL, NEOPLASIAS Y DERMATOSIS ASOCIADAS A ENFERMEDADES SISTÉMICAS","frente":"Un nevo melanocítico con asimetría, bordes irregulares, variaciones de color y diámetro mayor de 6 mm debe ser evaluado prioritariamente mediante:","opciones":[{"letra":"A","texto":"Biopsia escisional con margen estrecho"},{"letra":"B","texto":"Cauterización inmediata con nitrógeno líquido"},{"letra":"C","texto":"Raspado superficial"},{"letra":"D","texto":"Aplicación de corticoides tópicos por 1 mes"}],"respuesta":"A) Biopsia escisional con margen estrecho","explicacion":"Una lesión melanocítica con criterios ABCDE debe evaluarse mediante biopsia escisional con margen estrecho cuando sea posible, para permitir valoración completa de arquitectura y Breslow.","fija":"Sospecha de melanoma: biopsia escisional.","href":"examenes.html?pregunta=146"},"147":{"id":147,"tipo":"examen","titulo":"Pregunta 147","tema":"PARTE 8: CANCER DE PIEL, NEOPLASIAS Y DERMATOSIS ASOCIADAS A ENFERMEDADES SISTÉMICAS","frente":"El Queratoacantoma es una neoplasia cutánea epidérmica que se caracteriza por:","opciones":[{"letra":"A","texto":"Crecimiento rápido en semanas de un nódulo cupuliforme con un tapón córneo central de queratina, que puede involucionar espontáneamente"},{"letra":"B","texto":"Ampollas hemorrágicas crónicas"},{"letra":"C","texto":"Manchas acrómicas de bordes geográficos"},{"letra":"D","texto":"Nódulos subcutáneos dolorosos sin queratina"}],"respuesta":"A) Crecimiento rápido en semanas de un nódulo cupuliforme con un tapón córneo central de queratina, que puede involucionar espontáneamente","explicacion":"El queratoacantoma crece rápidamente en semanas como un nódulo cupuliforme con cráter central lleno de queratina. Aunque puede involucionar, suele manejarse como lesión de espectro escamoso.","fija":"Queratoacantoma: crecimiento rápido + cráter con tapón córneo.","href":"examenes.html?pregunta=147"},"148":{"id":148,"tipo":"examen","titulo":"Pregunta 148","tema":"PARTE 8: CANCER DE PIEL, NEOPLASIAS Y DERMATOSIS ASOCIADAS A ENFERMEDADES SISTÉMICAS","frente":"El Sarcoma de Kaposi es una neoplasia vascular asociada a la infección por:","opciones":[{"letra":"A","texto":"Virus Herpes Humano 8 (VHH-8) / HSV-8"},{"letra":"B","texto":"Virus de Epstein-Barr"},{"letra":"C","texto":"Citomegalovirus"},{"letra":"D","texto":"Virus de la Hepatitis C"}],"respuesta":"A) Virus Herpes Humano 8 (VHH-8) / HSV-8","explicacion":"El sarcoma de Kaposi está asociado a herpesvirus humano 8. La inmunosupresión favorece su aparición y progresión.","fija":"Kaposi = VHH-8.","href":"examenes.html?pregunta=148"},"149":{"id":149,"tipo":"examen","titulo":"Pregunta 149","tema":"PARTE 8: CANCER DE PIEL, NEOPLASIAS Y DERMATOSIS ASOCIADAS A ENFERMEDADES SISTÉMICAS","frente":"En pacientes con infección por VIH / SIDA avanzada, el Sarcoma de Kaposi se presenta clínicamente como:","opciones":[{"letra":"A","texto":"Maculas, placas y nódulos de color violáceo o purpúrico en piel y mucosas"},{"letra":"B","texto":"Ampollas desnudadas Nikolsky positivo"},{"letra":"C","texto":"Escamas plateadas extensas"},{"letra":"D","texto":"Telangiectasias puras no palpables"}],"respuesta":"A) Maculas, placas y nódulos de color violáceo o purpúrico en piel y mucosas","explicacion":"En VIH avanzado, Kaposi produce máculas, placas o nódulos violáceos en piel y mucosas por proliferación vascular. Puede comprometer órganos internos.","fija":"Kaposi: lesiones violáceas vasculares en inmunosupresión.","href":"examenes.html?pregunta=149"},"150":{"id":150,"tipo":"examen","titulo":"Pregunta 150","tema":"PARTE 8: CANCER DE PIEL, NEOPLASIAS Y DERMATOSIS ASOCIADAS A ENFERMEDADES SISTÉMICAS","frente":"El Micosis Fungoide es el tipo más frecuente de:","opciones":[{"letra":"A","texto":"Linfoma Cutáneo de Células T (LCCT)"},{"letra":"B","texto":"Linfoma Cutáneo de Células B"},{"letra":"C","texto":"Sarcoma de partes blandas"},{"letra":"D","texto":"Leucemia mieloide cutánea"}],"respuesta":"A) Linfoma Cutáneo de Células T (LCCT)","explicacion":"La micosis fungoide es el linfoma cutáneo de células T más frecuente. Evoluciona clásicamente desde parches a placas y tumores en algunos pacientes.","fija":"Micosis fungoide = LCCT más frecuente.","href":"examenes.html?pregunta=150"},"151":{"id":151,"tipo":"examen","titulo":"Pregunta 151","tema":"PARTE 8: CANCER DE PIEL, NEOPLASIAS Y DERMATOSIS ASOCIADAS A ENFERMEDADES SISTÉMICAS","frente":"Histológicamente, los cúmulos de linfocitos T atípicos en la epidermis observados en la Micosis Fungoide se llaman:","opciones":[{"letra":"A","texto":"Microabscesos de Pautrier"},{"letra":"B","texto":"Microabscesos de Munro"},{"letra":"C","texto":"Cuerpos de Russell"},{"letra":"D","texto":"Células de Aschoff"}],"respuesta":"A) Microabscesos de Pautrier","explicacion":"Los microabscesos de Pautrier son agrupaciones intraepidérmicas de linfocitos T atípicos y son un hallazgo clásico de micosis fungoide.","fija":"Micosis fungoide: microabscesos de Pautrier.","href":"examenes.html?pregunta=151"},"152":{"id":152,"tipo":"examen","titulo":"Pregunta 152","tema":"PARTE 8: CANCER DE PIEL, NEOPLASIAS Y DERMATOSIS ASOCIADAS A ENFERMEDADES SISTÉMICAS","frente":"El Síndrome de Sézary es la variante leucémica agresiva del Linfoma Cutáneo de Células T y se define por la tríada clásica de:","opciones":[{"letra":"A","texto":"Eritrodermia, linfadenopatías generalizadas y presencia de células de Sézary (linfocitos T con núcleo cerebriforme) en sangre periférica"},{"letra":"B","texto":"Alopecia, ampollas y artritis"},{"letra":"C","texto":"Psoriasis, ictericia y trombocitopenia"},{"letra":"D","texto":"Purpura fulminans, fiebre y coma"}],"respuesta":"A) Eritrodermia, linfadenopatías generalizadas y presencia de células de Sézary (linfocitos T con núcleo cerebriforme) en sangre periférica","explicacion":"El síndrome de Sézary se caracteriza por eritrodermia, adenopatías y células de Sézary circulantes con núcleos cerebriformes. Es la forma leucémica del linfoma cutáneo T.","fija":"Sézary: eritrodermia + adenopatías + células cerebriformes en sangre.","href":"examenes.html?pregunta=152"},"153":{"id":153,"tipo":"examen","titulo":"Pregunta 153","tema":"PARTE 8: CANCER DE PIEL, NEOPLASIAS Y DERMATOSIS ASOCIADAS A ENFERMEDADES SISTÉMICAS","frente":"La Acantosis Nigricans se manifiesta con placas hiperqueratósicas, gris-parduscas, de aspecto aterciopelado en pliegues (cuello, axilas) y se asocia principalmente a:","opciones":[{"letra":"A","texto":"Hiperinsulinemia y Resistencia a la Insulina (Diabetes Mellitus tipo 2 / Obesidad)"},{"letra":"B","texto":"Hipotiroidismo severo"},{"letra":"C","texto":"Insuficiencia renal terminal"},{"letra":"D","texto":"Déficit de vitamina C"}],"respuesta":"A) Hiperinsulinemia y Resistencia a la Insulina (Diabetes Mellitus tipo 2 / Obesidad)","explicacion":"La acantosis nigricans se asocia fuertemente con hiperinsulinemia y resistencia a insulina, especialmente en obesidad y diabetes tipo 2. La insulina elevada estimula vías de crecimiento epidérmico.","fija":"Acantosis nigricans: marcador de resistencia a insulina.","href":"examenes.html?pregunta=153"},"154":{"id":154,"tipo":"examen","titulo":"Pregunta 154","tema":"PARTE 8: CANCER DE PIEL, NEOPLASIAS Y DERMATOSIS ASOCIADAS A ENFERMEDADES SISTÉMICAS","frente":"La aparición súbita y masiva de múltiples queratosis seborreicas pruriginosas en el tronco (Signo de Leser-Trélat) es un signo paraneoplásico fuertemente asociado a:","opciones":[{"letra":"A","texto":"Adenocarcinoma gástrico u otras neoplasias gastrointestinales"},{"letra":"B","texto":"Melanoma maligno acral"},{"letra":"C","texto":"Carcinoma basocelular múltiple"},{"letra":"D","texto":"Glioblastoma multiforme"}],"respuesta":"A) Adenocarcinoma gástrico u otras neoplasias gastrointestinales","explicacion":"El signo de Leser-Trélat describe aparición abrupta de numerosas queratosis seborreicas y se ha asociado clásicamente a adenocarcinomas gastrointestinales, en especial gástrico.","fija":"Leser-Trélat: brote súbito de queratosis seborreicas + buscar neoplasia interna.","href":"examenes.html?pregunta=154"},"155":{"id":155,"tipo":"examen","titulo":"Pregunta 155","tema":"PARTE 8: CANCER DE PIEL, NEOPLASIAS Y DERMATOSIS ASOCIADAS A ENFERMEDADES SISTÉMICAS","frente":"El Eritema Nodoso es una paniculitis septal sin vasculitis que se presenta clínicamente como:","opciones":[{"letra":"A","texto":"Nódulos eritematosos, dolorosos, calientes en la superficie pretibial de ambas piernas"},{"letra":"B","texto":"Ampollas indoloras en los brazos"},{"letra":"C","texto":"Placas descamativas atróficas en cuero cabelludo"},{"letra":"D","texto":"Pústulas foliculares en espalda"}],"respuesta":"A) Nódulos eritematosos, dolorosos, calientes en la superficie pretibial de ambas piernas","explicacion":"El eritema nodoso es una paniculitis septal que produce nódulos dolorosos y calientes en superficies pretibiales, habitualmente bilaterales. No suele ulcerarse.","fija":"Eritema nodoso: nódulos pretibiales dolorosos.","href":"examenes.html?pregunta=155"},"156":{"id":156,"tipo":"examen","titulo":"Pregunta 156","tema":"PARTE 8: CANCER DE PIEL, NEOPLASIAS Y DERMATOSIS ASOCIADAS A ENFERMEDADES SISTÉMICAS","frente":"¿Cuál de las siguientes es una causa frecuente de Eritema Nodoso?","opciones":[{"letra":"A","texto":"Infecciones por Estreptococo del grupo A, Sarcoidosis, Tuberculosis y Enfermedad Inflamatoria Intestinal"},{"letra":"B","texto":"Exposición al frío extremo"},{"letra":"C","texto":"Déficit de Zinc"},{"letra":"D","texto":"Infección por Rabia"}],"respuesta":"A) Infecciones por Estreptococo del grupo A, Sarcoidosis, Tuberculosis y Enfermedad Inflamatoria Intestinal","explicacion":"Las causas clásicas de eritema nodoso incluyen infección estreptocócica, tuberculosis, sarcoidosis, enfermedad inflamatoria intestinal, fármacos y embarazo.","fija":"Eritema nodoso: pensar en estreptococo, TB, sarcoidosis e EII.","href":"examenes.html?pregunta=156"},"157":{"id":157,"tipo":"examen","titulo":"Pregunta 157","tema":"PARTE 8: CANCER DE PIEL, NEOPLASIAS Y DERMATOSIS ASOCIADAS A ENFERMEDADES SISTÉMICAS","frente":"El Pioderma Gangrenoso es una dermatosis neutrofílica ulcerosa destructiva, con bordes violáceos sobreelevados y socavados, asociada con frecuencia a:","opciones":[{"letra":"A","texto":"Enfermedad Inflamatoria Intestinal (Colitis Ulcerosa / Enfermedad de Crohn) y Artritis Reumatoide"},{"letra":"B","texto":"Asma bronquial"},{"letra":"C","texto":"Insuficiencia hepática fulminante"},{"letra":"D","texto":"Hipoparateroidismo"}],"respuesta":"A) Enfermedad Inflamatoria Intestinal (Colitis Ulcerosa / Enfermedad de Crohn) y Artritis Reumatoide","explicacion":"El pioderma gangrenoso se asocia con enfermedad inflamatoria intestinal, artritis inflamatoria y trastornos hematológicos. El fenómeno de patergia puede empeorar lesiones tras trauma.","fija":"Pioderma gangrenoso: asociación fuerte con EII y artritis.","href":"examenes.html?pregunta=157"},"158":{"id":158,"tipo":"examen","titulo":"Pregunta 158","tema":"PARTE 8: CANCER DE PIEL, NEOPLASIAS Y DERMATOSIS ASOCIADAS A ENFERMEDADES SISTÉMICAS","frente":"La Necrobiosis Lipoidica es una alteración degenerativa del colágeno dérmico con placas amarillentas-violáceas atróficas en región pretibial, asociada fuertemente a:","opciones":[{"letra":"A","texto":"Diabetes Mellitus"},{"letra":"B","texto":"Lupus eritematoso sistémico"},{"letra":"C","texto":"Hipertensión arterial"},{"letra":"D","texto":"Gota"}],"respuesta":"A) Diabetes Mellitus","explicacion":"La necrobiosis lipoídica se relaciona clásicamente con diabetes mellitus y aparece en región pretibial como placas amarillento-atróficas con borde inflamatorio.","fija":"Necrobiosis lipoídica: asociación con diabetes.","href":"examenes.html?pregunta=158"},"159":{"id":159,"tipo":"examen","titulo":"Pregunta 159","tema":"PARTE 8: CANCER DE PIEL, NEOPLASIAS Y DERMATOSIS ASOCIADAS A ENFERMEDADES SISTÉMICAS","frente":"Las pápulas de Gottron (pápulas eritematovioláceas sobre las articulaciones interfalángicas y metacarpofalángicas) y el eritema en heliotropo palpebral son patognomónicos de:","opciones":[{"letra":"A","texto":"Dermatomiositis"},{"letra":"B","texto":"Esclerodermia sistémica"},{"letra":"C","texto":"Lupus discoide"},{"letra":"D","texto":"Enfermedad Mixta del Tejido Conjuntivo"}],"respuesta":"A) Dermatomiositis","explicacion":"Las pápulas de Gottron sobre articulaciones y el eritema heliotropo son hallazgos muy característicos de dermatomiositis. Debe evaluarse además debilidad muscular proximal.","fija":"Gottron + heliotropo = dermatomiositis.","href":"examenes.html?pregunta=159"},"160":{"id":160,"tipo":"examen","titulo":"Pregunta 160","tema":"PARTE 8: CANCER DE PIEL, NEOPLASIAS Y DERMATOSIS ASOCIADAS A ENFERMEDADES SISTÉMICAS","frente":"El fenómeno de Raynaud, la esclerodactilia, las telangiectasias, la disfunción esofágica y la calcinosis cutánea constituyen el síndrome denominado:","opciones":[{"letra":"A","texto":"Síndrome CREST (Esclerosis sistémica cutánea limitada)"},{"letra":"B","texto":"Síndrome de Reiter"},{"letra":"C","texto":"Síndrome de Sweet"},{"letra":"D","texto":"Síndrome de Sjögren"}],"respuesta":"A) Síndrome CREST (Esclerosis sistémica cutánea limitada)","explicacion":"La combinación de calcinosis, Raynaud, disfunción esofágica, esclerodactilia y telangiectasias forma el acrónimo CREST, correspondiente a esclerosis sistémica cutánea limitada.","fija":"CREST = calcinosis, Raynaud, esófago, esclerodactilia, telangiectasias.","href":"examenes.html?pregunta=160"},"161":{"id":161,"tipo":"examen","titulo":"Pregunta 161","tema":"PARTE 9: DERMATOLOGÍA PEDIÁTRICA, TRAUMÁTICA Y TERAPÉUTICA GENERAL","frente":"El Eritema Tóxico del Recién Nacido se caracteriza por pápulas y pústulas eritematosas benignas autolimitadas. El frotis del contenido de la pústula muestra predominantemente:","opciones":[{"letra":"A","texto":"Eosinófilos"},{"letra":"B","texto":"Neutrófilos hipersegmentados"},{"letra":"C","texto":"Linfocitos B"},{"letra":"D","texto":"Histiocitos atípicos"}],"respuesta":"A) Eosinófilos","explicacion":"En eritema tóxico neonatal, el frotis de las pústulas muestra abundantes eosinófilos. Es una erupción benigna, transitoria y autolimitada.","fija":"Eritema tóxico neonatal: eosinófilos.","href":"examenes.html?pregunta=161"},"162":{"id":162,"tipo":"examen","titulo":"Pregunta 162","tema":"PARTE 9: DERMATOLOGÍA PEDIÁTRICA, TRAUMÁTICA Y TERAPÉUTICA GENERAL","frente":"La Melanosis Pustulosa Neonatal Transitoria se diferencia del eritema tóxico en que las pústulas están presentes al nacer y su frotis demuestra células de tipo:","opciones":[{"letra":"A","texto":"Neutrófilos"},{"letra":"B","texto":"Eosinófilos"},{"letra":"C","texto":"Mastocitos"},{"letra":"D","texto":"Células plasmáticas"}],"respuesta":"A) Neutrófilos","explicacion":"La melanosis pustulosa neonatal transitoria presenta pústulas desde el nacimiento y el frotis muestra neutrófilos. Al resolver deja máculas hiperpigmentadas transitorias.","fija":"Melanosis pustulosa neonatal: neutrófilos y lesiones presentes al nacer.","href":"examenes.html?pregunta=162"},"163":{"id":163,"tipo":"examen","titulo":"Pregunta 163","tema":"PARTE 9: DERMATOLOGÍA PEDIÁTRICA, TRAUMÁTICA Y TERAPÉUTICA GENERAL","frente":"La Mancha Mongólica (Melanocitosis Dermal Congénita) se presenta como una mácula azul-grisácea en región lumbosacra en neonatos. Su causa histológica es:","opciones":[{"letra":"A","texto":"Presencia de melanocitos atrapados en la dermis profunda durante la migración embriológica"},{"letra":"B","texto":"Vasodilatación capilar superficial"},{"letra":"C","texto":"Depósito de hemosiderina"},{"letra":"D","texto":"Proliferación epidérmica de queratinocitos"}],"respuesta":"A) Presencia de melanocitos atrapados en la dermis profunda durante la migración embriológica","explicacion":"La melanocitosis dérmica congénita se debe a melanocitos que quedan atrapados en dermis profunda durante migración embrionaria, generando color azul-gris por efecto Tyndall.","fija":"Mancha mongólica: melanocitos dérmicos profundos.","href":"examenes.html?pregunta=163"},"164":{"id":164,"tipo":"examen","titulo":"Pregunta 164","tema":"PARTE 9: DERMATOLOGÍA PEDIÁTRICA, TRAUMÁTICA Y TERAPÉUTICA GENERAL","frente":"El Hemangioma Infantil es el tumor benigno vascular más frecuente de la infancia. Su marcador inmunohistoquímico característico y específico es:","opciones":[{"letra":"A","texto":"GLUT-1 (Transportador de Glucosa 1)"},{"letra":"B","texto":"S100"},{"letra":"C","texto":"CD34"},{"letra":"D","texto":"Ki-67"}],"respuesta":"A) GLUT-1 (Transportador de Glucosa 1)","explicacion":"GLUT-1 es un marcador inmunohistoquímico característico del hemangioma infantil y ayuda a diferenciarlo de otras anomalías vasculares.","fija":"Hemangioma infantil: GLUT-1 positivo.","href":"examenes.html?pregunta=164"},"165":{"id":165,"tipo":"examen","titulo":"Pregunta 165","tema":"PARTE 9: DERMATOLOGÍA PEDIÁTRICA, TRAUMÁTICA Y TERAPÉUTICA GENERAL","frente":"Medicamento sistémico de primera elección para el tratamiento de Hemangiomas Infantiles complicados o con riesgo desfigurante:","opciones":[{"letra":"A","texto":"Propranolol oral"},{"letra":"B","texto":"Prednisona oral"},{"letra":"C","texto":"Vincristina"},{"letra":"D","texto":"Captopril"}],"respuesta":"A) Propranolol oral","explicacion":"Propranolol oral es el tratamiento sistémico de primera elección para hemangiomas infantiles complicados, ulcerados, con riesgo funcional o desfigurante.","fija":"Hemangioma infantil complicado: propranolol.","href":"examenes.html?pregunta=165"},"166":{"id":166,"tipo":"examen","titulo":"Pregunta 166","tema":"PARTE 9: DERMATOLOGÍA PEDIÁTRICA, TRAUMÁTICA Y TERAPÉUTICA GENERAL","frente":"La Mancha en \"Vino de Oporto\" es una malformación vascular capilar presente desde el nacimiento. Cuando se ubica en el territorio de la primera rama del nervio trigémino (V1), se debe descartar el Síndrome de:","opciones":[{"letra":"A","texto":"Sturge-Weber"},{"letra":"B","texto":"Klippel-Trenaunay"},{"letra":"C","texto":"Von Hippel-Lindau"},{"letra":"D","texto":"Neurofibromatosis Tipo 1"}],"respuesta":"A) Sturge-Weber","explicacion":"Una malformación capilar tipo vino de Oporto en territorio V1 obliga a considerar síndrome de Sturge-Weber por riesgo de angiomas leptomeníngeos y glaucoma.","fija":"Vino de Oporto en V1: descartar Sturge-Weber.","href":"examenes.html?pregunta=166"},"167":{"id":167,"tipo":"examen","titulo":"Pregunta 167","tema":"PARTE 9: DERMATOLOGÍA PEDIÁTRICA, TRAUMÁTICA Y TERAPÉUTICA GENERAL","frente":"Las manchas café con leche (más de 6 lesiones mayores de 5 mm en prepúberes) asociadas a efélides axilares (signo de Crowe) son criterio diagnóstico de:","opciones":[{"letra":"A","texto":"Neurofibromatosis Tipo 1 (Enfermedad de Von Recklinghausen)"},{"letra":"B","texto":"Esclerosis Tuberosa"},{"letra":"C","texto":"Síndrome de McCune-Albright"},{"letra":"D","texto":"Incontinencia Pigmenti"}],"respuesta":"A) Neurofibromatosis Tipo 1 (Enfermedad de Von Recklinghausen)","explicacion":"Seis o más manchas café con leche junto con efélides axilares constituyen criterios clásicos de neurofibromatosis tipo 1, especialmente si se acompañan de otros signos del síndrome.","fija":"Café con leche + Crowe = NF1.","href":"examenes.html?pregunta=167"},"168":{"id":168,"tipo":"examen","titulo":"Pregunta 168","tema":"PARTE 9: DERMATOLOGÍA PEDIÁTRICA, TRAUMÁTICA Y TERAPÉUTICA GENERAL","frente":"Los Angiofibromas faciales, los parches de Shagreen (piel de zapa) y los fibromas ungueales (tumores de Koenen) son hallazgos cutáneos de:","opciones":[{"letra":"A","texto":"Esclerosis Tuberosa (Enfermedad de Pringle-Bourneville)"},{"letra":"B","texto":"Neurofibromatosis Tipo 2"},{"letra":"C","texto":"Síndrome de Peutz-Jeghers"},{"letra":"D","texto":"Xeroderma Pigmentoso"}],"respuesta":"A) Esclerosis Tuberosa (Enfermedad de Pringle-Bourneville)","explicacion":"Angiofibromas faciales, parche de Shagreen y fibromas periungueales de Koenen son estigmas cutáneos característicos de esclerosis tuberosa.","fija":"Angiofibromas + Shagreen + Koenen = esclerosis tuberosa.","href":"examenes.html?pregunta=168"},"169":{"id":169,"tipo":"examen","titulo":"Pregunta 169","tema":"PARTE 9: DERMATOLOGÍA PEDIÁTRICA, TRAUMÁTICA Y TERAPÉUTICA GENERAL","frente":"Paciente neonato con ampollas y erosiones al mínimo trauma mecánico desde el nacimiento. La biopsia revela fragilidad de las uniones epiteliales genéticamente determinada. ¿Qué grupo de patologías se sospecha?","opciones":[{"letra":"A","texto":"Epidermólisis Ampollosa (Mecanoampollosa)"},{"letra":"B","texto":"Pénfigo Neonatal"},{"letra":"C","texto":"Dermatitis del Pañal severa"},{"letra":"D","texto":"Síndrome de Piel Escaldada"}],"respuesta":"A) Epidermólisis Ampollosa (Mecanoampollosa)","explicacion":"Ampollas y erosiones desde el nacimiento desencadenadas por trauma mínimo sugieren epidermólisis ampollosa hereditaria, un grupo de trastornos por defectos estructurales de adhesión cutánea.","fija":"Fragilidad mecánica desde nacimiento = epidermólisis ampollosa.","href":"examenes.html?pregunta=169"},"170":{"id":170,"tipo":"examen","titulo":"Pregunta 170","tema":"PARTE 9: DERMATOLOGÍA PEDIÁTRICA, TRAUMÁTICA Y TERAPÉUTICA GENERAL","frente":"El Síndrome de Gorlin (Síndrome del Carcinoma Basocelular Nevoide) es una enfermedad genética caracterizada por múltiplos carcinomas basocelulares a edades tempranas, fositas palmo-plantares (pits) y:","opciones":[{"letra":"A","texto":"Queratoquistes odontogénicos en los maxilares"},{"letra":"B","texto":"Melanomas múltiples"},{"letra":"C","texto":"Alopecia universal"},{"letra":"D","texto":"Nefritis lúpica"}],"respuesta":"A) Queratoquistes odontogénicos en los maxilares","explicacion":"El síndrome de Gorlin combina múltiples carcinomas basocelulares tempranos, pits palmoplantares y queratoquistes odontogénicos, entre otros hallazgos.","fija":"Gorlin: CBC múltiples + pits + queratoquistes maxilares.","href":"examenes.html?pregunta=170"},"171":{"id":171,"tipo":"examen","titulo":"Pregunta 171","tema":"PARTE 9: DERMATOLOGÍA PEDIÁTRICA, TRAUMÁTICA Y TERAPÉUTICA GENERAL","frente":"Tratamiento farmacológico de elección en la anafilaxia con compromiso respiratorio o hemodinámico por reacción alérgica grave:","opciones":[{"letra":"A","texto":"Adrenalina (Epinefrina) intramuscular en muslo anterolateral"},{"letra":"B","texto":"Hidrocortisona intravenosa únicamente"},{"letra":"C","texto":"Clorfenamina intravenosa pura"},{"letra":"D","texto":"Salbutamol nebulizado solo"}],"respuesta":"A) Adrenalina (Epinefrina) intramuscular en muslo anterolateral","explicacion":"La adrenalina intramuscular en muslo anterolateral es el tratamiento inmediato de primera línea en anafilaxia con compromiso respiratorio o hemodinámico. Antihistamínicos y corticoides son adyuvantes.","fija":"Anafilaxia: adrenalina IM primero.","href":"examenes.html?pregunta=171"},"172":{"id":172,"tipo":"examen","titulo":"Pregunta 172","tema":"PARTE 9: DERMATOLOGÍA PEDIÁTRICA, TRAUMÁTICA Y TERAPÉUTICA GENERAL","frente":"Antihistamínico H1 de primera generación (sedante) útil cuando se requiere sedación nocturna por prurito intenso:","opciones":[{"letra":"A","texto":"Clorfenamina o Difenhidramina"},{"letra":"B","texto":"Cetirizina"},{"letra":"C","texto":"Loratadina"},{"letra":"D","texto":"Fexofenadina"}],"respuesta":"A) Clorfenamina o Difenhidramina","explicacion":"Clorfenamina y difenhidramina son antihistamínicos H1 de primera generación con efecto sedante, útil cuando el prurito nocturno impide dormir, aunque sus efectos anticolinérgicos limitan uso crónico.","fija":"H1 de primera generación: más sedación.","href":"examenes.html?pregunta=172"},"173":{"id":173,"tipo":"examen","titulo":"Pregunta 173","tema":"PARTE 9: DERMATOLOGÍA PEDIÁTRICA, TRAUMÁTICA Y TERAPÉUTICA GENERAL","frente":"Antihistamínico H1 de segunda generación (no sedante) de elección para tratamiento ambulatorio prolongado de rinitis y urticaria:","opciones":[{"letra":"A","texto":"Cetirizina, Loratadina o Fexofenadina"},{"letra":"B","texto":"Prometazina"},{"letra":"C","texto":"Hidroxizina"},{"letra":"D","texto":"Ciproheptadina"}],"respuesta":"A) Cetirizina, Loratadina o Fexofenadina","explicacion":"Cetirizina, loratadina y fexofenadina son H1 de segunda generación y se prefieren para tratamiento prolongado por menor sedación y mejor perfil de seguridad.","fija":"H1 de segunda generación: preferidos para uso ambulatorio crónico.","href":"examenes.html?pregunta=173"},"174":{"id":174,"tipo":"examen","titulo":"Pregunta 174","tema":"PARTE 9: DERMATOLOGÍA PEDIÁTRICA, TRAUMÁTICA Y TERAPÉUTICA GENERAL","frente":"¿Cuál de los siguientes corticoides tópicos se clasifica como de potencia muy alta (Clase I)?","opciones":[{"letra":"A","texto":"Propionato de Clobetasol al 0.05%"},{"letra":"B","texto":"Valerato de Betametasona al 0.1%"},{"letra":"C","texto":"Acetónido de Triamcinolona al 0.1%"},{"letra":"D","texto":"Hidrocortisona al 1%"}],"respuesta":"A) Propionato de Clobetasol al 0.05%","explicacion":"Clobetasol propionato 0,05% es un corticoide tópico de muy alta potencia. Debe limitarse en duración y evitarse en áreas de piel fina salvo indicación específica.","fija":"Clobetasol 0,05% = potencia muy alta.","href":"examenes.html?pregunta=174"},"175":{"id":175,"tipo":"examen","titulo":"Pregunta 175","tema":"PARTE 9: DERMATOLOGÍA PEDIÁTRICA, TRAUMÁTICA Y TERAPÉUTICA GENERAL","frente":"Efecto secundario adverso local característico por el uso prolongado e indiscriminado de corticoides tópicos de alta potencia en la cara:","opciones":[{"letra":"A","texto":"Atrofia cutánea, telangiectasias, estrías e inducción de dermatitis rosaceiforme / perioral"},{"letra":"B","texto":"Hipertricosis localizada sin atrofia"},{"letra":"C","texto":"Hiperpigmentación difusa epidérmica"},{"letra":"D","texto":"Queratinización acelerada"}],"respuesta":"A) Atrofia cutánea, telangiectasias, estrías e inducción de dermatitis rosaceiforme / perioral","explicacion":"El uso prolongado de corticoides potentes en cara puede causar atrofia, telangiectasias, estrías y dermatitis rosaceiforme/perioral. La cara es especialmente susceptible a estos efectos.","fija":"Corticoide potente crónico en cara: atrofia y telangiectasias.","href":"examenes.html?pregunta=175"},"176":{"id":176,"tipo":"examen","titulo":"Pregunta 176","tema":"PARTE 9: DERMATOLOGÍA PEDIÁTRICA, TRAUMÁTICA Y TERAPÉUTICA GENERAL","frente":"El uso de retinoides sistémicos (Acitretina) en la psoriasis pustulosa exige evitar el embarazo tras su suspensión durante un periodo mínimo de:","opciones":[{"letra":"A","texto":"3 años"},{"letra":"B","texto":"1 mes"},{"letra":"C","texto":"6 meses"},{"letra":"D","texto":"10 años"}],"respuesta":"A) 3 años","explicacion":"La acitretina es altamente teratógena y, de acuerdo con el esquema señalado en el banco, debe evitarse embarazo durante tres años después de suspenderla. Este punto es crucial en mujeres con potencial reproductivo.","fija":"Acitretina: evitar embarazo por 3 años tras suspensión.","href":"examenes.html?pregunta=176"},"177":{"id":177,"tipo":"examen","titulo":"Pregunta 177","tema":"PARTE 9: DERMATOLOGÍA PEDIÁTRICA, TRAUMÁTICA Y TERAPÉUTICA GENERAL","frente":"Antifúngico oral de elección para el tratamiento de las onicomicosis dermatofíticas por su alta afinidad por la queratina y efecto fungicida:","opciones":[{"letra":"A","texto":"Terbinafina"},{"letra":"B","texto":"Nistatina"},{"letra":"C","texto":"Griseofulvina"},{"letra":"D","texto":"Fluconazol a dosis diaria"}],"respuesta":"A) Terbinafina","explicacion":"Terbinafina oral es fungicida frente a dermatofitos y se concentra en queratina, por lo que es una de las principales opciones para onicomicosis dermatofítica.","fija":"Onicomicosis dermatofítica: terbinafina oral.","href":"examenes.html?pregunta=177"},"178":{"id":178,"tipo":"examen","titulo":"Pregunta 178","tema":"PARTE 9: DERMATOLOGÍA PEDIÁTRICA, TRAUMÁTICA Y TERAPÉUTICA GENERAL","frente":"La Quimioterapia fotodinámica (PUVA) en dermatología combina la administración de Psoralenos con exposición a:","opciones":[{"letra":"A","texto":"Radiación Ultravioleta A (UVA)"},{"letra":"B","texto":"Radiación Ultravioleta C (UVC)"},{"letra":"C","texto":"Rayos X"},{"letra":"D","texto":"Luz infrarroja pura"}],"respuesta":"A) Radiación Ultravioleta A (UVA)","explicacion":"PUVA combina psoralenos fotosensibilizantes con radiación UVA. Se utiliza en algunas dermatosis inflamatorias y linfomas cutáneos bajo indicaciones específicas.","fija":"PUVA = psoraleno + UVA.","href":"examenes.html?pregunta=178"},"179":{"id":179,"tipo":"examen","titulo":"Pregunta 179","tema":"PARTE 9: DERMATOLOGÍA PEDIÁTRICA, TRAUMÁTICA Y TERAPÉUTICA GENERAL","frente":"En el manejo del prurito uremico en pacientes con insuficiencia renal crónica en hemodiálisis, una opción terapéutica física efectiva es:","opciones":[{"letra":"A","texto":"Fototerapia UVB de banda estrecha"},{"letra":"B","texto":"Crioterapia con nitrógeno"},{"letra":"C","texto":"Exfoliación química con ácido glicólico"},{"letra":"D","texto":"Dermoabrasión"}],"respuesta":"A) Fototerapia UVB de banda estrecha","explicacion":"La fototerapia UVB de banda estrecha puede reducir prurito urémico en pacientes seleccionados con insuficiencia renal crónica. Es una opción física cuando medidas generales son insuficientes.","fija":"Prurito urémico: UVB de banda estrecha puede ayudar.","href":"examenes.html?pregunta=179"},"180":{"id":180,"tipo":"examen","titulo":"Pregunta 180","tema":"PARTE 9: DERMATOLOGÍA PEDIÁTRICA, TRAUMÁTICA Y TERAPÉUTICA GENERAL","frente":"Medicamento inmunomodulador tópico (inhibidor de la calcineurina) utilizado como alternativa a los corticoides en la dermatitis atópica para evitar la atrofia cutánea:","opciones":[{"letra":"A","texto":"Tacrolimus o Pimecrolimus tópico"},{"letra":"B","texto":"Imiquimod"},{"letra":"C","texto":"5-Fluorouracilo"},{"letra":"D","texto":"Metronidazol"}],"respuesta":"A) Tacrolimus o Pimecrolimus tópico","explicacion":"Tacrolimus y pimecrolimus son inhibidores tópicos de calcineurina que controlan inflamación sin producir atrofia cutánea, por lo que son útiles en cara y pliegues de dermatitis atópica.","fija":"Atopia en zonas sensibles: tacrolimus/pimecrolimus.","href":"examenes.html?pregunta=180"},"181":{"id":181,"tipo":"examen","titulo":"Pregunta 181","tema":"PARTE 10: CASOS CLÍNICOS INTEGRADOS TIPO ENAM Y CORRELACIÓN DIAGNÓSTICA","frente":"Paciente de 25 años con placas eritematosas y escamas gruesas en codos y rodillas. Presenta cambios en uñas de las manos con pequeñas depresiones punctiformes en la lámina ungueal. ¿Cómo se denomina este hallazgo ungueal?","opciones":[{"letra":"A","texto":"Coiloniquia"},{"letra":"B","texto":"Pitting ungueal (uñas en dedal)"},{"letra":"C","texto":"Anoniquia"},{"letra":"D","texto":"Leuconiquia estriada"}],"respuesta":"B) Pitting ungueal (uñas en dedal)","explicacion":"Las depresiones puntiformes de la lámina ungueal en psoriasis se denominan pitting ungueal o uñas en dedal. Reflejan afectación de matriz ungueal.","fija":"Psoriasis ungueal: pitting.","href":"examenes.html?pregunta=181"},"182":{"id":182,"tipo":"examen","titulo":"Pregunta 182","tema":"PARTE 10: CASOS CLÍNICOS INTEGRADOS TIPO ENAM Y CORRELACIÓN DIAGNÓSTICA","frente":"Paciente de 18 años acude por brote severo de pústulas y comedones en cara y tórax superior. Se inicia Isotretinoína oral. A las 2 semanas presenta un empeoramiento súbito con lesiones noduloulcerosas hemorrágicas, fiebre y artralgias. ¿De qué complicación se trata?","opciones":[{"letra":"A","texto":"Acné Fulminans"},{"letra":"B","texto":"Acné Conglobata"},{"letra":"C","texto":"Síndrome DRESS"},{"letra":"D","texto":"Folliculitis por Gram negativos"}],"respuesta":"A) Acné Fulminans","explicacion":"El empeoramiento abrupto con lesiones noduloulcerosas hemorrágicas, fiebre y artralgias en un joven con acné severo corresponde a acné fulminans, una variante inflamatoria sistémica grave.","fija":"Acné fulminans: lesiones ulceronecróticas + fiebre/artralgias.","href":"examenes.html?pregunta=182"},"183":{"id":183,"tipo":"examen","titulo":"Pregunta 183","tema":"PARTE 10: CASOS CLÍNICOS INTEGRADOS TIPO ENAM Y CORRELACIÓN DIAGNÓSTICA","frente":"Mujer de 45 años con erupción de pápulas eritematosa violáceas e intenso prurito en muñecas. Presenta además lesiones blanquecinas en retículo en la mucosa oral dolorosas a la ingesta de alimentos picantes. ¿Cuál es la conducta diagnóstica de elección?","opciones":[{"letra":"A","texto":"Biopsia de piel para confirmar Liquen Plano"},{"letra":"B","texto":"Dosaje de IgE sérica total"},{"letra":"C","texto":"Cultivo fúngico de mucosa oral"},{"letra":"D","texto":"Prueba de parche alergológico"}],"respuesta":"A) Biopsia de piel para confirmar Liquen Plano","explicacion":"La clínica es compatible con liquen plano cutáneo y oral; la biopsia permite confirmar una dermatitis de interfase con infiltrado en banda y daño basal. Es la prueba más útil entre las opciones.","fija":"Liquen plano: biopsia cuando se requiere confirmación.","href":"examenes.html?pregunta=183"},"184":{"id":184,"tipo":"examen","titulo":"Pregunta 184","tema":"PARTE 10: CASOS CLÍNICOS INTEGRADOS TIPO ENAM Y CORRELACIÓN DIAGNÓSTICA","frente":"Paciente de 70 años con placa eritematosa infiltrada en mejilla de 2 cm de diámetro, de bordes mal definidos, áspera al tacto, semejante a papel de lija. Histología: displasia parcial de queratinocitos en la epidermis. Diagnóstico:","opciones":[{"letra":"A","texto":"Queratosis actínica"},{"letra":"B","texto":"Carcinoma basocelular"},{"letra":"C","texto":"Melanoma in situ"},{"letra":"D","texto":"Queratosis seborreica"}],"respuesta":"A) Queratosis actínica","explicacion":"Una lesión áspera en piel fotoexpuesta con displasia parcial de queratinocitos corresponde a queratosis actínica, una lesión premaligna relacionada con radiación UV crónica.","fija":"Queratosis actínica: aspereza tipo lija + displasia epidérmica.","href":"examenes.html?pregunta=184"},"185":{"id":185,"tipo":"examen","titulo":"Pregunta 185","tema":"PARTE 10: CASOS CLÍNICOS INTEGRADOS TIPO ENAM Y CORRELACIÓN DIAGNÓSTICA","frente":"Paciente diabético tipo 2 acude por úlcera en talón de pie derecho, indolora, profunda, rodeada de un callo hiperqueratósico en punto de apoyo. Pulsos pedios presentes. ¿Cuál es la etiología principal de la úlcera?","opciones":[{"letra":"A","texto":"Neuropatía diabética motora y sensitiva (Mal perforante plantar)"},{"letra":"B","texto":"Isquemia arterial aguda"},{"letra":"C","texto":"Insuficiencia venosa crónica"},{"letra":"D","texto":"Vasculitis leucocitoclástica"}],"respuesta":"A) Neuropatía diabética motora y sensitiva (Mal perforante plantar)","explicacion":"Una úlcera plantar indolora sobre punto de presión, rodeada por callo y con pulsos conservados, apunta a neuropatía diabética sensitiva y motora más que a isquemia arterial.","fija":"Pie diabético neuropático: úlcera indolora en punto de apoyo con pulsos presentes.","href":"examenes.html?pregunta=185"},"186":{"id":186,"tipo":"examen","titulo":"Pregunta 186","tema":"PARTE 10: CASOS CLÍNICOS INTEGRADOS TIPO ENAM Y CORRELACIÓN DIAGNÓSTICA","frente":"Paciente inmunodeficiente presenta múltiples pápulas eritematosas vascularizadas similares a granulomas piógenos en piel, acompañadas de fiebre y hepatoesplenomegalia. La biopsia con tinción de Warthin-Starry muestra bacilos gramnegativos intra y extracelulares. Diagnóstico:","opciones":[{"letra":"A","texto":"Angiomatosis bacilar (Bartonella henselae / quintana)"},{"letra":"B","texto":"Sarcoma de Kaposi"},{"letra":"C","texto":"Hemangiomatosis diseminada"},{"letra":"D","texto":"Síndrome de Sweet"}],"respuesta":"A) Angiomatosis bacilar (Bartonella henselae / quintana)","explicacion":"En inmunodeficiencia, lesiones vasculares similares a granulomas piógenos con Warthin-Starry positivo orientan a angiomatosis bacilar por Bartonella henselae o B. quintana.","fija":"Angiomatosis bacilar: Bartonella + Warthin-Starry.","href":"examenes.html?pregunta=186"},"187":{"id":187,"tipo":"examen","titulo":"Pregunta 187","tema":"PARTE 10: CASOS CLÍNICOS INTEGRADOS TIPO ENAM Y CORRELACIÓN DIAGNÓSTICA","frente":"Paciente de 30 años presenta alopecia en placas circulares bien delimitadas en cuero cabelludo, sin descamación ni signos inflamatorios. La piel de la zona alopécica es lisa y suave. Diagnóstico:","opciones":[{"letra":"A","texto":"Alopecia Areata"},{"letra":"B","texto":"Tiña capitis"},{"letra":"C","texto":"Alopecia androgenética"},{"letra":"D","texto":"Licuen plano pilar"}],"respuesta":"A) Alopecia Areata","explicacion":"Placas circulares de alopecia no cicatricial, lisas y sin descamación son clásicas de alopecia areata. La tiña suele mostrar descamación y cabellos quebrados.","fija":"Alopecia areata: placa lisa, no cicatricial y sin descamación.","href":"examenes.html?pregunta=187"},"188":{"id":188,"tipo":"examen","titulo":"Pregunta 188","tema":"PARTE 10: CASOS CLÍNICOS INTEGRADOS TIPO ENAM Y CORRELACIÓN DIAGNÓSTICA","frente":"Paciente de 50 años acude por eritema facial en mariposa que respeta los surcos nasogenianos, fotosensibilidad acentuada y artralgias en manos. Anticuerpos ANA y Anti-DNAdc positivos. ¿Diagnóstico principal?","opciones":[{"letra":"A","texto":"Lupus Eritematoso Sistémico"},{"letra":"B","texto":"Rosácea papulopustulosa"},{"letra":"C","texto":"Dermatomiositis"},{"letra":"D","texto":"Psoriasis facial"}],"respuesta":"A) Lupus Eritematoso Sistémico","explicacion":"Eritema malar que respeta surcos nasogenianos, fotosensibilidad, artralgias y anti-dsDNA positivos orientan a lupus eritematoso sistémico. La serología apoya el diagnóstico en el contexto adecuado.","fija":"LES: rash malar + fotosensibilidad + anti-dsDNA.","href":"examenes.html?pregunta=188"},"189":{"id":189,"tipo":"examen","titulo":"Pregunta 189","tema":"PARTE 10: CASOS CLÍNICOS INTEGRADOS TIPO ENAM Y CORRELACIÓN DIAGNÓSTICA","frente":"En el Lupus Eritematoso Discoide crónico, las lesiones cutáneas características se describen como:","opciones":[{"letra":"A","texto":"Placas eritematosas atróficas con hiperqueratosis folicular (tapones córneos) y telangiectasias que dejan cicatriz central"},{"letra":"B","texto":"Ampollas desnudadas sin cicatriz"},{"letra":"C","texto":"Habones migratorios"},{"letra":"D","texto":"Escamas nacaradas abundantes sin atrofia"}],"respuesta":"A) Placas eritematosas atróficas con hiperqueratosis folicular (tapones córneos) y telangiectasias que dejan cicatriz central","explicacion":"El lupus discoide produce placas eritematosas con hiperqueratosis folicular, atrofia y telangiectasias que evolucionan a cicatriz. En cuero cabelludo puede causar alopecia cicatricial.","fija":"Lupus discoide: atrofia + tapones foliculares + cicatriz.","href":"examenes.html?pregunta=189"},"190":{"id":190,"tipo":"examen","titulo":"Pregunta 190","tema":"PARTE 10: CASOS CLÍNICOS INTEGRADOS TIPO ENAM Y CORRELACIÓN DIAGNÓSTICA","frente":"Paciente con infección por VIH presenta lesiones blanquecinas no desprendibles con raspado en los bordes laterales de la lengua. ¿Cuál es el diagnóstico y su agente etiologico?","opciones":[{"letra":"A","texto":"Leucoplaxia Vellosa Oral – Virus de Epstein-Barr (VEB)"},{"letra":"B","texto":"Candidiasis oral – Candida albicans"},{"letra":"C","texto":"Liquen plano oral – VHC"},{"letra":"D","texto":"Sarcoma de Kaposi mucosal – VHH-8"}],"respuesta":"A) Leucoplaxia Vellosa Oral – Virus de Epstein-Barr (VEB)","explicacion":"Las placas blanquecinas laterales de lengua que no se desprenden al raspado en VIH sugieren leucoplasia vellosa oral asociada a virus Epstein-Barr. La candidiasis suele poder desprenderse.","fija":"VIH + placa blanca lateral no desprendible = leucoplasia vellosa por VEB.","href":"examenes.html?pregunta=190"},"191":{"id":191,"tipo":"examen","titulo":"Pregunta 191","tema":"PARTE 10: CASOS CLÍNICOS INTEGRADOS TIPO ENAM Y CORRELACIÓN DIAGNÓSTICA","frente":"Paciente de 65 años acude por erosiones y ampollas en zonas expuestas al sol. Presenta orina de color oscuro (marrón-rojiza). Los exámenes muestran acumulación de uroporfirinas. Diagnóstico:","opciones":[{"letra":"A","texto":"Porfiria Cutánea Tarda"},{"letra":"B","texto":"Fenilcetonuria"},{"letra":"C","texto":"Albinismo oculocutáneo"},{"letra":"D","texto":"Ictericia obstructiva"}],"respuesta":"A) Porfiria Cutánea Tarda","explicacion":"La fragilidad cutánea fotoexpuesta, ampollas y orina oscura con acumulación de uroporfirinas corresponden a porfiria cutánea tarda.","fija":"Porfiria cutánea tarda: fotosensibilidad ampollosa + uroporfirinas.","href":"examenes.html?pregunta=191"},"192":{"id":192,"tipo":"examen","titulo":"Pregunta 192","tema":"PARTE 10: CASOS CLÍNICOS INTEGRADOS TIPO ENAM Y CORRELACIÓN DIAGNÓSTICA","frente":"La Deficiencia de Zinc hereditaria (Acrodermatitis Enteropática) se manifiesta en lactantes al retirar la lactancia materna mediante la tríada clásica de:","opciones":[{"letra":"A","texto":"Dermatitis acral y periorificial, Alopecia y Diarrea"},{"letra":"B","texto":"Psoriasis, Convulsiones y Cardiopatía"},{"letra":"C","texto":"Ampollas, Ictericia y Espasmfilia"},{"letra":"D","texto":"Eritema mariposa, Artritis y Anemia"}],"respuesta":"A) Dermatitis acral y periorificial, Alopecia y Diarrea","explicacion":"La acrodermatitis enteropática por deficiencia de zinc produce la tríada de dermatitis acral/periorificial, alopecia y diarrea, a menudo al disminuir el aporte de zinc tras destete.","fija":"Déficit de zinc: dermatitis acral/periorificial + alopecia + diarrea.","href":"examenes.html?pregunta=192"},"193":{"id":193,"tipo":"examen","titulo":"Pregunta 193","tema":"PARTE 10: CASOS CLÍNICOS INTEGRADOS TIPO ENAM Y CORRELACIÓN DIAGNÓSTICA","frente":"Paciente varón de 40 años presenta prurito intenso en axilas y pliegues. Al examen presenta pápulas pardo-violáceas y surcos excoriados. Se objetiva el ácaro Sarcoptes scabiei. ¿Qué tipo de tratamiento debe recibir su entorno cercano?","opciones":[{"letra":"A","texto":"Tratamiento simultáneo a todos los contactos convivientes aunque estén asintomáticos"},{"letra":"B","texto":"Tratar solo si desarrollan síntomas clínicos"},{"letra":"C","texto":"Profilaxis con corticoides a la familia"},{"letra":"D","texto":"Aislamiento hospitalario por 14 días"}],"respuesta":"A) Tratamiento simultáneo a todos los contactos convivientes aunque estén asintomáticos","explicacion":"En escabiosis deben tratarse simultáneamente los convivientes cercanos aunque estén asintomáticos, porque el periodo de incubación puede ser prolongado y la reinfestación es frecuente.","fija":"Escabiosis: tratar contactos al mismo tiempo.","href":"examenes.html?pregunta=193"},"194":{"id":194,"tipo":"examen","titulo":"Pregunta 194","tema":"PARTE 10: CASOS CLÍNICOS INTEGRADOS TIPO ENAM Y CORRELACIÓN DIAGNÓSTICA","frente":"La Escabiosis Noruega (o costrosa) se caracteriza por hiperqueratosis masiva con millones de ácaros y se presenta típicamente en pacientes:","opciones":[{"letra":"A","texto":"Inmunodeprimidos (VIH, HTLV-1, desnutrición) o con discapacidad neurológica/senil"},{"letra":"B","texto":"Deportistas de alto rendimiento"},{"letra":"C","texto":"Niños atópicos sin otras enfermedades"},{"letra":"D","texto":"Embarazadas primigestas"}],"respuesta":"A) Inmunodeprimidos (VIH, HTLV-1, desnutrición) o con discapacidad neurológica/senil","explicacion":"La escabiosis costrosa ocurre sobre todo en inmunodeprimidos, ancianos, desnutridos o personas con discapacidad neurológica y alberga una carga enorme de ácaros, por lo que es muy contagiosa.","fija":"Escabiosis costrosa: inmunosupresión y millones de ácaros.","href":"examenes.html?pregunta=194"},"195":{"id":195,"tipo":"examen","titulo":"Pregunta 195","tema":"PARTE 10: CASOS CLÍNICOS INTEGRADOS TIPO ENAM Y CORRELACIÓN DIAGNÓSTICA","frente":"En un paciente quemado que presenta ampollas de fondo rosado, muy dolorosas al tacto, que conservan los anexos cutáneos, ¿qué profundidad de quemadura presenta?","opciones":[{"letra":"A","texto":"Segundo grado superficial (Dérmica superficial)"},{"letra":"B","texto":"Primer grado (Epidérmica)"},{"letra":"C","texto":"Segundo grado profundo (Dérmica profunda)"},{"letra":"D","texto":"Tercer grado (Espesor total)"}],"respuesta":"A) Segundo grado superficial (Dérmica superficial)","explicacion":"Una quemadura con ampollas, fondo rosado, dolor intenso y anexos conservados corresponde a segundo grado superficial o dérmica superficial. La preservación de anexos permite reepitelización.","fija":"Quemadura dérmica superficial: ampollas, rosada y muy dolorosa.","href":"examenes.html?pregunta=195"},"196":{"id":196,"tipo":"examen","titulo":"Pregunta 196","tema":"PARTE 10: CASOS CLÍNICOS INTEGRADOS TIPO ENAM Y CORRELACIÓN DIAGNÓSTICA","frente":"Las quemaduras de Tercer Grado (Espesor Total) se caracterizan por ser:","opciones":[{"letra":"A","texto":"Indoloras (anestesiadas por destrucción de terminaciones nerviosas), de aspecto blanquecino o acartonado (escara)"},{"letra":"B","texto":"Extremadamente dolorosas con eritema seco"},{"letra":"C","texto":"Ampollas hiperalgésicas transparentes"},{"letra":"D","texto":"Lesiones puramente epidérmicas sin cicatriz"}],"respuesta":"A) Indoloras (anestesiadas por destrucción de terminaciones nerviosas), de aspecto blanquecino o acartonado (escara)","explicacion":"Las quemaduras de tercer grado destruyen toda la dermis y terminaciones nerviosas, por lo que pueden ser indoloras y de aspecto blanco, céreo o acartonado con escara.","fija":"Tercer grado: espesor total, anestesia y escara.","href":"examenes.html?pregunta=196"},"197":{"id":197,"tipo":"examen","titulo":"Pregunta 197","tema":"PARTE 10: CASOS CLÍNICOS INTEGRADOS TIPO ENAM Y CORRELACIÓN DIAGNÓSTICA","frente":"El fenómeno pathergy (Patergia positivo), definido como la formación de una pústula o pápula inflamatoria 24-48 horas después de una punción con aguja estéril en la piel, es característico del Síndrome de:","opciones":[{"letra":"A","texto":"Behçet y Síndrome de Sweet"},{"letra":"B","texto":"Stevens-Johnson"},{"letra":"C","texto":"Reiter"},{"letra":"D","texto":"Raynaud"}],"respuesta":"A) Behçet y Síndrome de Sweet","explicacion":"La patergia es una respuesta inflamatoria exagerada a traumatismo mínimo y se asocia clásicamente con enfermedad de Behçet; también puede observarse en dermatosis neutrofílicas como síndrome de Sweet.","fija":"Patergia: Behçet y dermatosis neutrofílicas.","href":"examenes.html?pregunta=197"},"198":{"id":198,"tipo":"examen","titulo":"Pregunta 198","tema":"PARTE 10: CASOS CLÍNICOS INTEGRADOS TIPO ENAM Y CORRELACIÓN DIAGNÓSTICA","frente":"Paciente femenina de 30 años presenta manchas hipercromicas marrón-grisáceas simétricas en frente, mejillas y labio superior, que empeoran con la exposición solar. No refiere prurito. Diagnóstico:","opciones":[{"letra":"A","texto":"Melasma (Cloasma)"},{"letra":"B","texto":"Vitíligo"},{"letra":"C","texto":"Léntigo senil"},{"letra":"D","texto":"Efélides simples"}],"respuesta":"A) Melasma (Cloasma)","explicacion":"Máculas marrón-grisáceas simétricas en frente, mejillas y labio superior que empeoran con el sol son típicas de melasma. Suele relacionarse con radiación UV y factores hormonales.","fija":"Melasma: hiperpigmentación facial simétrica fotoagravada.","href":"examenes.html?pregunta=198"},"199":{"id":199,"tipo":"examen","titulo":"Pregunta 199","tema":"PARTE 10: CASOS CLÍNICOS INTEGRADOS TIPO ENAM Y CORRELACIÓN DIAGNÓSTICA","frente":"El Vitíligo es una dermatosis acromiante autoinmune caracterizada por la destrucción selectiva de:","opciones":[{"letra":"A","texto":"Melanocitos (con ausencia completa de melanina en las lesiones)"},{"letra":"B","texto":"Queratinocitos del estrato córneo"},{"letra":"C","texto":"Células de Langerhans"},{"letra":"D","texto":"Adipocitos subcutáneos"}],"respuesta":"A) Melanocitos (con ausencia completa de melanina en las lesiones)","explicacion":"El vitíligo se debe a pérdida autoinmune de melanocitos funcionales, produciendo áreas acrómicas sin melanina. Puede asociarse con otras enfermedades autoinmunes.","fija":"Vitíligo: destrucción selectiva de melanocitos.","href":"examenes.html?pregunta=199"},"200":{"id":200,"tipo":"examen","titulo":"Pregunta 200","tema":"PARTE 10: CASOS CLÍNICOS INTEGRADOS TIPO ENAM Y CORRELACIÓN DIAGNÓSTICA","frente":"¿Cuál es el tratamiento inicial de elección en parches limitados de Vitíligo en fase activa?","opciones":[{"letra":"A","texto":"Corticoides tópicos de alta potencia o inhibidores tópicos de la calcineurina"},{"letra":"B","texto":"Hidroquinona al 4% tópica"},{"letra":"C","texto":"Antibióticos orales por 3 meses"},{"letra":"D","texto":"Excéresis quirúrgica de todas las máculas"}],"respuesta":"A) Corticoides tópicos de alta potencia o inhibidores tópicos de la calcineurina","explicacion":"En vitíligo localizado activo, el tratamiento inicial suele ser antiinflamatorio tópico con corticoides o inhibidores de calcineurina, según localización y características del paciente.","fija":"Vitíligo limitado: corticoide tópico o inhibidor de calcineurina.","href":"examenes.html?pregunta=200"}},"banco":{"1":{"id":1,"tipo":"banco","titulo":"Psoriasis en placas","tema":"Psoriasis en placas","frente":"Paciente varón de 23 años acude al Servicio de Dermatología del Hospital Nacional Daniel Alcides Carrión por ocho meses de evolución con exacerbaciones periódicas. Presenta lesiones crónicas recurrentes sobre codos y rodillas. Al examen se observan áreas cutáneas sobreelevadas de superficie amplia rojizas de contorno nítido cubiertas por escamas blanquecinas. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de contorno nítido; predominan en superficies externas de las extremidades.","respuesta":"Psoriasis en placas","explicacion":"Placas eritematosas bien delimitadas con escamas blanquecinas o plateadas. Generalmente clínico. La biopsia puede utilizarse cuando la presentación es atípica.","fija":"Placa eritematosa bien delimitada con escama plateada en superficies extensoras sugiere psoriasis.","href":"banco.html?caso=1"},"2":{"id":2,"tipo":"banco","titulo":"Psoriasis en placas","tema":"Psoriasis en placas","frente":"Paciente mujer de 51 años acude al Servicio de Dermatología del Hospital Nacional Hipólito Unanue por seis meses de evolución progresiva. Presenta lesiones descamativas simétricas en superficies extensoras y cuero cabelludo. Refiere exacerbaciones periódicas. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de contorno nítido; predominan en superficies externas de las extremidades.","respuesta":"Psoriasis en placas","explicacion":"Placas eritematosas bien delimitadas con escamas blanquecinas o plateadas. Generalmente clínico. La biopsia puede utilizarse cuando la presentación es atípica.","fija":"Placa eritematosa bien delimitada con escama plateada en superficies extensoras sugiere psoriasis.","href":"banco.html?caso=2"},"3":{"id":3,"tipo":"banco","titulo":"Dermatitis atópica","tema":"Dermatitis atópica","frente":"Paciente de 9 años, acompañada de su madre, acude al Servicio de Dermatología del Hospital Nacional Cayetano Heredia por ocho meses de evolución con exacerbaciones periódicas. Tiene antecedente de asma y presenta prurito intenso y lesiones eccematosas crónicas en pliegues antecubitales y poplíteos. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de transición gradual hacia la piel vecina; predominan en pliegues de flexión.","respuesta":"Dermatitis atópica","explicacion":"Eritema, pápulas, excoriaciones, descamación y liquenificación en fases crónicas. Clínico, basado en morfología, distribución, prurito y antecedentes atópicos.","fija":"Prurito crónico + superficies flexoras + antecedentes de atopia.","href":"banco.html?caso=3"},"4":{"id":4,"tipo":"banco","titulo":"Dermatitis atópica","tema":"Dermatitis atópica","frente":"Paciente mujer de 32 años acude al Servicio de Dermatología del Hospital Nacional Daniel Alcides Carrión por seis meses de evolución progresiva. Con rinitis alérgica presenta brotes recurrentes de prurito, xerosis y áreas cutáneas sobreelevadas de superficie amplia eccematosas predominantes en superficies flexoras. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de transición gradual hacia la piel vecina; predominan en pliegues de flexión.","respuesta":"Dermatitis atópica","explicacion":"Eritema, pápulas, excoriaciones, descamación y liquenificación en fases crónicas. Clínico, basado en morfología, distribución, prurito y antecedentes atópicos.","fija":"Prurito crónico + superficies flexoras + antecedentes de atopia.","href":"banco.html?caso=4"},"5":{"id":5,"tipo":"banco","titulo":"Dermatitis seborreica","tema":"Dermatitis seborreica","frente":"Paciente mujer de 40 años acude al Servicio de Dermatología del Hospital Nacional Daniel Alcides Carrión por ocho meses de evolución con exacerbaciones periódicas. Presenta enrojecimiento y descamación grasosa en cuero cabelludo, cejas y surcos nasolabiales. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de transición gradual hacia la piel vecina; predominan en cuero cabelludo, cejas, surcos nasolabiales u otras zonas ricas en sebo.","respuesta":"Dermatitis seborreica","explicacion":"Placas eritematosas con escamas finas o grasosas amarillentas. Principalmente clínico.","fija":"Escama grasosa en cuero cabelludo y surcos nasolabiales.","href":"banco.html?caso=5"},"6":{"id":6,"tipo":"banco","titulo":"Dermatitis seborreica","tema":"Dermatitis seborreica","frente":"Paciente mujer de 23 años acude al Servicio de Dermatología del Hospital Nacional Daniel Alcides Carrión por seis meses de evolución progresiva. Refiere caspa persistente con áreas cutáneas sobreelevadas de superficie amplia eritematodescamativas en regiones ricas en glándulas sebáceas. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de transición gradual hacia la piel vecina; predominan en cuero cabelludo, cejas, surcos nasolabiales u otras zonas ricas en sebo.","respuesta":"Dermatitis seborreica","explicacion":"Placas eritematosas con escamas finas o grasosas amarillentas. Principalmente clínico.","fija":"Escama grasosa en cuero cabelludo y surcos nasolabiales.","href":"banco.html?caso=6"},"7":{"id":7,"tipo":"banco","titulo":"Dermatitis de contacto alérgica","tema":"Dermatitis de contacto alérgica","frente":"Paciente varón de 18 años acude al Servicio de Dermatología del Hospital Nacional Daniel Alcides Carrión por tres semanas de evolución. Desarrolla prurito y enrojecimiento vesicular en muñeca después de usar una pulsera metálica nueva. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de contorno nítido; se limitan a una región anatómica.","respuesta":"Dermatitis de contacto alérgica","explicacion":"Eritema, pápulas, vesículas y eccema en el área de contacto. Clínico; pruebas epicutáneas ayudan a identificar el alérgeno.","fija":"La geometría o localización suele delatar el contacto causal.","href":"banco.html?caso=7"},"8":{"id":8,"tipo":"banco","titulo":"Dermatitis de contacto alérgica","tema":"Dermatitis de contacto alérgica","frente":"Paciente mujer de 40 años acude al Servicio de Dermatología del Hospital María Auxiliadora por dos meses de evolución. Trabajadora presenta áreas cutáneas sobreelevadas de superficie amplia eccematosas pruriginosas en manos luego del contacto repetido con un producto químico. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de contorno nítido; se limitan a una región anatómica.","respuesta":"Dermatitis de contacto alérgica","explicacion":"Eritema, pápulas, vesículas y eccema en el área de contacto. Clínico; pruebas epicutáneas ayudan a identificar el alérgeno.","fija":"La geometría o localización suele delatar el contacto causal.","href":"banco.html?caso=8"},"9":{"id":9,"tipo":"banco","titulo":"Liquen plano","tema":"Liquen plano","frente":"Paciente mujer de 39 años acude al Servicio de Dermatología del Hospital Nacional Hipólito Unanue por ocho meses de evolución con exacerbaciones periódicas. Presenta múltiples pequeñas elevaciones sólidas rojizo-purpúreas intensamente pruriginosas en muñecas y tobillos. En la inspección se observan pequeñas elevaciones sólidas, de aspecto rojizo-purpúreas y de contorno nítido; predominan en pliegues de flexión.","respuesta":"Liquen plano","explicacion":"Pápulas planas, poligonales, violáceas y pruriginosas, a veces con estrías de Wickham. Clínico y, cuando es necesario, biopsia cutánea.","fija":"Las clásicas 5 P: pruritic, purple, polygonal, planar papules.","href":"banco.html?caso=9"},"10":{"id":10,"tipo":"banco","titulo":"Liquen plano","tema":"Liquen plano","frente":"Paciente mujer de 65 años acude al Servicio de Dermatología del Hospital Nacional Arzobispo Loayza por seis meses de evolución progresiva. Presenta lesiones poligonales planas de color violáceo en superficies flexoras, algunas con finas líneas blanquecinas. En la inspección se observan pequeñas elevaciones sólidas, de aspecto rojizo-purpúreas y de contorno nítido; predominan en pliegues de flexión.","respuesta":"Liquen plano","explicacion":"Pápulas planas, poligonales, violáceas y pruriginosas, a veces con estrías de Wickham. Clínico y, cuando es necesario, biopsia cutánea.","fija":"Las clásicas 5 P: pruritic, purple, polygonal, planar papules.","href":"banco.html?caso=10"},"11":{"id":11,"tipo":"banco","titulo":"Pitiriasis rosada","tema":"Pitiriasis rosada","frente":"Paciente varón de 63 años acude al Servicio de Dermatología del Hospital Nacional Arzobispo Loayza por tres semanas de evolución. Presenta inicialmente una área cutánea sobreelevada de superficie amplia ovalada en tronco y días después múltiples lesiones menores siguiendo líneas de tensión. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de contorno nítido; se observan en varias regiones corporales.","respuesta":"Pitiriasis rosada","explicacion":"Placas ovaladas eritematosas con collarete descamativo. Clínico.","fija":"Placa heraldo seguida de patrón en árbol de Navidad.","href":"banco.html?caso=11"},"12":{"id":12,"tipo":"banco","titulo":"Pitiriasis rosada","tema":"Pitiriasis rosada","frente":"Paciente mujer de 20 años acude al Servicio de Dermatología del Hospital Nacional Edgardo Rebagliati Martins por dos meses de evolución. Presenta erupción autolimitada en tronco con distribución en árbol de Navidad. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de contorno nítido; se observan en varias regiones corporales.","respuesta":"Pitiriasis rosada","explicacion":"Placas ovaladas eritematosas con collarete descamativo. Clínico.","fija":"Placa heraldo seguida de patrón en árbol de Navidad.","href":"banco.html?caso=12"},"13":{"id":13,"tipo":"banco","titulo":"Urticaria","tema":"Urticaria","frente":"Paciente varón de 65 años acude al Servicio de Dermatología del Hospital Nacional Daniel Alcides Carrión por cuatro días de evolución y progresión reciente. Desarrolla lesiones sobreelevadas muy pruriginosas que aparecen y desaparecen en diferentes áreas en menos de 24 horas. En la inspección se observan elevaciones edematosas transitorias, de aspecto rojizas y de contorno nítido; se observan en varias regiones corporales. Presión arterial 118/74 mmHg, frecuencia cardiaca 82 lpm y saturación de oxígeno 98%. No presenta disnea, estridor ni hipotensión; las lesiones individuales desaparecen en pocas horas.","respuesta":"Urticaria","explicacion":"Habones eritematosos o pálidos, edematosos y pruriginosos. Clínico.","fija":"Si la lesión migra y desaparece en menos de 24 horas, piense en urticaria.","href":"banco.html?caso=13"},"14":{"id":14,"tipo":"banco","titulo":"Urticaria","tema":"Urticaria","frente":"Paciente varón de 53 años acude al Servicio de Dermatología del Hospital Nacional Daniel Alcides Carrión por siete días de evolución. Tras ingerir un alimento, paciente presenta múltiples ronchas edematosas pruriginosas migratorias. En la inspección se observan elevaciones edematosas transitorias, de aspecto rojizas y de contorno nítido; se observan en varias regiones corporales. Los signos vitales son estables y no hay compromiso de la vía aérea. Los elevaciones edematosas transitorias son migratorios y cada uno dura menos de 24 horas.","respuesta":"Urticaria","explicacion":"Habones eritematosos o pálidos, edematosos y pruriginosos. Clínico.","fija":"Si la lesión migra y desaparece en menos de 24 horas, piense en urticaria.","href":"banco.html?caso=14"},"15":{"id":15,"tipo":"banco","titulo":"Impétigo","tema":"Impétigo","frente":"Paciente mujer de 5 años acude al Servicio de Dermatología del Instituto Nacional de Salud del Niño - Breña por cuatro días de evolución y progresión reciente. Presenta pequeñas elevaciones con contenido líquido claro superficiales alrededor de nariz y boca que dejan costras amarillo-doradas color miel. En la inspección se observan pequeñas elevaciones con contenido purulento, de aspecto rojizas y de contorno nítido; se agrupan alrededor de orificios faciales. Se encuentra afebril, activo para la edad y hemodinámicamente estable, sin signos de compromiso sistémico.","respuesta":"Impétigo","explicacion":"Vesículas o pústulas que evolucionan a erosiones con costras melicéricas. Clínico; cultivo si enfermedad recurrente o resistente.","fija":"Costra color miel = impétigo.","href":"banco.html?caso=15"},"16":{"id":16,"tipo":"banco","titulo":"Impétigo","tema":"Impétigo","frente":"Paciente mujer de 10 años acude al Servicio de Dermatología del Instituto Nacional de Salud del Niño - Breña por siete días de evolución. Presenta lesiones contagiosas periorales con áreas superficiales de pérdida de epidermis y costras melicéricas. En la inspección se observan pequeñas elevaciones con contenido purulento, de aspecto rojizas y de contorno nítido; se agrupan alrededor de orificios faciales. Se encuentra afebril, activo para la edad y hemodinámicamente estable, sin signos de compromiso sistémico.","respuesta":"Impétigo","explicacion":"Vesículas o pústulas que evolucionan a erosiones con costras melicéricas. Clínico; cultivo si enfermedad recurrente o resistente.","fija":"Costra color miel = impétigo.","href":"banco.html?caso=16"},"17":{"id":17,"tipo":"banco","titulo":"Erisipela","tema":"Erisipela","frente":"Paciente mujer de 41 años acude al Servicio de Dermatología del Hospital María Auxiliadora por cuatro días de evolución y progresión reciente. Con fiebre presenta área cutánea sobreelevada de superficie amplia roja, caliente, dolorosa y claramente delimitada en pierna. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de contorno nítido; se limitan a una región anatómica. Al ingreso presenta temperatura de 38,4 °C, frecuencia cardiaca de 102 lpm y presión arterial de 118/72 mmHg. El hemograma muestra 14 800 leucocitos/µL con neutrofilia y proteína C reactiva elevada.","respuesta":"Erisipela","explicacion":"Placa eritematosa, caliente, dolorosa y bien delimitada. Principalmente clínico.","fija":"Erisipela tiene límites más nítidos y aspecto más superficial que la celulitis.","href":"banco.html?caso=17"},"18":{"id":18,"tipo":"banco","titulo":"Erisipela","tema":"Erisipela","frente":"Paciente mujer de 45 años acude al Servicio de Dermatología del Hospital Nacional Arzobispo Loayza por siete días de evolución. Presenta inicio súbito de fiebre y lesión rojiza brillante, elevada y con límites netos en miembro inferior. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de contorno nítido; se limitan a una región anatómica. Llega con fiebre de 38,1 °C y escalofríos, con presión arterial de 122/76 mmHg. Se documenta leucocitosis neutrofílica moderada y elevación de reactantes de fase aguda.","respuesta":"Erisipela","explicacion":"Placa eritematosa, caliente, dolorosa y bien delimitada. Principalmente clínico.","fija":"Erisipela tiene límites más nítidos y aspecto más superficial que la celulitis.","href":"banco.html?caso=18"},"19":{"id":19,"tipo":"banco","titulo":"Celulitis","tema":"Celulitis","frente":"Paciente mujer de 42 años acude al Servicio de Dermatología del Hospital Nacional Arzobispo Loayza por cuatro días de evolución y progresión reciente. Presenta aumento de volumen, calor, dolor y enrojecimiento difuso en pierna sin límites claramente definidos. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de transición gradual hacia la piel vecina; se limitan a una región anatómica. Signos vitales: temperatura 38,0 °C, frecuencia cardiaca 98 lpm y presión arterial 116/70 mmHg. Hemograma con 13 200 leucocitos/µL y neutrofilia; no se palpa fluctuación ni se aprecia crepitación.","respuesta":"Celulitis","explicacion":"Área eritematosa, caliente, dolorosa y mal delimitada. Clínico.","fija":"Celulitis = bordes difusos; erisipela = borde más nítido.","href":"banco.html?caso=19"},"20":{"id":20,"tipo":"banco","titulo":"Celulitis","tema":"Celulitis","frente":"Paciente varón de 27 años acude al Servicio de Dermatología del Hospital Nacional Daniel Alcides Carrión por siete días de evolución. Presenta infección de tejidos blandos con área rojiza caliente y dolorosa de bordes imprecisos. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de transición gradual hacia la piel vecina; se limitan a una región anatómica. Presenta febrícula y dolor progresivo. Leucocitos 12 600/µL con neutrofilia y proteína C reactiva elevada; pulsos distales conservados y sin signos clínicos de absceso.","respuesta":"Celulitis","explicacion":"Área eritematosa, caliente, dolorosa y mal delimitada. Clínico.","fija":"Celulitis = bordes difusos; erisipela = borde más nítido.","href":"banco.html?caso=20"},"21":{"id":21,"tipo":"banco","titulo":"Foliculitis bacteriana","tema":"Foliculitis bacteriana","frente":"Paciente mujer de 38 años acude al Servicio de Dermatología del Hospital Nacional Hipólito Unanue por tres semanas de evolución. Presenta pequeñas pequeñas elevaciones con contenido purulento centradas en folículos pilosos después de depilación. En la inspección se observan pequeñas elevaciones con contenido purulento, de aspecto rojizas y de contorno nítido; se limitan a una región anatómica.","respuesta":"Foliculitis bacteriana","explicacion":"Pústulas pequeñas centradas en folículos. Clínico; cultivo en recurrencias.","fija":"La pústula está centrada exactamente sobre un folículo.","href":"banco.html?caso=21"},"22":{"id":22,"tipo":"banco","titulo":"Foliculitis bacteriana","tema":"Foliculitis bacteriana","frente":"Paciente mujer de 55 años acude al Servicio de Dermatología del Hospital María Auxiliadora por dos meses de evolución. Desarrolla múltiples pequeñas elevaciones con contenido purulento superficiales perifoliculares en tronco después de sudoración intensa. En la inspección se observan pequeñas elevaciones con contenido purulento, de aspecto rojizas y de contorno nítido; se limitan a una región anatómica.","respuesta":"Foliculitis bacteriana","explicacion":"Pústulas pequeñas centradas en folículos. Clínico; cultivo en recurrencias.","fija":"La pústula está centrada exactamente sobre un folículo.","href":"banco.html?caso=22"},"23":{"id":23,"tipo":"banco","titulo":"Herpes simple","tema":"Herpes simple","frente":"Paciente mujer de 47 años acude al Servicio de Dermatología del Hospital María Auxiliadora por cuatro días de evolución y progresión reciente. Presenta ardor seguido de pequeñas pequeñas elevaciones con contenido líquido claro agrupadas dolorosas en borde del labio. En la inspección se observan pequeñas elevaciones con contenido líquido claro, de aspecto rojizas y de contorno nítido; se limitan a una región anatómica.","respuesta":"Herpes simple","explicacion":"Vesículas agrupadas sobre base eritematosa que pueden evolucionar a erosiones. Generalmente clínico; PCR en situaciones seleccionadas.","fija":"Vesículas agrupadas recurrentes en el mismo sitio.","href":"banco.html?caso=23"},"24":{"id":24,"tipo":"banco","titulo":"Herpes simple","tema":"Herpes simple","frente":"Paciente mujer de 19 años acude al Servicio de Dermatología del Hospital Nacional Daniel Alcides Carrión por siete días de evolución. Refiere episodios recurrentes de pequeñas elevaciones con contenido líquido claro agrupadas sobre base rojiza en la misma región. En la inspección se observan pequeñas elevaciones con contenido líquido claro, de aspecto rojizas y de contorno nítido; se limitan a una región anatómica.","respuesta":"Herpes simple","explicacion":"Vesículas agrupadas sobre base eritematosa que pueden evolucionar a erosiones. Generalmente clínico; PCR en situaciones seleccionadas.","fija":"Vesículas agrupadas recurrentes en el mismo sitio.","href":"banco.html?caso=24"},"25":{"id":25,"tipo":"banco","titulo":"Herpes zóster","tema":"Herpes zóster","frente":"Paciente varón de 77 años acude al Servicio de Dermatología del Hospital Nacional Cayetano Heredia por cuatro días de evolución y progresión reciente. Presenta dolor intenso en hemitórax seguido de pequeñas elevaciones con contenido líquido claro agrupadas en una banda unilateral. En la inspección se observan pequeñas elevaciones con contenido líquido claro, de aspecto rojizas y de contorno nítido; siguen una banda unilateral correspondiente a un territorio sensitivo.","respuesta":"Herpes zóster","explicacion":"Vesículas agrupadas sobre base eritematosa siguiendo un dermatoma. Clínico; PCR en casos atípicos.","fija":"Dolor + vesículas + distribución dermatomal unilateral.","href":"banco.html?caso=25"},"26":{"id":26,"tipo":"banco","titulo":"Herpes zóster","tema":"Herpes zóster","frente":"Paciente varón de 70 años acude al Servicio de Dermatología del Hospital Nacional Hipólito Unanue por siete días de evolución. Desarrolla ardor y parestesias, seguidas por erupción vesicular que respeta un dermatoma. En la inspección se observan pequeñas elevaciones con contenido líquido claro, de aspecto rojizas y de contorno nítido; siguen una banda unilateral correspondiente a un territorio sensitivo.","respuesta":"Herpes zóster","explicacion":"Vesículas agrupadas sobre base eritematosa siguiendo un dermatoma. Clínico; PCR en casos atípicos.","fija":"Dolor + vesículas + distribución dermatomal unilateral.","href":"banco.html?caso=26"},"27":{"id":27,"tipo":"banco","titulo":"Molusco contagioso","tema":"Molusco contagioso","frente":"Paciente mujer de 8 años acude al Servicio de Dermatología del Hospital Nacional Dos de Mayo por tres semanas de evolución. Presenta múltiples pequeñas elevaciones sólidas perladas pequeñas con depresión central. En la inspección se observan pequeñas elevaciones sólidas, de aspecto del mismo tono que la piel circundante y de contorno nítido; se limitan a una región anatómica. Se encuentra afebril, activo para la edad y hemodinámicamente estable, sin signos de compromiso sistémico.","respuesta":"Molusco contagioso","explicacion":"Pápulas perladas, cupuliformes y umbilicadas. Clínico.","fija":"Pápula perlada con umbilicación central.","href":"banco.html?caso=27"},"28":{"id":28,"tipo":"banco","titulo":"Molusco contagioso","tema":"Molusco contagioso","frente":"Paciente mujer de 7 años acude al Servicio de Dermatología del Instituto Nacional de Salud del Niño - Breña por dos meses de evolución. Presenta lesiones hemisféricas color piel, brillantes y umbilicadas. En la inspección se observan pequeñas elevaciones sólidas, de aspecto del mismo tono que la piel circundante y de contorno nítido; se limitan a una región anatómica. Se encuentra afebril, activo para la edad y hemodinámicamente estable, sin signos de compromiso sistémico.","respuesta":"Molusco contagioso","explicacion":"Pápulas perladas, cupuliformes y umbilicadas. Clínico.","fija":"Pápula perlada con umbilicación central.","href":"banco.html?caso=28"},"29":{"id":29,"tipo":"banco","titulo":"Verruga vulgar","tema":"Verruga vulgar","frente":"Paciente varón de 45 años acude al Servicio de Dermatología del Hospital María Auxiliadora por tres semanas de evolución. Presenta pequeña elevación sólida áspera hiperqueratósica en dedo de evolución lenta. En la inspección se observan pequeñas elevaciones sólidas, de aspecto del mismo tono que la piel circundante y de contorno nítido; se limitan a una región anatómica.","respuesta":"Verruga vulgar","explicacion":"Pápula hiperqueratósica de superficie rugosa. Clínico.","fija":"Superficie rugosa y puntos negros trombosados pueden sugerir verruga.","href":"banco.html?caso=29"},"30":{"id":30,"tipo":"banco","titulo":"Verruga vulgar","tema":"Verruga vulgar","frente":"Paciente varón de 34 años acude al Servicio de Dermatología del Hospital Nacional Dos de Mayo por dos meses de evolución. Presenta varias lesiones verrugosas rugosas en dorso de las manos. En la inspección se observan pequeñas elevaciones sólidas, de aspecto del mismo tono que la piel circundante y de contorno nítido; se limitan a una región anatómica.","respuesta":"Verruga vulgar","explicacion":"Pápula hiperqueratósica de superficie rugosa. Clínico.","fija":"Superficie rugosa y puntos negros trombosados pueden sugerir verruga.","href":"banco.html?caso=30"},"31":{"id":31,"tipo":"banco","titulo":"Tiña corporis","tema":"Tiña corporis","frente":"Paciente mujer de 43 años acude al Servicio de Dermatología del Hospital Nacional Dos de Mayo por tres semanas de evolución. Presenta área cutánea sobreelevada de superficie amplia anular pruriginosa con borde activo descamativo y aclaramiento central. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y elevados; se limitan a una región anatómica.","respuesta":"Tiña corporis","explicacion":"Placa anular eritematodescamativa con borde periférico activo. Examen directo con KOH puede demostrar hifas.","fija":"Borde activo + aclaramiento central = dermatofitosis.","href":"banco.html?caso=31"},"32":{"id":32,"tipo":"banco","titulo":"Tiña corporis","tema":"Tiña corporis","frente":"Paciente varón de 31 años acude al Servicio de Dermatología del Hospital Nacional Cayetano Heredia por dos meses de evolución. Deportista desarrolla lesión circular que crece centrífugamente con descamación predominante en la periferia. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y elevados; se limitan a una región anatómica.","respuesta":"Tiña corporis","explicacion":"Placa anular eritematodescamativa con borde periférico activo. Examen directo con KOH puede demostrar hifas.","fija":"Borde activo + aclaramiento central = dermatofitosis.","href":"banco.html?caso=32"},"33":{"id":33,"tipo":"banco","titulo":"Tiña cruris","tema":"Tiña cruris","frente":"Paciente varón de 24 años acude al Servicio de Dermatología del Hospital Nacional Arzobispo Loayza por tres semanas de evolución. Presenta áreas cutáneas sobreelevadas de superficie amplia pruriginosas anulares en región inguinal con borde descamativo activo. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y elevados; se limitan a una región anatómica.","respuesta":"Tiña cruris","explicacion":"Placas eritematodescamativas con borde activo. KOH en escamas periféricas.","fija":"Tiña cruris suele respetar el escroto; candidiasis puede comprometerlo.","href":"banco.html?caso=33"},"34":{"id":34,"tipo":"banco","titulo":"Tiña cruris","tema":"Tiña cruris","frente":"Paciente varón de 18 años acude al Servicio de Dermatología del Hospital Nacional Daniel Alcides Carrión por dos meses de evolución. Presenta lesión rojiza que se extiende desde pliegues inguinales hacia cara interna del muslo. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y elevados; se limitan a una región anatómica.","respuesta":"Tiña cruris","explicacion":"Placas eritematodescamativas con borde activo. KOH en escamas periféricas.","fija":"Tiña cruris suele respetar el escroto; candidiasis puede comprometerlo.","href":"banco.html?caso=34"},"35":{"id":35,"tipo":"banco","titulo":"Tiña pedis","tema":"Tiña pedis","frente":"Paciente mujer de 20 años acude al Servicio de Dermatología del Hospital Nacional Arzobispo Loayza por tres semanas de evolución. Presenta prurito, descamación y maceración entre cuarto y quinto dedos del pie. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de transición gradual hacia la piel vecina; predominan entre los dedos.","respuesta":"Tiña pedis","explicacion":"Descamación, maceración, fisuras o placas hiperqueratósicas. Examen directo con KOH.","fija":"Maceración interdigital crónica en el pie = tiña pedis hasta demostrar lo contrario.","href":"banco.html?caso=35"},"36":{"id":36,"tipo":"banco","titulo":"Tiña pedis","tema":"Tiña pedis","frente":"Paciente mujer de 33 años acude al Servicio de Dermatología del Hospital Nacional Arzobispo Loayza por dos meses de evolución. Deportista presenta fisuras y descamación interdigital recurrente en ambos pies. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de transición gradual hacia la piel vecina; predominan entre los dedos.","respuesta":"Tiña pedis","explicacion":"Descamación, maceración, fisuras o placas hiperqueratósicas. Examen directo con KOH.","fija":"Maceración interdigital crónica en el pie = tiña pedis hasta demostrar lo contrario.","href":"banco.html?caso=36"},"37":{"id":37,"tipo":"banco","titulo":"Tiña capitis","tema":"Tiña capitis","frente":"Paciente varón de 12 años acude al Servicio de Dermatología del Instituto Nacional de Salud del Niño San Borja por tres semanas de evolución. Presenta áreas de alopecia con descamación y cabellos quebrados. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de contorno nítido; se limitan a una región anatómica. Se encuentra afebril, activo para la edad y hemodinámicamente estable, sin signos de compromiso sistémico.","respuesta":"Tiña capitis","explicacion":"Placas descamativas alopécicas con cabellos rotos. KOH, cultivo y otras pruebas micológicas según disponibilidad.","fija":"Tiña capitis no se trata adecuadamente solo con crema: necesita terapia sistémica.","href":"banco.html?caso=37"},"38":{"id":38,"tipo":"banco","titulo":"Tiña capitis","tema":"Tiña capitis","frente":"Paciente varón de 7 años acude al Servicio de Dermatología del Hospital Nacional Dos de Mayo por dos meses de evolución. Desarrolla áreas cutáneas sobreelevadas de superficie amplia descamativas del cuero cabelludo con pérdida focal del cabello. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de contorno nítido; se limitan a una región anatómica. Se encuentra afebril, activo para la edad y hemodinámicamente estable, sin signos de compromiso sistémico.","respuesta":"Tiña capitis","explicacion":"Placas descamativas alopécicas con cabellos rotos. KOH, cultivo y otras pruebas micológicas según disponibilidad.","fija":"Tiña capitis no se trata adecuadamente solo con crema: necesita terapia sistémica.","href":"banco.html?caso=38"},"39":{"id":39,"tipo":"banco","titulo":"Pitiriasis versicolor","tema":"Pitiriasis versicolor","frente":"Paciente varón de 32 años acude al Servicio de Dermatología del Hospital María Auxiliadora por tres semanas de evolución. Presenta múltiples cambios planos de coloración más claras que la piel circundante finamente descamativas en tronco. En la inspección se observan cambios planos de coloración, de aspecto más claras que la piel circundante y de contorno nítido; se observan en varias regiones corporales.","respuesta":"Pitiriasis versicolor","explicacion":"Máculas hipo o hiperpigmentadas con fina descamación. KOH puede mostrar patrón de hifas cortas y levaduras.","fija":"Hipopigmentación con descamación fina en tronco.","href":"banco.html?caso=39"},"40":{"id":40,"tipo":"banco","titulo":"Pitiriasis versicolor","tema":"Pitiriasis versicolor","frente":"Paciente mujer de 43 años acude al Servicio de Dermatología del Hospital María Auxiliadora por dos meses de evolución. Presenta manchas de diferente tonalidad en espalda y tórax que se hacen más evidentes tras exposición solar. En la inspección se observan cambios planos de coloración, de aspecto más claras que la piel circundante y de contorno nítido; se observan en varias regiones corporales.","respuesta":"Pitiriasis versicolor","explicacion":"Máculas hipo o hiperpigmentadas con fina descamación. KOH puede mostrar patrón de hifas cortas y levaduras.","fija":"Hipopigmentación con descamación fina en tronco.","href":"banco.html?caso=40"},"41":{"id":41,"tipo":"banco","titulo":"Candidiasis cutánea","tema":"Candidiasis cutánea","frente":"Paciente mujer de 28 años acude al Servicio de Dermatología del Hospital Nacional Daniel Alcides Carrión por tres semanas de evolución. Obeso presenta área cutánea sobreelevada de superficie amplia rojiza húmeda en pliegue submamario con pequeñas elevaciones con contenido purulento satélite. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de contorno nítido; se limitan a una región anatómica. Glucemia capilar de 196 mg/dL y antecedente de diabetes mellitus con controles irregulares. No presenta fiebre ni compromiso sistémico.","respuesta":"Candidiasis cutánea","explicacion":"Placa eritematosa macerada con pápulas o pústulas satélite. Clínico y examen directo en casos dudosos.","fija":"Pústulas satélite alrededor de un intertrigo sugieren Candida.","href":"banco.html?caso=41"},"42":{"id":42,"tipo":"banco","titulo":"Candidiasis cutánea","tema":"Candidiasis cutánea","frente":"Paciente varón de 60 años acude al Servicio de Dermatología del Hospital Nacional Dos de Mayo por dos meses de evolución. Diabético presenta intertrigo intensamente rojizo con lesiones satélite en pliegue inguinal. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de contorno nítido; se limitan a una región anatómica. Signos vitales estables. Glucosa en ayunas de 168 mg/dL y antecedente de humedad persistente en el pliegue afectado.","respuesta":"Candidiasis cutánea","explicacion":"Placa eritematosa macerada con pápulas o pústulas satélite. Clínico y examen directo en casos dudosos.","fija":"Pústulas satélite alrededor de un intertrigo sugieren Candida.","href":"banco.html?caso=42"},"43":{"id":43,"tipo":"banco","titulo":"Escabiosis","tema":"Escabiosis","frente":"Paciente mujer de 31 años acude al Servicio de Dermatología del Hospital Nacional Dos de Mayo por tres semanas de evolución. Presenta prurito intenso predominantemente nocturno con lesiones en espacios interdigitales y muñecas. En la inspección se observan pequeñas elevaciones sólidas, de aspecto rojizas y de contorno nítido; predominan entre los dedos.","respuesta":"Escabiosis","explicacion":"Pápulas pruriginosas, excoriaciones y surcos acarinos. Clínico; dermatoscopia o raspado puede demostrar el ácaro.","fija":"Prurito nocturno + convivientes afectados + espacios interdigitales.","href":"banco.html?caso=43"},"44":{"id":44,"tipo":"banco","titulo":"Escabiosis","tema":"Escabiosis","frente":"Paciente mujer de 44 años acude al Servicio de Dermatología del Hospital Nacional Arzobispo Loayza por dos meses de evolución. Varios miembros de una familia presentan prurito nocturno y pequeñas pequeñas elevaciones sólidas excoriadas en manos y cintura. En la inspección se observan pequeñas elevaciones sólidas, de aspecto rojizas y de contorno nítido; predominan entre los dedos.","respuesta":"Escabiosis","explicacion":"Pápulas pruriginosas, excoriaciones y surcos acarinos. Clínico; dermatoscopia o raspado puede demostrar el ácaro.","fija":"Prurito nocturno + convivientes afectados + espacios interdigitales.","href":"banco.html?caso=44"},"45":{"id":45,"tipo":"banco","titulo":"Larva migrans cutánea","tema":"Larva migrans cutánea","frente":"Paciente mujer de 31 años acude al Servicio de Dermatología del Hospital Nacional Arzobispo Loayza por tres semanas de evolución. Que caminó descalzo en playa presenta trayecto serpiginoso muy pruriginoso en el pie. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de contorno nítido; se limitan a una región anatómica.","respuesta":"Larva migrans cutánea","explicacion":"Trayecto eritematoso serpiginoso y migratorio. Clínico.","fija":"Trayecto serpiginoso que avanza después de contacto con arena o suelo.","href":"banco.html?caso=45"},"46":{"id":46,"tipo":"banco","titulo":"Larva migrans cutánea","tema":"Larva migrans cutánea","frente":"Paciente mujer de 51 años acude al Servicio de Dermatología del Hospital María Auxiliadora por dos meses de evolución. Viajero presenta lesión lineal migratoria de aspecto serpiginoso que avanza lentamente. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de contorno nítido; se limitan a una región anatómica.","respuesta":"Larva migrans cutánea","explicacion":"Trayecto eritematoso serpiginoso y migratorio. Clínico.","fija":"Trayecto serpiginoso que avanza después de contacto con arena o suelo.","href":"banco.html?caso=46"},"47":{"id":47,"tipo":"banco","titulo":"Pénfigo vulgar","tema":"Pénfigo vulgar","frente":"Paciente mujer de 46 años acude al Servicio de Dermatología del Hospital Nacional Daniel Alcides Carrión por tres semanas de evolución. Presenta áreas superficiales de pérdida de epidermis orales dolorosas seguidas por elevaciones de mayor tamaño con contenido líquido flácidas que se rompen fácilmente. En la inspección se observan elevaciones de mayor tamaño con contenido líquido, de aspecto rojizas y de transición gradual hacia la piel vecina; se observan en varias regiones corporales. Presenta múltiples áreas superficiales de pérdida de epidermis dolorosas en la mucosa oral y signo de Nikolsky clínicamente positivo en piel perilesional; los signos vitales son estables.","respuesta":"Pénfigo vulgar","explicacion":"Ampollas flácidas intraepidérmicas que se rompen y producen erosiones. Biopsia e inmunofluorescencia directa.","fija":"Ampolla flácida + mucosa oral = pénfigo vulgar.","href":"banco.html?caso=47"},"48":{"id":48,"tipo":"banco","titulo":"Pénfigo vulgar","tema":"Pénfigo vulgar","frente":"Paciente mujer de 70 años acude al Servicio de Dermatología del Hospital Nacional Arzobispo Loayza por dos meses de evolución. Presenta elevaciones de mayor tamaño con contenido líquido frágiles y áreas superficiales de pérdida de epidermis extensas con compromiso de mucosa oral. En la inspección se observan elevaciones de mayor tamaño con contenido líquido, de aspecto rojizas y de transición gradual hacia la piel vecina; se observan en varias regiones corporales. No hay fiebre ni datos de infección secundaria. Las elevaciones de mayor tamaño con contenido líquido son flácidas y se rompen con facilidad, dejando áreas superficiales de pérdida de epidermis húmedas.","respuesta":"Pénfigo vulgar","explicacion":"Ampollas flácidas intraepidérmicas que se rompen y producen erosiones. Biopsia e inmunofluorescencia directa.","fija":"Ampolla flácida + mucosa oral = pénfigo vulgar.","href":"banco.html?caso=48"},"49":{"id":49,"tipo":"banco","titulo":"Pénfigo foliáceo","tema":"Pénfigo foliáceo","frente":"Paciente mujer de 58 años acude al Servicio de Dermatología del Hospital Nacional Hipólito Unanue por tres semanas de evolución. Presenta áreas superficiales de pérdida de epidermis superficiales costrosas en cara, cuero cabelludo y tronco sin compromiso oral. En la inspección se observan áreas superficiales de pérdida de epidermis, de aspecto rojizas y de transición gradual hacia la piel vecina; predominan en cuero cabelludo, cejas, surcos nasolabiales u otras zonas ricas en sebo.","respuesta":"Pénfigo foliáceo","explicacion":"Ampollas muy superficiales que suelen verse clínicamente como erosiones y costras. Biopsia e inmunofluorescencia directa.","fija":"Pénfigo foliáceo: superficial y típicamente sin mucosa.","href":"banco.html?caso=49"},"50":{"id":50,"tipo":"banco","titulo":"Pénfigo foliáceo","tema":"Pénfigo foliáceo","frente":"Paciente varón de 45 años acude al Servicio de Dermatología del Hospital María Auxiliadora por dos meses de evolución. Desarrolla lesiones descamativas y erosivas superficiales en áreas seborreicas. En la inspección se observan áreas superficiales de pérdida de epidermis, de aspecto rojizas y de transición gradual hacia la piel vecina; predominan en cuero cabelludo, cejas, surcos nasolabiales u otras zonas ricas en sebo.","respuesta":"Pénfigo foliáceo","explicacion":"Ampollas muy superficiales que suelen verse clínicamente como erosiones y costras. Biopsia e inmunofluorescencia directa.","fija":"Pénfigo foliáceo: superficial y típicamente sin mucosa.","href":"banco.html?caso=50"},"51":{"id":51,"tipo":"banco","titulo":"Penfigoide ampolloso","tema":"Penfigoide ampolloso","frente":"Paciente varón de 85 años acude al Servicio de Dermatología del Hospital Nacional Dos de Mayo por tres semanas de evolución. Presenta elevaciones de mayor tamaño con contenido líquido tensas muy pruriginosas sobre piel rojiza. En la inspección se observan elevaciones de mayor tamaño con contenido líquido, de aspecto rojizas y de contorno nítido; se observan en varias regiones corporales. Se encuentra afebril y hemodinámicamente estable. Las elevaciones de mayor tamaño con contenido líquido son tensas, pruriginosas y la mucosa oral está respetada.","respuesta":"Penfigoide ampolloso","explicacion":"Ampollas tensas sobre piel normal o eritematosa. Biopsia e inmunofluorescencia directa.","fija":"Penfigoide = ampolla tensa; pénfigo = ampolla flácida.","href":"banco.html?caso=51"},"52":{"id":52,"tipo":"banco","titulo":"Penfigoide ampolloso","tema":"Penfigoide ampolloso","frente":"Paciente mujer de 84 años acude al Servicio de Dermatología del Hospital Nacional Cayetano Heredia por dos meses de evolución. De edad avanzada desarrolla lesiones ampollosas firmes que no se rompen fácilmente. En la inspección se observan elevaciones de mayor tamaño con contenido líquido, de aspecto rojizas y de contorno nítido; se observan en varias regiones corporales. Los signos vitales no muestran alteraciones. Refiere prurito intenso previo a la aparición de elevaciones de mayor tamaño con contenido líquido firmes que no se rompen con facilidad.","respuesta":"Penfigoide ampolloso","explicacion":"Ampollas tensas sobre piel normal o eritematosa. Biopsia e inmunofluorescencia directa.","fija":"Penfigoide = ampolla tensa; pénfigo = ampolla flácida.","href":"banco.html?caso=52"},"53":{"id":53,"tipo":"banco","titulo":"Dermatitis herpetiforme","tema":"Dermatitis herpetiforme","frente":"Paciente mujer de 32 años acude al Servicio de Dermatología del Hospital Nacional Dos de Mayo por tres semanas de evolución. Presenta pequeñas elevaciones con contenido líquido claro pequeñas extremadamente pruriginosas y excoriadas en codos y rodillas. En la inspección se observan pequeñas elevaciones con contenido líquido claro, de aspecto rojizas y de contorno nítido; predominan en superficies externas de las extremidades.","respuesta":"Dermatitis herpetiforme","explicacion":"Pápulas y vesículas agrupadas intensamente pruriginosas. Biopsia perilesional con inmunofluorescencia directa.","fija":"Prurito intenso en extensores + celiaquía.","href":"banco.html?caso=53"},"54":{"id":54,"tipo":"banco","titulo":"Dermatitis herpetiforme","tema":"Dermatitis herpetiforme","frente":"Paciente varón de 47 años acude al Servicio de Dermatología del Hospital María Auxiliadora por dos meses de evolución. Con síntomas intestinales presenta lesiones papulovesiculares simétricas sobre superficies extensoras. En la inspección se observan pequeñas elevaciones con contenido líquido claro, de aspecto rojizas y de contorno nítido; predominan en superficies externas de las extremidades.","respuesta":"Dermatitis herpetiforme","explicacion":"Pápulas y vesículas agrupadas intensamente pruriginosas. Biopsia perilesional con inmunofluorescencia directa.","fija":"Prurito intenso en extensores + celiaquía.","href":"banco.html?caso=54"},"55":{"id":55,"tipo":"banco","titulo":"Vitíligo","tema":"Vitíligo","frente":"Paciente mujer de 40 años acude al Servicio de Dermatología del Hospital María Auxiliadora por ocho meses de evolución con exacerbaciones periódicas. Presenta manchas completamente blancas de contorno nítido en dorso de manos y alrededor de boca. En la inspección se observan cambios planos de coloración, de aspecto blanco tiza sin pigmento visible y de contorno nítido; aparecen de forma semejante a ambos lados del cuerpo.","respuesta":"Vitíligo","explicacion":"Máculas o parches acrómicos bien delimitados. Clínico; lámpara de Wood puede facilitar la evaluación.","fija":"Vitíligo = acrómico, no simplemente hipopigmentado.","href":"banco.html?caso=55"},"56":{"id":56,"tipo":"banco","titulo":"Vitíligo","tema":"Vitíligo","frente":"Paciente mujer de 20 años acude al Servicio de Dermatología del Hospital María Auxiliadora por seis meses de evolución progresiva. Presenta despigmentación simétrica progresiva sin descamación ni síntomas. En la inspección se observan cambios planos de coloración, de aspecto blanco tiza sin pigmento visible y de contorno nítido; aparecen de forma semejante a ambos lados del cuerpo.","respuesta":"Vitíligo","explicacion":"Máculas o parches acrómicos bien delimitados. Clínico; lámpara de Wood puede facilitar la evaluación.","fija":"Vitíligo = acrómico, no simplemente hipopigmentado.","href":"banco.html?caso=56"},"57":{"id":57,"tipo":"banco","titulo":"Melasma","tema":"Melasma","frente":"Paciente mujer de 28 años acude al Servicio de Dermatología del Hospital Nacional Cayetano Heredia por ocho meses de evolución con exacerbaciones periódicas. Presenta cambios planos de coloración marrones simétricas en mejillas y frente que aumentan con exposición solar. En la inspección se observan cambios planos de coloración, de aspecto marrón más oscuro que la piel vecina y irregulares; aparecen de forma semejante a ambos lados del cuerpo.","respuesta":"Melasma","explicacion":"Máculas parduzcas irregulares y simétricas. Clínico.","fija":"Hiperpigmentación facial simétrica que empeora con sol.","href":"banco.html?caso=57"},"58":{"id":58,"tipo":"banco","titulo":"Melasma","tema":"Melasma","frente":"Paciente mujer de 36 años acude al Servicio de Dermatología del Hospital Nacional Edgardo Rebagliati Martins por seis meses de evolución progresiva. Desarrolla hiperpigmentación facial bilateral durante el embarazo. En la inspección se observan cambios planos de coloración, de aspecto marrón más oscuro que la piel vecina y irregulares; aparecen de forma semejante a ambos lados del cuerpo.","respuesta":"Melasma","explicacion":"Máculas parduzcas irregulares y simétricas. Clínico.","fija":"Hiperpigmentación facial simétrica que empeora con sol.","href":"banco.html?caso=58"},"59":{"id":59,"tipo":"banco","titulo":"Acné vulgar","tema":"Acné vulgar","frente":"Paciente varón de 22 años acude al Servicio de Dermatología del Hospital Nacional Arzobispo Loayza por ocho meses de evolución con exacerbaciones periódicas. Presenta comedones abiertos y cerrados junto con pequeñas elevaciones sólidas y pequeñas elevaciones con contenido purulento en cara. En la inspección se observan pequeñas elevaciones sólidas, de aspecto rojizas y de contorno nítido; predominan en cuero cabelludo, cejas, surcos nasolabiales u otras zonas ricas en sebo.","respuesta":"Acné vulgar","explicacion":"Comedones, pápulas, pústulas y eventualmente nódulos. Clínico.","fija":"La presencia de comedones orienta fuertemente a acné.","href":"banco.html?caso=59"},"60":{"id":60,"tipo":"banco","titulo":"Acné vulgar","tema":"Acné vulgar","frente":"Paciente varón de 15 años acude al Servicio de Dermatología del Hospital Nacional Dos de Mayo por seis meses de evolución progresiva. Joven presenta lesiones inflamatorias y comedones en cara, pecho y espalda. En la inspección se observan pequeñas elevaciones sólidas, de aspecto rojizas y de contorno nítido; predominan en cuero cabelludo, cejas, surcos nasolabiales u otras zonas ricas en sebo.","respuesta":"Acné vulgar","explicacion":"Comedones, pápulas, pústulas y eventualmente nódulos. Clínico.","fija":"La presencia de comedones orienta fuertemente a acné.","href":"banco.html?caso=60"},"61":{"id":61,"tipo":"banco","titulo":"Rosácea","tema":"Rosácea","frente":"Paciente mujer de 54 años acude al Servicio de Dermatología del Hospital Nacional Cayetano Heredia por ocho meses de evolución con exacerbaciones periódicas. Presenta enrojecimiento centrofacial persistente, telangiectasias y pequeñas elevaciones sólidas sin comedones. En la inspección se observan pequeñas elevaciones sólidas, de aspecto rojizas y de transición gradual hacia la piel vecina; aparecen de forma semejante a ambos lados del cuerpo.","respuesta":"Rosácea","explicacion":"Eritema persistente, telangiectasias, pápulas y pústulas. Clínico.","fija":"Rosácea tiene pápulas/pústulas, pero no comedones.","href":"banco.html?caso=61"},"62":{"id":62,"tipo":"banco","titulo":"Rosácea","tema":"Rosácea","frente":"Paciente mujer de 46 años acude al Servicio de Dermatología del Hospital Nacional Edgardo Rebagliati Martins por seis meses de evolución progresiva. Refiere flushing facial recurrente y posteriormente pequeñas elevaciones sólidas y pequeñas elevaciones con contenido purulento en mejillas y nariz. En la inspección se observan pequeñas elevaciones sólidas, de aspecto rojizas y de transición gradual hacia la piel vecina; aparecen de forma semejante a ambos lados del cuerpo.","respuesta":"Rosácea","explicacion":"Eritema persistente, telangiectasias, pápulas y pústulas. Clínico.","fija":"Rosácea tiene pápulas/pústulas, pero no comedones.","href":"banco.html?caso=62"},"63":{"id":63,"tipo":"banco","titulo":"Hidradenitis supurativa","tema":"Hidradenitis supurativa","frente":"Paciente mujer de 34 años acude al Servicio de Dermatología del Hospital Nacional Edgardo Rebagliati Martins por ocho meses de evolución con exacerbaciones periódicas. Presenta lesiones sólidas profundas y palpables dolorosos recurrentes y abscesos en axilas con cicatrices y trayectos fistulosos. En la inspección se observan lesiones sólidas profundas y palpables, de aspecto rojizas y de contorno nítido; se limitan a una región anatómica. Permanece afebril, con presión arterial de 124/78 mmHg. El hemograma no muestra leucocitosis marcada y la proteína C reactiva está discretamente elevada; refiere episodios similares desde hace tres años.","respuesta":"Hidradenitis supurativa","explicacion":"Nódulos profundos, abscesos, fístulas y cicatrices. Clínico.","fija":"Nódulos recurrentes + fístulas + cicatrices en pliegues.","href":"banco.html?caso=63"},"64":{"id":64,"tipo":"banco","titulo":"Hidradenitis supurativa","tema":"Hidradenitis supurativa","frente":"Paciente mujer de 67 años acude al Servicio de Dermatología del Hospital María Auxiliadora por seis meses de evolución progresiva. Presenta lesiones inflamatorias recurrentes en ingles y axilas que drenan material purulento. En la inspección se observan lesiones sólidas profundas y palpables, de aspecto rojizas y de contorno nítido; se limitan a una región anatómica. Los signos vitales son estables. Se observan cicatrices retraídas y trayectos de drenaje en pliegues, sin datos clínicos de sepsis.","respuesta":"Hidradenitis supurativa","explicacion":"Nódulos profundos, abscesos, fístulas y cicatrices. Clínico.","fija":"Nódulos recurrentes + fístulas + cicatrices en pliegues.","href":"banco.html?caso=64"},"65":{"id":65,"tipo":"banco","titulo":"Alopecia areata","tema":"Alopecia areata","frente":"Paciente mujer de 42 años acude al Servicio de Dermatología del Hospital Nacional Hipólito Unanue por ocho meses de evolución con exacerbaciones periódicas. Presenta pérdida súbita de cabello en una área cutánea sobreelevada de superficie amplia redonda completamente lisa. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto del mismo tono que la piel circundante y de contorno nítido; se limitan a una región anatómica.","respuesta":"Alopecia areata","explicacion":"Placa alopécica lisa y bien delimitada. Clínico y dermatoscópico.","fija":"Placa alopécica lisa sin escama.","href":"banco.html?caso=65"},"66":{"id":66,"tipo":"banco","titulo":"Alopecia areata","tema":"Alopecia areata","frente":"Paciente varón de 67 años acude al Servicio de Dermatología del Hospital Nacional Edgardo Rebagliati Martins por seis meses de evolución progresiva. Presenta área alopécica de contorno nítido sin descamación ni inflamación evidente. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto del mismo tono que la piel circundante y de contorno nítido; se limitan a una región anatómica.","respuesta":"Alopecia areata","explicacion":"Placa alopécica lisa y bien delimitada. Clínico y dermatoscópico.","fija":"Placa alopécica lisa sin escama.","href":"banco.html?caso=66"},"67":{"id":67,"tipo":"banco","titulo":"Eritema multiforme","tema":"Eritema multiforme","frente":"Paciente varón de 29 años acude al Servicio de Dermatología del Hospital Nacional Cayetano Heredia por cuatro días de evolución y progresión reciente. Presenta lesiones concéntricas en diana sobre manos y extremidades después de episodio de herpes simple. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de contorno nítido; predominan en superficies externas de las extremidades.","respuesta":"Eritema multiforme","explicacion":"Lesión típica en diana con zonas concéntricas. Clínico.","fija":"La lesión en diana clásica es la clave.","href":"banco.html?caso=67"},"68":{"id":68,"tipo":"banco","titulo":"Eritema multiforme","tema":"Eritema multiforme","frente":"Paciente mujer de 24 años acude al Servicio de Dermatología del Hospital María Auxiliadora por siete días de evolución. Desarrolla múltiples lesiones target simétricas en superficies extensoras. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de contorno nítido; predominan en superficies externas de las extremidades.","respuesta":"Eritema multiforme","explicacion":"Lesión típica en diana con zonas concéntricas. Clínico.","fija":"La lesión en diana clásica es la clave.","href":"banco.html?caso=68"},"69":{"id":69,"tipo":"banco","titulo":"Eritema nodoso","tema":"Eritema nodoso","frente":"Paciente mujer de 33 años acude al Servicio de Dermatología del Hospital Nacional Edgardo Rebagliati Martins por cuatro días de evolución y progresión reciente. Presenta lesiones sólidas profundas y palpables dolorosos rojizos simétricos en cara anterior de ambas piernas. En la inspección se observan lesiones sólidas profundas y palpables, de aspecto rojizas y de transición gradual hacia la piel vecina; aparecen de forma semejante a ambos lados del cuerpo. Presenta temperatura de 37,7 °C y artralgias de tobillos. El hemograma no muestra leucocitosis importante, pero la VSG y la proteína C reactiva están elevadas.","respuesta":"Eritema nodoso","explicacion":"Nódulos subcutáneos eritematosos y dolorosos. Clínico; debe investigarse la causa subyacente.","fija":"Nódulos dolorosos pretibiales bilaterales.","href":"banco.html?caso=69"},"70":{"id":70,"tipo":"banco","titulo":"Eritema nodoso","tema":"Eritema nodoso","frente":"Paciente mujer de 31 años acude al Servicio de Dermatología del Hospital Nacional Cayetano Heredia por siete días de evolución. Presenta lesiones subcutáneas dolorosas en tibias asociadas con malestar general. En la inspección se observan lesiones sólidas profundas y palpables, de aspecto rojizas y de transición gradual hacia la piel vecina; aparecen de forma semejante a ambos lados del cuerpo. Refiere malestar general y dolor articular. Los signos vitales son estables y los reactantes de fase aguda están elevados.","respuesta":"Eritema nodoso","explicacion":"Nódulos subcutáneos eritematosos y dolorosos. Clínico; debe investigarse la causa subyacente.","fija":"Nódulos dolorosos pretibiales bilaterales.","href":"banco.html?caso=70"},"71":{"id":71,"tipo":"banco","titulo":"Lupus cutáneo discoide","tema":"Lupus cutáneo discoide","frente":"Paciente mujer de 48 años acude al Servicio de Dermatología del Hospital Nacional Edgardo Rebagliati Martins por ocho meses de evolución con exacerbaciones periódicas. Presenta áreas cutáneas sobreelevadas de superficie amplia rojizas descamativas en cara con atrofia y alteración pigmentaria residual. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de contorno nítido; predominan en zonas expuestas al sol.","respuesta":"Lupus cutáneo discoide","explicacion":"Placas eritematosas escamosas que pueden evolucionar a atrofia y cicatriz. Clínico, serológico según contexto y biopsia cutánea.","fija":"Lupus discoide puede dejar cicatriz y alopecia cicatricial.","href":"banco.html?caso=71"},"72":{"id":72,"tipo":"banco","titulo":"Lupus cutáneo discoide","tema":"Lupus cutáneo discoide","frente":"Paciente mujer de 33 años acude al Servicio de Dermatología del Hospital Nacional Cayetano Heredia por seis meses de evolución progresiva. Presenta lesiones crónicas discoides en cuero cabelludo y cara que dejan cicatriz. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de contorno nítido; predominan en zonas expuestas al sol.","respuesta":"Lupus cutáneo discoide","explicacion":"Placas eritematosas escamosas que pueden evolucionar a atrofia y cicatriz. Clínico, serológico según contexto y biopsia cutánea.","fija":"Lupus discoide puede dejar cicatriz y alopecia cicatricial.","href":"banco.html?caso=72"},"73":{"id":73,"tipo":"banco","titulo":"Dermatomiositis","tema":"Dermatomiositis","frente":"Paciente mujer de 38 años acude al Servicio de Dermatología del Hospital Nacional Arzobispo Loayza por tres semanas de evolución. Con debilidad muscular proximal presenta pequeñas elevaciones sólidas rojizo-purpúreas sobre nudillos. En la inspección se observan pequeñas elevaciones sólidas, de aspecto rojizo-purpúreas y de contorno nítido; predominan en superficies externas de las extremidades. Refiere además dificultad para levantarse de una silla y elevar los brazos. CK 1 480 U/L, AST y ALT discretamente elevadas y VSG aumentada.","respuesta":"Dermatomiositis","explicacion":"Pápulas de Gottron y eritema heliotropo entre otras manifestaciones. Evaluación clínica, enzimas musculares, autoanticuerpos, estudios electrofisiológicos o biopsia según caso.","fija":"Pápulas de Gottron + debilidad proximal.","href":"banco.html?caso=73"},"74":{"id":74,"tipo":"banco","titulo":"Dermatomiositis","tema":"Dermatomiositis","frente":"Paciente mujer de 54 años acude al Servicio de Dermatología del Hospital Nacional Daniel Alcides Carrión por dos meses de evolución. Presenta enrojecimiento violáceo periocular y lesiones de Gottron en articulaciones de manos. En la inspección se observan pequeñas elevaciones sólidas, de aspecto rojizo-purpúreas y de contorno nítido; predominan en superficies externas de las extremidades. Al examen neuromuscular presenta debilidad proximal simétrica 4/5. CK 1 120 U/L y aldolasa elevada; los signos vitales son estables.","respuesta":"Dermatomiositis","explicacion":"Pápulas de Gottron y eritema heliotropo entre otras manifestaciones. Evaluación clínica, enzimas musculares, autoanticuerpos, estudios electrofisiológicos o biopsia según caso.","fija":"Pápulas de Gottron + debilidad proximal.","href":"banco.html?caso=74"},"75":{"id":75,"tipo":"banco","titulo":"Esclerodermia localizada","tema":"Esclerodermia localizada","frente":"Paciente mujer de 62 años acude al Servicio de Dermatología del Hospital Nacional Edgardo Rebagliati Martins por ocho meses de evolución con exacerbaciones periódicas. Presenta área cutánea sobreelevada de superficie amplia endurecida, brillante y progresivamente más oscura que la piel vecina en tronco. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto marrones y de contorno nítido; se limitan a una región anatómica.","respuesta":"Esclerodermia localizada","explicacion":"Placa indurada y esclerótica. Clínico y biopsia en casos seleccionados.","fija":"Placa dura e indurada con aspecto esclerótico.","href":"banco.html?caso=75"},"76":{"id":76,"tipo":"banco","titulo":"Esclerodermia localizada","tema":"Esclerodermia localizada","frente":"Paciente varón de 63 años acude al Servicio de Dermatología del Hospital Nacional Edgardo Rebagliati Martins por seis meses de evolución progresiva. Presenta lesión indurada de contorno nítido con centro esclerótico y halo violáceo. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto marrones y de contorno nítido; se limitan a una región anatómica.","respuesta":"Esclerodermia localizada","explicacion":"Placa indurada y esclerótica. Clínico y biopsia en casos seleccionados.","fija":"Placa dura e indurada con aspecto esclerótico.","href":"banco.html?caso=76"},"77":{"id":77,"tipo":"banco","titulo":"Queratosis seborreica","tema":"Queratosis seborreica","frente":"Paciente mujer de 50 años acude al Servicio de Dermatología del Hospital Nacional Daniel Alcides Carrión por ocho meses de evolución con exacerbaciones periódicas. Presenta lesión marrón verrugosa con apariencia de estar pegada sobre la piel. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto marrón más oscuro que la piel vecina y de contorno nítido; se limitan a una región anatómica.","respuesta":"Queratosis seborreica","explicacion":"Pápula o placa bien delimitada, verrugosa o cerosa con aspecto adherido. Clínico y dermatoscópico.","fija":"Aspecto de lesión pegada o 'stuck-on'.","href":"banco.html?caso=77"},"78":{"id":78,"tipo":"banco","titulo":"Queratosis seborreica","tema":"Queratosis seborreica","frente":"Paciente varón de 44 años acude al Servicio de Dermatología del Hospital Nacional Dos de Mayo por seis meses de evolución progresiva. Consulta por múltiples lesiones pigmentadas de superficie cerosa en tronco. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto marrón más oscuro que la piel vecina y de contorno nítido; se limitan a una región anatómica.","respuesta":"Queratosis seborreica","explicacion":"Pápula o placa bien delimitada, verrugosa o cerosa con aspecto adherido. Clínico y dermatoscópico.","fija":"Aspecto de lesión pegada o 'stuck-on'.","href":"banco.html?caso=78"},"79":{"id":79,"tipo":"banco","titulo":"Queratosis actínica","tema":"Queratosis actínica","frente":"Paciente mujer de 59 años acude al Servicio de Dermatología del Hospital Nacional Daniel Alcides Carrión por ocho meses de evolución con exacerbaciones periódicas. Con exposición solar crónica presenta pequeña área cutánea sobreelevada de superficie amplia áspera en cuero cabelludo. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de transición gradual hacia la piel vecina; predominan en zonas expuestas al sol.","respuesta":"Queratosis actínica","explicacion":"Mácula, pápula o placa áspera y descamativa. Clínico y dermatoscópico; biopsia si hay sospecha de carcinoma invasivo.","fija":"Muchas veces se siente áspera antes de verse claramente.","href":"banco.html?caso=79"},"80":{"id":80,"tipo":"banco","titulo":"Queratosis actínica","tema":"Queratosis actínica","frente":"Paciente mujer de 81 años acude al Servicio de Dermatología del Hospital Nacional Cayetano Heredia por seis meses de evolución progresiva. Presenta múltiples lesiones rojizas rugosas al tacto en cara y dorso de manos. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de transición gradual hacia la piel vecina; predominan en zonas expuestas al sol.","respuesta":"Queratosis actínica","explicacion":"Mácula, pápula o placa áspera y descamativa. Clínico y dermatoscópico; biopsia si hay sospecha de carcinoma invasivo.","fija":"Muchas veces se siente áspera antes de verse claramente.","href":"banco.html?caso=80"},"81":{"id":81,"tipo":"banco","titulo":"Carcinoma basocelular","tema":"Carcinoma basocelular","frente":"Paciente mujer de 76 años acude al Servicio de Dermatología del Hospital Nacional Hipólito Unanue por ocho meses de evolución con exacerbaciones periódicas. Presenta pequeña elevación sólida perlada facial con telangiectasias y ulceración central. En la inspección se observan lesiones sólidas profundas y palpables, de aspecto del mismo tono que la piel circundante y elevados; predominan en zonas expuestas al sol. Los signos vitales son estables. La lesión sangra con traumatismos mínimos y presenta un borde perlado con telangiectasias superficiales.","respuesta":"Carcinoma basocelular","explicacion":"Pápula o nódulo perlado con telangiectasias y posible ulceración. Dermatoscopia y confirmación histológica.","fija":"Pápula perlada + telangiectasias = carcinoma basocelular.","href":"banco.html?caso=81"},"82":{"id":82,"tipo":"banco","titulo":"Carcinoma basocelular","tema":"Carcinoma basocelular","frente":"Paciente varón de 73 años acude al Servicio de Dermatología del Hospital María Auxiliadora por seis meses de evolución progresiva. Con exposición solar crónica presenta lesión nodular brillante de crecimiento lento en nariz. En la inspección se observan lesiones sólidas profundas y palpables, de aspecto del mismo tono que la piel circundante y elevados; predominan en zonas expuestas al sol. No se palpan adenopatías regionales. Se observa un pápulo-lesión sólida profunda y palpable perlado de crecimiento lento con ulceración central.","respuesta":"Carcinoma basocelular","explicacion":"Pápula o nódulo perlado con telangiectasias y posible ulceración. Dermatoscopia y confirmación histológica.","fija":"Pápula perlada + telangiectasias = carcinoma basocelular.","href":"banco.html?caso=82"},"83":{"id":83,"tipo":"banco","titulo":"Carcinoma epidermoide cutáneo","tema":"Carcinoma epidermoide cutáneo","frente":"Paciente varón de 77 años acude al Servicio de Dermatología del Hospital Nacional Daniel Alcides Carrión por ocho meses de evolución con exacerbaciones periódicas. Presenta lesión sólida profunda y palpable hiperqueratósico ulcerado de crecimiento progresivo en dorso de mano. En la inspección se observan lesiones sólidas profundas y palpables, de aspecto rojizas y irregulares; predominan en zonas expuestas al sol. Está afebril y hemodinámicamente estable. No se palpan adenopatías regionales y la lesión ha crecido de forma progresiva durante los últimos meses.","respuesta":"Carcinoma epidermoide cutáneo","explicacion":"Pápula, placa o nódulo hiperqueratósico, costroso o ulcerado. Biopsia cutánea.","fija":"Lesión queratósica infiltrada o ulcerada sobre piel fotodañada.","href":"banco.html?caso=83"},"84":{"id":84,"tipo":"banco","titulo":"Carcinoma epidermoide cutáneo","tema":"Carcinoma epidermoide cutáneo","frente":"Paciente varón de 78 años acude al Servicio de Dermatología del Hospital Nacional Hipólito Unanue por seis meses de evolución progresiva. Con daño solar presenta lesión costrosa e infiltrada en región facial. En la inspección se observan lesiones sólidas profundas y palpables, de aspecto rojizas y irregulares; predominan en zonas expuestas al sol. El hemograma no muestra alteraciones relevantes. Se observa una lesión indurada, hiperqueratósica y parcialmente ulcerada en una zona fotoexpuesta.","respuesta":"Carcinoma epidermoide cutáneo","explicacion":"Pápula, placa o nódulo hiperqueratósico, costroso o ulcerado. Biopsia cutánea.","fija":"Lesión queratósica infiltrada o ulcerada sobre piel fotodañada.","href":"banco.html?caso=84"},"85":{"id":85,"tipo":"banco","titulo":"Melanoma","tema":"Melanoma","frente":"Paciente mujer de 48 años acude al Servicio de Dermatología del Hospital Nacional Arzobispo Loayza por ocho meses de evolución con exacerbaciones periódicas. Presenta lesión pigmentada que ha aumentado de tamaño, con asimetría, bordes irregulares y varios colores. En la inspección se observan cambios planos de coloración, de aspecto marrón más oscuro que la piel vecina y irregulares; predominan de manera desigual entre ambos lados. Los signos vitales y el hemograma no presentan alteraciones relevantes. En la dermatoscopia se aprecia asimetría estructural, red pigmentaria atípica y múltiples tonalidades.","respuesta":"Melanoma","explicacion":"Mácula, placa o nódulo pigmentado con asimetría y heterogeneidad. Dermatoscopia y biopsia excisional cuando es posible.","fija":"ABCDE: Asimetría, Bordes, Color, Diámetro y Evolución.","href":"banco.html?caso=85"},"86":{"id":86,"tipo":"banco","titulo":"Melanoma","tema":"Melanoma","frente":"Paciente mujer de 49 años acude al Servicio de Dermatología del Hospital María Auxiliadora por seis meses de evolución progresiva. Consulta por nevo que ha cambiado recientemente de forma y tonalidad. En la inspección se observan cambios planos de coloración, de aspecto marrón más oscuro que la piel vecina y irregulares; predominan de manera desigual entre ambos lados. Se encuentra hemodinámicamente estable. La lesión ha aumentado de tamaño en los últimos meses y presenta asimetría, bordes irregulares y variación de color.","respuesta":"Melanoma","explicacion":"Mácula, placa o nódulo pigmentado con asimetría y heterogeneidad. Dermatoscopia y biopsia excisional cuando es posible.","fija":"ABCDE: Asimetría, Bordes, Color, Diámetro y Evolución.","href":"banco.html?caso=86"},"87":{"id":87,"tipo":"banco","titulo":"Nevo melanocítico","tema":"Nevo melanocítico","frente":"Paciente varón de 56 años acude al Servicio de Dermatología del Hospital Nacional Daniel Alcides Carrión por ocho meses de evolución con exacerbaciones periódicas. Presenta lesión pigmentada estable durante años, simétrica y de bordes regulares. En la inspección se observan pequeñas elevaciones sólidas, de aspecto marrón más oscuro que la piel vecina y regulares; se limitan a una región anatómica.","respuesta":"Nevo melanocítico","explicacion":"Mácula o pápula pigmentada, simétrica y homogénea. Clínico y dermatoscópico.","fija":"Simetría y homogeneidad favorecen benignidad, pero siempre se evalúa evolución.","href":"banco.html?caso=87"},"88":{"id":88,"tipo":"banco","titulo":"Nevo melanocítico","tema":"Nevo melanocítico","frente":"Paciente mujer de 56 años acude al Servicio de Dermatología del Hospital María Auxiliadora por seis meses de evolución progresiva. Presenta pequeño nevo homogéneo, sin cambios recientes ni síntomas. En la inspección se observan pequeñas elevaciones sólidas, de aspecto marrón más oscuro que la piel vecina y regulares; se limitan a una región anatómica.","respuesta":"Nevo melanocítico","explicacion":"Mácula o pápula pigmentada, simétrica y homogénea. Clínico y dermatoscópico.","fija":"Simetría y homogeneidad favorecen benignidad, pero siempre se evalúa evolución.","href":"banco.html?caso=88"},"89":{"id":89,"tipo":"banco","titulo":"Dermatofibroma","tema":"Dermatofibroma","frente":"Paciente varón de 60 años acude al Servicio de Dermatología del Hospital Nacional Cayetano Heredia por ocho meses de evolución con exacerbaciones periódicas. Presenta pequeño lesión sólida profunda y palpable firme parduzco en pierna que se deprime al comprimirlo lateralmente. En la inspección se observan lesiones sólidas profundas y palpables, de aspecto marrón más oscuro que la piel vecina y de contorno nítido; se limitan a una región anatómica.","respuesta":"Dermatofibroma","explicacion":"Pápula o nódulo firme parduzco. Clínico y dermatoscópico.","fija":"Compresión lateral produce signo del hoyuelo.","href":"banco.html?caso=89"},"90":{"id":90,"tipo":"banco","titulo":"Dermatofibroma","tema":"Dermatofibroma","frente":"Paciente varón de 30 años acude al Servicio de Dermatología del Hospital Nacional Cayetano Heredia por seis meses de evolución progresiva. Presenta lesión estable y firme en miembro inferior con signo del hoyuelo. En la inspección se observan lesiones sólidas profundas y palpables, de aspecto marrón más oscuro que la piel vecina y de contorno nítido; se limitan a una región anatómica.","respuesta":"Dermatofibroma","explicacion":"Pápula o nódulo firme parduzco. Clínico y dermatoscópico.","fija":"Compresión lateral produce signo del hoyuelo.","href":"banco.html?caso=90"},"91":{"id":91,"tipo":"banco","titulo":"Acrocordón","tema":"Acrocordón","frente":"Paciente varón de 45 años acude al Servicio de Dermatología del Hospital Nacional Cayetano Heredia por ocho meses de evolución con exacerbaciones periódicas. Presenta múltiples pequeñas lesiones pediculadas blandas en cuello y axilas. En la inspección se observan pequeñas elevaciones sólidas, de aspecto del mismo tono que la piel circundante y de contorno nítido; se limitan a una región anatómica.","respuesta":"Acrocordón","explicacion":"Pápula blanda, pediculada y color piel. Clínico.","fija":"Lesión blanda y pediculada en pliegues.","href":"banco.html?caso=91"},"92":{"id":92,"tipo":"banco","titulo":"Acrocordón","tema":"Acrocordón","frente":"Paciente mujer de 32 años acude al Servicio de Dermatología del Hospital Nacional Daniel Alcides Carrión por seis meses de evolución progresiva. Con obesidad presenta pequeñas elevaciones sólidas blandas color piel en pliegues. En la inspección se observan pequeñas elevaciones sólidas, de aspecto del mismo tono que la piel circundante y de contorno nítido; se limitan a una región anatómica.","respuesta":"Acrocordón","explicacion":"Pápula blanda, pediculada y color piel. Clínico.","fija":"Lesión blanda y pediculada en pliegues.","href":"banco.html?caso=92"},"93":{"id":93,"tipo":"banco","titulo":"Hemangioma infantil","tema":"Hemangioma infantil","frente":"Paciente varón de 10 meses acude al Servicio de Dermatología del Hospital Nacional Dos de Mayo por tres semanas de evolución. Presenta lesión vascular roja sobreelevada que creció durante los primeros meses de vida. En la inspección se observan lesiones sólidas profundas y palpables, de aspecto rojizas y de contorno nítido; se limitan a una región anatómica. Se encuentra afebril, activo para la edad y hemodinámicamente estable, sin signos de compromiso sistémico.","respuesta":"Hemangioma infantil","explicacion":"Pápula, placa o nódulo vascular rojo brillante. Generalmente clínico.","fija":"Hemangioma infantil prolifera después del nacimiento y posteriormente involuciona.","href":"banco.html?caso=93"},"94":{"id":94,"tipo":"banco","titulo":"Hemangioma infantil","tema":"Hemangioma infantil","frente":"Paciente varón de 7 meses acude al Servicio de Dermatología del Instituto Nacional de Salud del Niño - Breña por dos meses de evolución. Madre consulta por tumoración rojo brillante tipo fresa en la cara de su bebé. En la inspección se observan lesiones sólidas profundas y palpables, de aspecto rojizas y de contorno nítido; se limitan a una región anatómica. Se encuentra afebril, activo para la edad y hemodinámicamente estable, sin signos de compromiso sistémico.","respuesta":"Hemangioma infantil","explicacion":"Pápula, placa o nódulo vascular rojo brillante. Generalmente clínico.","fija":"Hemangioma infantil prolifera después del nacimiento y posteriormente involuciona.","href":"banco.html?caso=94"},"95":{"id":95,"tipo":"banco","titulo":"Nevus simplex","tema":"Nevus simplex","frente":"Paciente varón de 2 meses acude al Servicio de Dermatología del Instituto Nacional de Salud del Niño San Borja por tres semanas de evolución. Recién nacido presenta cambio plano de coloración rosada plana en nuca que se intensifica con el llanto. En la inspección se observan cambios planos de coloración, de aspecto rojizas y de transición gradual hacia la piel vecina; se limitan a una región anatómica. Se encuentra afebril, activo para la edad y hemodinámicamente estable, sin signos de compromiso sistémico.","respuesta":"Nevus simplex","explicacion":"Mácula rosada o eritematosa plana. Clínico.","fija":"También llamado beso de ángel o picotazo de cigüeña según localización.","href":"banco.html?caso=95"},"96":{"id":96,"tipo":"banco","titulo":"Nevus simplex","tema":"Nevus simplex","frente":"Paciente varón de 8 meses acude al Servicio de Dermatología del Instituto Nacional de Salud del Niño - Breña por dos meses de evolución. Presenta mancha rosada tenue en glabela desde el nacimiento. En la inspección se observan cambios planos de coloración, de aspecto rojizas y de transición gradual hacia la piel vecina; se limitan a una región anatómica. Se encuentra afebril, activo para la edad y hemodinámicamente estable, sin signos de compromiso sistémico.","respuesta":"Nevus simplex","explicacion":"Mácula rosada o eritematosa plana. Clínico.","fija":"También llamado beso de ángel o picotazo de cigüeña según localización.","href":"banco.html?caso=96"},"97":{"id":97,"tipo":"banco","titulo":"Malformación capilar tipo vino de Oporto","tema":"Malformación capilar tipo vino de Oporto","frente":"Paciente varón de 58 años acude al Servicio de Dermatología del Hospital Nacional Hipólito Unanue por tres semanas de evolución. Presenta desde el nacimiento una cambio plano de coloración rojo-vinosa unilateral en cara que persiste con la edad. En la inspección se observan cambios planos de coloración, de aspecto rojizo-purpúreas y de contorno nítido; se limitan a una región anatómica.","respuesta":"Malformación capilar tipo vino de Oporto","explicacion":"Mácula rojo-violácea plana y bien delimitada. Clínico.","fija":"Vino de Oporto persiste; nevus simplex suele aclararse.","href":"banco.html?caso=97"},"98":{"id":98,"tipo":"banco","titulo":"Malformación capilar tipo vino de Oporto","tema":"Malformación capilar tipo vino de Oporto","frente":"Paciente mujer de 47 años acude al Servicio de Dermatología del Hospital Nacional Arzobispo Loayza por dos meses de evolución. Presenta malformación vascular plana que progresivamente se oscurece con el crecimiento. En la inspección se observan cambios planos de coloración, de aspecto rojizo-purpúreas y de contorno nítido; se limitan a una región anatómica.","respuesta":"Malformación capilar tipo vino de Oporto","explicacion":"Mácula rojo-violácea plana y bien delimitada. Clínico.","fija":"Vino de Oporto persiste; nevus simplex suele aclararse.","href":"banco.html?caso=98"},"99":{"id":99,"tipo":"banco","titulo":"Púrpura","tema":"Púrpura","frente":"Paciente mujer de 41 años acude al Servicio de Dermatología del Hospital Nacional Edgardo Rebagliati Martins por tres semanas de evolución. Consulta por aparición progresiva, desde hace 4 días, de múltiples lesiones rojizo-purpúreas en ambas extremidades inferiores. Refiere que las lesiones no desaparecen al presionarlas y algunas son ligeramente palpables. Niega traumatismos recientes. Al examen se observan cambios planos de coloración y pequeñas pequeñas elevaciones sólidas purpúricas, simétricas, predominantes en piernas, sin blanqueamiento a la digitopresión. En la inspección se observan cambios planos de coloración, de aspecto rojizo-purpúreas y de contorno nítido; se observan en varias regiones corporales. Se encuentra hemodinámicamente estable. Hemograma: hemoglobina 12,8 g/dL, leucocitos 7 400/µL y plaquetas 238 000/µL; tiempo de protrombina y TTPa dentro de rango.","respuesta":"Púrpura","explicacion":"Máculas violáceas no blanqueables. Clínico acompañado de estudio etiológico.","fija":"La púrpura no desaparece con la presión.","href":"banco.html?caso=99"},"100":{"id":100,"tipo":"banco","titulo":"Púrpura","tema":"Púrpura","frente":"Paciente mujer de 42 años acude al Servicio de Dermatología del Hospital María Auxiliadora por una semana de evolución. Presenta manchas rojizo-purpúreas de aparición espontánea en miembros inferiores y antebrazos. Refiere evolución de una semana, sin prurito ni dolor intenso. Al examen físico se observan lesiones purpúricas de tamaño variable, no blanqueables, algunas con tendencia a confluir. No se evidencian pequeñas elevaciones con contenido líquido claro ni pequeñas elevaciones con contenido purulento. En la inspección se observan cambios planos de coloración, de aspecto rojizo-purpúreas y de contorno nítido; se observan en varias regiones corporales. Presión arterial 114/68 mmHg, afebril. Hemograma sin anemia ni leucocitosis, con plaquetas 210 000/µL. Las lesiones no blanquean a la digitopresión.","respuesta":"Púrpura","explicacion":"Máculas violáceas no blanqueables. Clínico acompañado de estudio etiológico.","fija":"La púrpura no desaparece con la presión.","href":"banco.html?caso=100"},"101":{"id":101,"tipo":"banco","titulo":"Púrpura","tema":"Púrpura","frente":"Paciente mujer de 26 años acude al Servicio de Dermatología del Hospital Nacional Arzobispo Loayza por aparición progresiva durante las últimas cuatro semanas. Consulta por lesiones rojo-rojizo-purpúreas múltiples en ambas piernas, de inicio reciente, acompañadas de leve artralgia. Las lesiones son simétricas, no desaparecen con la presión y algunas se palpan discretamente elevadas. No presenta fiebre ni compromiso del estado general. En la inspección se observan cambios planos de coloración, de aspecto rojizo-purpúreas y de contorno nítido; se observan en varias regiones corporales. Se encuentra hemodinámicamente estable. Hemograma: hemoglobina 12,8 g/dL, leucocitos 7 400/µL y plaquetas 238 000/µL; tiempo de protrombina y TTPa dentro de rango.","respuesta":"Púrpura","explicacion":"Máculas violáceas no blanqueables. Clínico acompañado de estudio etiológico.","fija":"La púrpura no desaparece con la presión.","href":"banco.html?caso=101"},"102":{"id":102,"tipo":"banco","titulo":"Petequias","tema":"Petequias","frente":"Paciente varón de 50 años acude al Servicio de Dermatología del Hospital Nacional Hipólito Unanue por tres semanas de evolución. Presenta múltiples puntos rojo-violáceos de pocos milímetros que no desaparecen a la presión. En la inspección se observan cambios planos de coloración, de aspecto rojizo-purpúreas y de contorno nítido; se observan en varias regiones corporales. Hemograma: hemoglobina 11,9 g/dL, leucocitos 6 900/µL y plaquetas 42 000/µL; TP y TTPa sin prolongación significativa. Se mantiene hemodinámicamente estable.","respuesta":"Petequias","explicacion":"Máculas purpúricas puntiformes generalmente menores de pocos milímetros. Clínico y evaluación etiológica.","fija":"Petequia = púrpura puntiforme no blanqueable.","href":"banco.html?caso=102"},"103":{"id":103,"tipo":"banco","titulo":"Petequias","tema":"Petequias","frente":"Paciente mujer de 63 años acude al Servicio de Dermatología del Hospital Nacional Arzobispo Loayza por dos meses de evolución. Desarrolla numerosas lesiones puntiformes no blanqueables en extremidades. En la inspección se observan cambios planos de coloración, de aspecto rojizo-purpúreas y de contorno nítido; se observan en varias regiones corporales. Presión arterial 110/70 mmHg y afebril. El hemograma muestra trombocitopenia de 58 000/µL, sin leucocitosis y sin sangrado activo.","respuesta":"Petequias","explicacion":"Máculas purpúricas puntiformes generalmente menores de pocos milímetros. Clínico y evaluación etiológica.","fija":"Petequia = púrpura puntiforme no blanqueable.","href":"banco.html?caso=103"},"104":{"id":104,"tipo":"banco","titulo":"Granuloma anular","tema":"Granuloma anular","frente":"Paciente mujer de 38 años acude al Servicio de Dermatología del Hospital Nacional Edgardo Rebagliati Martins por ocho meses de evolución con exacerbaciones periódicas. Presenta anillo de pequeñas elevaciones sólidas color piel en dorso de mano sin descamación. En la inspección se observan pequeñas elevaciones sólidas, de aspecto del mismo tono que la piel circundante y elevados; se limitan a una región anatómica.","respuesta":"Granuloma anular","explicacion":"Pápulas firmes que forman configuraciones anulares sin descamación. Clínico; biopsia si existe duda.","fija":"Anillo sin escama periférica favorece granuloma anular frente a tiña.","href":"banco.html?caso=104"},"105":{"id":105,"tipo":"banco","titulo":"Granuloma anular","tema":"Granuloma anular","frente":"Paciente mujer de 45 años acude al Servicio de Dermatología del Hospital Nacional Hipólito Unanue por seis meses de evolución progresiva. Presenta lesión anular asintomática formada por pequeñas pequeñas elevaciones sólidas y centro aparentemente normal. En la inspección se observan pequeñas elevaciones sólidas, de aspecto del mismo tono que la piel circundante y elevados; se limitan a una región anatómica.","respuesta":"Granuloma anular","explicacion":"Pápulas firmes que forman configuraciones anulares sin descamación. Clínico; biopsia si existe duda.","fija":"Anillo sin escama periférica favorece granuloma anular frente a tiña.","href":"banco.html?caso=105"},"106":{"id":106,"tipo":"banco","titulo":"Eczema numular","tema":"Eczema numular","frente":"Paciente mujer de 38 años acude al Servicio de Dermatología del Hospital María Auxiliadora por ocho meses de evolución con exacerbaciones periódicas. Presenta áreas cutáneas sobreelevadas de superficie amplia redondas en forma de moneda, intensamente pruriginosas, en extremidades. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de contorno nítido; se limitan a una región anatómica.","respuesta":"Eczema numular","explicacion":"Placas redondas eritematosas, descamativas o exudativas. Clínico.","fija":"Placa eccematosa con forma de moneda.","href":"banco.html?caso=106"},"107":{"id":107,"tipo":"banco","titulo":"Eczema numular","tema":"Eczema numular","frente":"Paciente mujer de 32 años acude al Servicio de Dermatología del Hospital Nacional Dos de Mayo por seis meses de evolución progresiva. Con xerosis desarrolla múltiples áreas cutáneas sobreelevadas de superficie amplia eccematosas circulares de contorno nítido. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de contorno nítido; se limitan a una región anatómica.","respuesta":"Eczema numular","explicacion":"Placas redondas eritematosas, descamativas o exudativas. Clínico.","fija":"Placa eccematosa con forma de moneda.","href":"banco.html?caso=107"},"108":{"id":108,"tipo":"banco","titulo":"Liquen simple crónico","tema":"Liquen simple crónico","frente":"Paciente mujer de 42 años acude al Servicio de Dermatología del Hospital Nacional Edgardo Rebagliati Martins por ocho meses de evolución con exacerbaciones periódicas. Con prurito crónico presenta área cutánea sobreelevada de superficie amplia engrosada con acentuación de los pliegues cutáneos. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto marrón más oscuro que la piel vecina y de contorno nítido; se limitan a una región anatómica.","respuesta":"Liquen simple crónico","explicacion":"Placa engrosada y liquenificada con líneas cutáneas acentuadas. Clínico.","fija":"Liquenificación = rascado crónico.","href":"banco.html?caso=108"},"109":{"id":109,"tipo":"banco","titulo":"Liquen simple crónico","tema":"Liquen simple crónico","frente":"Paciente mujer de 25 años acude al Servicio de Dermatología del Hospital Nacional Edgardo Rebagliati Martins por seis meses de evolución progresiva. Refiere rascar repetidamente la nuca y presenta área más oscura que la piel vecina liquenificada. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto marrón más oscuro que la piel vecina y de contorno nítido; se limitan a una región anatómica.","respuesta":"Liquen simple crónico","explicacion":"Placa engrosada y liquenificada con líneas cutáneas acentuadas. Clínico.","fija":"Liquenificación = rascado crónico.","href":"banco.html?caso=109"},"110":{"id":110,"tipo":"banco","titulo":"Prúrigo nodular","tema":"Prúrigo nodular","frente":"Paciente mujer de 38 años acude al Servicio de Dermatología del Hospital Nacional Arzobispo Loayza por ocho meses de evolución con exacerbaciones periódicas. Presenta múltiples lesiones sólidas profundas y palpables hiperqueratósicos intensamente pruriginosos en superficies extensoras. En la inspección se observan lesiones sólidas profundas y palpables, de aspecto marrón más oscuro que la piel vecina y de contorno nítido; predominan en superficies externas de las extremidades.","respuesta":"Prúrigo nodular","explicacion":"Nódulos hiperqueratósicos y excoriados. Clínico, con evaluación de causas de prurito.","fija":"Nódulos pruriginosos excoriados en extensores.","href":"banco.html?caso=110"},"111":{"id":111,"tipo":"banco","titulo":"Prúrigo nodular","tema":"Prúrigo nodular","frente":"Paciente mujer de 56 años acude al Servicio de Dermatología del Hospital Nacional Cayetano Heredia por seis meses de evolución progresiva. Con prurito crónico desarrolla lesiones sólidas profundas y palpables excoriados simétricos en brazos y piernas. En la inspección se observan lesiones sólidas profundas y palpables, de aspecto marrón más oscuro que la piel vecina y de contorno nítido; predominan en superficies externas de las extremidades.","respuesta":"Prúrigo nodular","explicacion":"Nódulos hiperqueratósicos y excoriados. Clínico, con evaluación de causas de prurito.","fija":"Nódulos pruriginosos excoriados en extensores.","href":"banco.html?caso=111"},"112":{"id":112,"tipo":"banco","titulo":"Psoriasis guttata","tema":"Psoriasis guttata","frente":"Paciente varón de 15 años acude al Servicio de Dermatología del Hospital Nacional Hipólito Unanue por tres semanas de evolución. Desarrolla numerosas pequeñas lesiones descamativas en tronco después de faringitis. En la inspección se observan pequeñas elevaciones sólidas, de aspecto rojizas y de contorno nítido; se observan en varias regiones corporales.","respuesta":"Psoriasis guttata","explicacion":"Pequeñas pápulas o placas eritematodescamativas en forma de gota. Clínico.","fija":"Psoriasis en gotas después de faringitis.","href":"banco.html?caso=112"},"113":{"id":113,"tipo":"banco","titulo":"Psoriasis guttata","tema":"Psoriasis guttata","frente":"Paciente varón de 15 años acude al Servicio de Dermatología del Hospital Nacional Daniel Alcides Carrión por dos meses de evolución. Joven presenta erupción súbita de múltiples pequeñas elevaciones sólidas eritematodescamativas en forma de gotas. En la inspección se observan pequeñas elevaciones sólidas, de aspecto rojizas y de contorno nítido; se observan en varias regiones corporales.","respuesta":"Psoriasis guttata","explicacion":"Pequeñas pápulas o placas eritematodescamativas en forma de gota. Clínico.","fija":"Psoriasis en gotas después de faringitis.","href":"banco.html?caso=113"},"114":{"id":114,"tipo":"banco","titulo":"Psoriasis inversa","tema":"Psoriasis inversa","frente":"Paciente varón de 34 años acude al Servicio de Dermatología del Hospital Nacional Daniel Alcides Carrión por tres semanas de evolución. Con psoriasis conocida presenta áreas cutáneas sobreelevadas de superficie amplia rojas lisas y brillantes en axilas e ingles, con poca escama. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de contorno nítido; predominan en pliegues de flexión.","respuesta":"Psoriasis inversa","explicacion":"Placas eritematosas lisas, brillantes y con poca descamación. Clínico.","fija":"Psoriasis de pliegues puede casi no tener escama.","href":"banco.html?caso=114"},"115":{"id":115,"tipo":"banco","titulo":"Psoriasis inversa","tema":"Psoriasis inversa","frente":"Paciente mujer de 51 años acude al Servicio de Dermatología del Hospital Nacional Hipólito Unanue por dos meses de evolución. Presenta lesiones rojizas de contorno nítido en pliegues inframamarios y genitales. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de contorno nítido; predominan en pliegues de flexión.","respuesta":"Psoriasis inversa","explicacion":"Placas eritematosas lisas, brillantes y con poca descamación. Clínico.","fija":"Psoriasis de pliegues puede casi no tener escama.","href":"banco.html?caso=115"},"116":{"id":116,"tipo":"banco","titulo":"Sífilis secundaria","tema":"Sífilis secundaria","frente":"Paciente varón de 24 años acude al Servicio de Dermatología del Hospital Nacional Daniel Alcides Carrión por cuatro días de evolución y progresión reciente. Presenta exantema generalizado no pruriginoso que compromete palmas y plantas. En la inspección se observan cambios planos de coloración, de aspecto rojizas y de contorno nítido; se observan en varias regiones corporales. Refiere adenopatías generalizadas y antecedente de una lesión genital indolora semanas antes. RPR reactivo 1:64 y prueba treponémica confirmatoria positiva.","respuesta":"Sífilis secundaria","explicacion":"Exantema macular o papular de distribución generalizada. Pruebas treponémicas y no treponémicas.","fija":"Exantema palmoplantar debe hacer recordar sífilis secundaria.","href":"banco.html?caso=116"},"117":{"id":117,"tipo":"banco","titulo":"Sífilis secundaria","tema":"Sífilis secundaria","frente":"Paciente varón de 35 años acude al Servicio de Dermatología del Hospital Nacional Arzobispo Loayza por siete días de evolución. Con antecedente sexual de riesgo presenta lesiones maculopapulares difusas, adenopatías y compromiso palmoplantar. En la inspección se observan cambios planos de coloración, de aspecto rojizas y de contorno nítido; se observan en varias regiones corporales. Se encuentra afebril y hemodinámicamente estable. Presenta adenopatías cervicales e inguinales; VDRL reactivo y prueba treponémica positiva.","respuesta":"Sífilis secundaria","explicacion":"Exantema macular o papular de distribución generalizada. Pruebas treponémicas y no treponémicas.","fija":"Exantema palmoplantar debe hacer recordar sífilis secundaria.","href":"banco.html?caso=117"},"118":{"id":118,"tipo":"banco","titulo":"Herpes zóster oftálmico","tema":"Herpes zóster oftálmico","frente":"Paciente mujer de 72 años acude al Servicio de Dermatología del Hospital María Auxiliadora por cuatro días de evolución y progresión reciente. Presenta dolor y pequeñas elevaciones con contenido líquido claro en frente unilateral con compromiso de punta nasal. En la inspección se observan pequeñas elevaciones con contenido líquido claro, de aspecto rojizas y de contorno nítido; siguen una banda unilateral correspondiente a un territorio sensitivo. La agudeza visual está discretamente disminuida en el ojo afectado y refiere dolor ocular. Se observa compromiso de la punta nasal, por lo que se solicita valoración oftalmológica urgente.","respuesta":"Herpes zóster oftálmico","explicacion":"Vesículas agrupadas en territorio V1. Clínico, con valoración oftalmológica cuando existe riesgo ocular.","fija":"Lesión en punta nasal puede indicar afectación nasociliar y mayor riesgo ocular.","href":"banco.html?caso=118"},"119":{"id":119,"tipo":"banco","titulo":"Herpes zóster oftálmico","tema":"Herpes zóster oftálmico","frente":"Paciente varón de 64 años acude al Servicio de Dermatología del Hospital Nacional Cayetano Heredia por siete días de evolución. Presenta erupción vesicular dolorosa en territorio de la primera rama del trigémino. En la inspección se observan pequeñas elevaciones con contenido líquido claro, de aspecto rojizas y de contorno nítido; siguen una banda unilateral correspondiente a un territorio sensitivo. Presenta fotofobia y dolor ocular ipsilateral. La erupción respeta la línea media y compromete el territorio de la primera rama del trigémino.","respuesta":"Herpes zóster oftálmico","explicacion":"Vesículas agrupadas en territorio V1. Clínico, con valoración oftalmológica cuando existe riesgo ocular.","fija":"Lesión en punta nasal puede indicar afectación nasociliar y mayor riesgo ocular.","href":"banco.html?caso=119"},"120":{"id":120,"tipo":"banco","titulo":"Ectima","tema":"Ectima","frente":"Paciente varón de 31 años acude al Servicio de Dermatología del Hospital María Auxiliadora por cuatro días de evolución y progresión reciente. Presenta lesión costrosa profunda en pierna que al desprenderse revela una pérdida profunda de sustancia cutánea. En la inspección se observan pérdidas profundas de sustancia cutánea, de aspecto rojizas y de contorno nítido; se limitan a una región anatómica.","respuesta":"Ectima","explicacion":"Úlcera superficial cubierta por costra gruesa. Clínico; cultivo en casos seleccionados.","fija":"Ectima es un impétigo más profundo y ulcerativo.","href":"banco.html?caso=120"},"121":{"id":121,"tipo":"banco","titulo":"Ectima","tema":"Ectima","frente":"Paciente mujer de 55 años acude al Servicio de Dermatología del Hospital Nacional Dos de Mayo por siete días de evolución. En malas condiciones higiénicas presenta pérdidas profundas de sustancia cutánea superficiales cubiertas por costras gruesas. En la inspección se observan pérdidas profundas de sustancia cutánea, de aspecto rojizas y de contorno nítido; se limitan a una región anatómica.","respuesta":"Ectima","explicacion":"Úlcera superficial cubierta por costra gruesa. Clínico; cultivo en casos seleccionados.","fija":"Ectima es un impétigo más profundo y ulcerativo.","href":"banco.html?caso=121"},"122":{"id":122,"tipo":"banco","titulo":"Onicomicosis","tema":"Onicomicosis","frente":"Paciente mujer de 57 años acude al Servicio de Dermatología del Hospital Nacional Edgardo Rebagliati Martins por ocho meses de evolución con exacerbaciones periódicas. Presenta uña del primer dedo del pie engrosada, amarillo-dorada y quebradiza. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto amarillo-doradas y de transición gradual hacia la piel vecina; se limitan a una región anatómica.","respuesta":"Onicomicosis","explicacion":"Engrosamiento, decoloración, friabilidad y detritos subungueales. Confirmación micológica antes de terapia sistémica cuando sea posible.","fija":"No toda uña amarilla es hongo: conviene confirmación micológica.","href":"banco.html?caso=122"},"123":{"id":123,"tipo":"banco","titulo":"Onicomicosis","tema":"Onicomicosis","frente":"Paciente varón de 22 años acude al Servicio de Dermatología del Hospital Nacional Hipólito Unanue por seis meses de evolución progresiva. Presenta hiperqueratosis subungueal, decoloración y onicólisis progresiva. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto amarillo-doradas y de transición gradual hacia la piel vecina; se limitan a una región anatómica.","respuesta":"Onicomicosis","explicacion":"Engrosamiento, decoloración, friabilidad y detritos subungueales. Confirmación micológica antes de terapia sistémica cuando sea posible.","fija":"No toda uña amarilla es hongo: conviene confirmación micológica.","href":"banco.html?caso=123"},"124":{"id":124,"tipo":"banco","titulo":"Psoriasis ungueal","tema":"Psoriasis ungueal","frente":"Paciente varón de 22 años acude al Servicio de Dermatología del Hospital Nacional Daniel Alcides Carrión por ocho meses de evolución con exacerbaciones periódicas. Con psoriasis presenta múltiples depresiones puntiformes en lámina ungueal. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto amarillo-doradas y de transición gradual hacia la piel vecina; se limitan a una región anatómica.","respuesta":"Psoriasis ungueal","explicacion":"Pitting, onicólisis, hiperqueratosis subungueal y manchas de aceite. Clínico.","fija":"Pitting y mancha de aceite son pistas clásicas.","href":"banco.html?caso=124"},"125":{"id":125,"tipo":"banco","titulo":"Psoriasis ungueal","tema":"Psoriasis ungueal","frente":"Paciente mujer de 48 años acude al Servicio de Dermatología del Hospital Nacional Cayetano Heredia por seis meses de evolución progresiva. Presenta onicólisis y mancha de aceite junto con lesiones psoriásicas cutáneas. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto amarillo-doradas y de transición gradual hacia la piel vecina; se limitan a una región anatómica.","respuesta":"Psoriasis ungueal","explicacion":"Pitting, onicólisis, hiperqueratosis subungueal y manchas de aceite. Clínico.","fija":"Pitting y mancha de aceite son pistas clásicas.","href":"banco.html?caso=125"},"126":{"id":126,"tipo":"banco","titulo":"Intertrigo","tema":"Intertrigo","frente":"Paciente mujer de 67 años acude al Servicio de Dermatología del Hospital Nacional Dos de Mayo por tres semanas de evolución. Obeso presenta enrojecimiento y maceración simétrica en pliegues abdominales por humedad y fricción. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de transición gradual hacia la piel vecina; predominan en pliegues de flexión.","respuesta":"Intertrigo","explicacion":"Placa eritematosa y macerada. Clínico.","fija":"Primero piense en humedad y fricción; luego descarte sobreinfección.","href":"banco.html?caso=126"},"127":{"id":127,"tipo":"banco","titulo":"Intertrigo","tema":"Intertrigo","frente":"Paciente mujer de 25 años acude al Servicio de Dermatología del Hospital Nacional Daniel Alcides Carrión por dos meses de evolución. Presenta irritación dolorosa en pliegue submamario sin pequeñas elevaciones con contenido purulento satélite. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto rojizas y de transición gradual hacia la piel vecina; predominan en pliegues de flexión.","respuesta":"Intertrigo","explicacion":"Placa eritematosa y macerada. Clínico.","fija":"Primero piense en humedad y fricción; luego descarte sobreinfección.","href":"banco.html?caso=127"},"128":{"id":128,"tipo":"banco","titulo":"Eritrasma","tema":"Eritrasma","frente":"Paciente mujer de 49 años acude al Servicio de Dermatología del Hospital Nacional Dos de Mayo por tres semanas de evolución. Presenta área cutánea sobreelevada de superficie amplia marrón rojiza poco sintomática en pliegue inguinal. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto marrones y de contorno nítido; predominan en pliegues de flexión.","respuesta":"Eritrasma","explicacion":"Placas marrón-rojizas bien delimitadas con descamación fina. Lámpara de Wood puede mostrar fluorescencia coral-roja.","fija":"Fluorescencia coral-roja con Wood.","href":"banco.html?caso=128"},"129":{"id":129,"tipo":"banco","titulo":"Eritrasma","tema":"Eritrasma","frente":"Paciente varón de 60 años acude al Servicio de Dermatología del Hospital María Auxiliadora por dos meses de evolución. Con diabetes presenta lesiones marrones finamente descamativas en axilas. En la inspección se observan áreas sobreelevadas de superficie amplia, de aspecto marrones y de contorno nítido; predominan en pliegues de flexión.","respuesta":"Eritrasma","explicacion":"Placas marrón-rojizas bien delimitadas con descamación fina. Lámpara de Wood puede mostrar fluorescencia coral-roja.","fija":"Fluorescencia coral-roja con Wood.","href":"banco.html?caso=129"},"130":{"id":130,"tipo":"banco","titulo":"Pitiriasis alba","tema":"Pitiriasis alba","frente":"Paciente varón de 12 años acude al Servicio de Dermatología del Hospital Nacional Dos de Mayo por tres semanas de evolución. Con piel seca presenta cambios planos de coloración más claras que la piel circundante de transición gradual hacia la piel vecina en mejillas. En la inspección se observan cambios planos de coloración, de aspecto más claras que la piel circundante y de transición gradual hacia la piel vecina; se limitan a una región anatómica. Se encuentra afebril, activo para la edad y hemodinámicamente estable, sin signos de compromiso sistémico.","respuesta":"Pitiriasis alba","explicacion":"Máculas hipopigmentadas mal delimitadas con descamación fina. Clínico.","fija":"Pitiriasis alba es hipopigmentada y mal delimitada; vitíligo es acrómico y más definido.","href":"banco.html?caso=130"},"131":{"id":131,"tipo":"banco","titulo":"Pitiriasis alba","tema":"Pitiriasis alba","frente":"Paciente mujer de 11 años acude al Servicio de Dermatología del Instituto Nacional de Salud del Niño San Borja por dos meses de evolución. Presenta manchas claras faciales con fina descamación, más evidentes después del verano. En la inspección se observan cambios planos de coloración, de aspecto más claras que la piel circundante y de transición gradual hacia la piel vecina; se limitan a una región anatómica. Se encuentra afebril, activo para la edad y hemodinámicamente estable, sin signos de compromiso sistémico.","respuesta":"Pitiriasis alba","explicacion":"Máculas hipopigmentadas mal delimitadas con descamación fina. Clínico.","fija":"Pitiriasis alba es hipopigmentada y mal delimitada; vitíligo es acrómico y más definido.","href":"banco.html?caso=131"},"132":{"id":132,"tipo":"banco","titulo":"Hiperpigmentación postinflamatoria","tema":"Hiperpigmentación postinflamatoria","frente":"Paciente mujer de 26 años acude al Servicio de Dermatología del Hospital Nacional Edgardo Rebagliati Martins por ocho meses de evolución con exacerbaciones periódicas. Presenta manchas oscuras persistentes en sitios donde previamente tuvo acné inflamatorio. En la inspección se observan cambios planos de coloración, de aspecto marrón más oscuro que la piel vecina y de transición gradual hacia la piel vecina; se limitan a una región anatómica.","respuesta":"Hiperpigmentación postinflamatoria","explicacion":"Máculas o parches hiperpigmentados en áreas previamente inflamadas. Clínico.","fija":"La historia de una lesión inflamatoria previa es la pista.","href":"banco.html?caso=132"},"133":{"id":133,"tipo":"banco","titulo":"Hiperpigmentación postinflamatoria","tema":"Hiperpigmentación postinflamatoria","frente":"Paciente mujer de 39 años acude al Servicio de Dermatología del Hospital Nacional Cayetano Heredia por seis meses de evolución progresiva. Después de un episodio de dermatitis, paciente conserva cambios planos de coloración marrones residuales. En la inspección se observan cambios planos de coloración, de aspecto marrón más oscuro que la piel vecina y de transición gradual hacia la piel vecina; se limitan a una región anatómica.","respuesta":"Hiperpigmentación postinflamatoria","explicacion":"Máculas o parches hiperpigmentados en áreas previamente inflamadas. Clínico.","fija":"La historia de una lesión inflamatoria previa es la pista.","href":"banco.html?caso=133"}}};
